INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('py-r1', 'py', 'متغیرها، تایپ‌ها و مدل ذهنی پایتون', 50, 1, '[{"k":"p","t":"پایتون قبل از هر چیز یک مدل ذهنی است: در پایتون «متغیر» جعبه نیست، بلکه برچسبی است که به یک شیء در حافظه می‌چسبد. تا این تصویر را درست نسازی، رفتارهایی مثل «چرا دو لیست با هم عوض شدند» برایت غیرقابل توضیح می‌ماند."},{"k":"h","t":"متغیر یعنی برچسب، نه جعبه"},{"k":"p","t":"در زبان‌هایی مثل C متغیر یک خانه حافظه با اندازه ثابت است. در پایتون اما هر مقدار یک «شیء» است در جایی از حافظه، و متغیر فقط نامی است که به آن اشاره می‌کند. وقتی می‌نویسی a = 5 و بعد b = a، عدد کپی نمی‌شود؛ حالا دو برچسب به همان شیء اشاره می‌کنند. برای اعداد و رشته‌ها این بی‌خطر است چون تغییرناپذیرند، ولی برای لیست و دیکشنری همین یک خط، سرچشمه معروف‌ترین باگ‌های پایتون است."},{"k":"h","t":"تایپ پویا اما قوی"},{"k":"p","t":"پایتون «پویا» است چون لازم نیست نوع را اعلام کنی و یک متغیر می‌تواند در زمان‌های مختلف به شیءهای متفاوت اشاره کند؛ اما «قوی» است چون هرگز به‌طور پنهان یک رشته را با عدد جمع نمی‌کند و به‌جای حدس‌زدن، خطای TypeError می‌دهد. این ترکیب یعنی سرعت توسعه بالا بدون باج‌دادن به ابهام. ابزار type hint که از نسخه ۳٫۵ اضافه شد، اجازه می‌دهد همان خوانایی تایپ ایستا را هم به کد بیاوری بدون اینکه رفتار زمان اجرای برنامه تغییر کند."},{"k":"h","t":"تغییرپذیر در برابر تغییرناپذیر"},{"k":"p","t":"رشته، عدد و تاپل تغییرناپذیرند: هر عملی که بخواهد محتوایشان را عوض کند، در واقع شیء جدیدی می‌سازد. لیست، دیکشنری و مجموعه تغییرپذیرند: می‌توانند درجا تغییر کنند. این تمایز تعیین می‌کند چه زمانی داده به‌صورت غیرمنتظره «به‌اشتراک‌گذاشته‌شده» رفتار می‌کند. قاعده عملی: هر وقت یک ساختار تغییرپذیر را به تابعی می‌دهی یا از جایی کپی می‌کنی، درباره اینکه آیا داری همان شیء را می‌فرستی یا یک کپی مستقل، آگاهانه تصمیم بگیر."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"alias.py","code":"a = [1, 2, 3]\nb = a            # b برچسب دوم روی همان لیست است\nb.append(4)\nprint(a)         # [1, 2, 3, 4]  ← a هم تغییر کرد!\n\nc = a.copy()     # حالا یک کپی مستقل\nc.append(5)\nprint(a)         # [1, 2, 3, 4]  ← a دست‌نخورده ماند\n\n# برای ساختارهای تودرتو، copy سطحی کافی نیست:\nimport copy\nm = [[1], [2]]\nn = copy.deepcopy(m)\nn[0].append(99)\nprint(m[0])      # [1] ← deepcopy واقعاً مستقل است"},{"k":"list","items":["خط b = a هیچ داده‌ای کپی نمی‌کند؛ فقط یک برچسب دوم می‌سازد. پس تغییر b روی a هم دیده می‌شود.","متد copy() یک لیست جدید با همان عناصر می‌سازد؛ برای لیست یک‌سطحی همین کافی است تا استقلال به دست آید.","وقتی عناصر خودشان لیست باشند (تودرتو)، copy سطحی باز هم درونی‌ها را به‌اشتراک می‌گذارد؛ deepcopy همه سطوح را بازسازی می‌کند.","این الگو یعنی «ارجاع در برابر کپی» پایه درک حافظه در همه زبان‌هاست؛ پایتون فقط آن را قابل‌مشاهده می‌کند."]},{"k":"def","term":"ارجاع (Reference)","t":"متغیر در پایتون مستقیماً داده را نگه نمی‌دارد؛ به یک شیء در حافظه اشاره می‌کند. چند متغیر می‌توانند همزمان به یک شیء ارجاع دهند و هویت یک شیء با تابع id() قابل بررسی است؛ دو متغیر وقتی is باشند یعنی دقیقاً به یک شیء اشاره می‌کنند."},{"k":"table","head":["نوع","تغییرپذیری","مثال","نکته"],"rows":[["int / float","تغییرناپذیر","x = 10","هر محاسبه شیء جدید می‌سازد"],["str","تغییرناپذیر","s = ''abc''","s += ''d'' شیء جدید است"],["tuple","تغییرناپذیر","t = (1, 2)","برای کلید دیکشنری مناسب است"],["list","تغییرپذیر","l = [1, 2]","درجا اضافه/حذف می‌شود"],["dict / set","تغییرپذیر","d = {''a'': 1}","کلیدها باید تغییرناپذیر باشند"]]},{"k":"warn","title":"دام رایج","t":"استفاده از is به‌جای == برای مقایسه مقدار. عملگر is هویت دو شیء را می‌سنجد نه برابری محتوایشان؛ دو لیست با محتوای یکسان == هستند ولی is نیستند. is را فقط برای مقایسه با None به کار ببر."},{"k":"tip","title":"نکته حرفه‌ای","t":"وقتی شک داری داده به‌اشتراک گذاشته شده یا نه، id() دو متغیر را چاپ کن؛ اگر یکسان بود هر دو به یک شیء نگاه می‌کنند. این یک خط، ساعت‌ها دیباگ را نجات می‌دهد."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["متغیر پایتون برچسبی روی شیء است، نه ظرفی برای داده","پایتون پویا ولی قوی است؛ تبدیل نوع پنهان انجام نمی‌دهد","ساختارهای تغییرپذیر (لیست، دیکشنری) به‌اشتراک گذاشته می‌شوند مگر کپی شوند","برای برابری مقدار از == و فقط برای None از is استفاده کن"]}]'::jsonb, '[{"q":"چرا بعد از b = a و تغییر b، مقدار a هم عوض شد؟","opts":["پایتون باگ دارد","چون هر دو متغیر به یک شیء ارجاع می‌دهند و لیست تغییرپذیر است","چون a و j اشتباه تایپ شده","چون پایتون مقادیر را جابه‌جا می‌کند"],"ans":1,"why":"b = a برچسب دوم روی همان شیء است؛ تغییر درجا از هر برچسبی، برای هر دو دیده می‌شود."},{"q":"کدام گزینه درباره رشته‌ها درست است؟","opts":["درجا تغییر می‌کنند","تغییرناپذیرند؛ هر عملیات، شیء جدید می‌سازد","با list() یکی‌اند","نمی‌توانند کلید دیکشنری باشند"],"ans":1,"why":"str تغییرناپذیر است؛ s += ''x'' در واقع یک رشته تازه می‌سازد و برچسب را به آن وصل می‌کند."},{"q":"copy() و deepcopy() چه فرقی دارند؟","opts":["هیچ","copy سطحی است و درونی‌های تودرتو را به‌اشتراک می‌گذارد؛ deepcopy همه سطوح را مستقل کپی می‌کند","deepcopy کندتر اما فقط برای عدد","copy فقط برای دیکشنری است"],"ans":1,"why":"در داده تودرتو، copy سطحی هنوز زیرساختارها را به‌اشتراک می‌گذارد؛ deepcopy بازگشتی عمل می‌کند."}]'::jsonb),
('py-r2', 'py', 'ساختارهای کنترل جریان و خوانایی کد', 45, 2, '[{"k":"p","t":"کدی که درست کار می‌کند اما خوانده نمی‌شود، عملاً اشتباه است؛ چون نفر بعدی (که شاید خودِ سه‌ماهه‌بعدِ تو باشد) نمی‌تواند با اطمینان تغییرش بدهد. کنترل جریان در پایتون به‌عمد طوری طراحی شده که خواندنش شبیه خواندن متن باشد."},{"k":"h","t":"if و فلسفه تورفتگی"},{"k":"p","t":"پایتون بلوک‌ها را نه با آکولاد بلکه با تورفتگی مشخص می‌کند؛ این یک اجبار زیبایی نیست، یک تصمیم مهندسی است: ساختار بصری کد با ساختار منطقی‌اش یکی می‌شود و کدِ «ظاهراً داخل حلقه ولی واقعاً بیرون» که در زبان‌های آکولادی فراوان است، غیرممکن می‌شود. بهای این تصمیم، نیاز به نظم همیشگی است؛ یک فاصله نابجا یا ترکیب تب و فاصله، معنای برنامه را عوض می‌کند یا خطای IndentationError می‌دهد."},{"k":"h","t":"حلقه‌ها و دستور else"},{"k":"p","t":"for در پایتون روی هر چیزی که «پیمایش‌پذیر» باشد کار می‌کند: لیست، رشته، فایل، بازه. یکی از قابلیت‌های کمترشناخته‌شده، else روی حلقه است: بلوک else فقط وقتی اجرا می‌شود که حلقه بدون رسیدن به break تمام شده باشد. این یعنی «اگر وسط راه چیزی پیدا نشد» را بدون هیچ پرچم کمکی می‌توان نوشت؛ الگویی که در جست‌وجوها کد را به‌طور محسوسی تمیز می‌کند."},{"k":"h","t":"List Comprehension؛ قدرت با مهار"},{"k":"p","t":"کامپری‌هنشن یعنی ساختن یک لیست جدید از یک پیمایش، در یک عبارت خوانا: به‌جای چهار خط حلقه و append، یک خط که نیت را فریاد می‌زند. اما قدرت بدون مهار ضدخود است؛ کامپری‌هنشنِ تودرتو یا طولانی از حلقه ساده ناخواناتر است. قاعده سرانگشتی: اگر عبارت بیشتر از یک for و یک شرط ساده دارد یا از یک خط صفحه رد می‌شود، آن را به حلقه یا تابع تبدیل کن."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"flow.py","code":"# else روی حلقه: «اگر پیدا نشد»\ndef find_even(nums):\n    for n in nums:\n        if n % 2 == 0:\n            return n\n    else:\n        return None      # حلقه بدون break/return تمام شد\n\n# comprehension خوانا\nsquares = [n * n for n in range(10) if n % 2 == 0]\n\n# همان با حلقه — طولانی‌تر ولی گاهی واضح‌تر\nsquares2 = []\nfor n in range(10):\n    if n % 2 == 0:\n        squares2.append(n * n)"},{"k":"list","items":["بلوک else بعد از for فقط وقتی اجرا می‌شود که حلقه کامل پیموده شود؛ چون return مسیر را ترک می‌کند، else یعنی «چیزی پیدا نشد».","کامپری‌هنشن squares دقیقاً معادل حلقه پایین است ولی نیت (ساختن لیست جدید) را در یک نگاه می‌رساند.","فیلتر if داخل comprehension جایگزین if داخل حلقه است؛ ترتیب خواندن: خروجی، سپس پیمایش، سپس شرط."]},{"k":"def","term":"پیمایش‌پذیر (Iterable)","t":"هر چیزی که بتوان عناصرش را یکی‌یکی گرفت؛ لیست، رشته، دیکشنری، فایل و range. حلقه for با گرفتن یک «تکرارکننده» از پیمایش‌پذیر کار می‌کند؛ دانستن این تمایز توضیح می‌دهد چرا بعضی ساختارها چندبار پیمایش می‌شوند و بعضی (مثل نتیجه map یا فایل) فقط یک‌بار."},{"k":"table","head":["ساختار","کی استفاده کنیم","نکته"],"rows":[["if / elif / else","تصمیم بین مسیرها","ترتیب شرط‌ها از خاص به عام"],["for","پیمایش تعداد/مجموعه مشخص","else یعنی «بدون توقف تمام شد»"],["while","تکرار تا شرطی که نامشخص است کی برقرار می‌شود","حتماً راه خروج داشته باشد"],["comprehension","ساختن مجموعه جدید از مجموعه دیگر","یک for و یک شرط؛ نه بیشتر"]]},{"k":"warn","title":"دام رایج","t":"تغییر لیست هنگام پیمایشش با for — حذف عنصر وسط پیمایش، ایندکس‌ها را جابه‌جا می‌کند و عناصری جا می‌مانند. راه درست: پیمایش روی کپی (for x in list(l)) یا ساختن لیست جدید با comprehension."},{"k":"tip","title":"نکته حرفه‌ای","t":"برای شمارش از range(len(l)) استفاده نکن؛ enumerate ایندکس و مقدار را با هم می‌دهد و کد را هم کوتاه‌تر و هم خواناتر می‌کند."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["تورفتگی در پایتون ساختار منطقی کد است، نه تزئین","else روی حلقه یعنی «حلقه بدون break تمام شد»","comprehension برای ساختن مجموعه جدید عالی است، نه برای هر حلقه‌ای","هنگام پیمایش، لیست را درجا تغییر نده"]}]'::jsonb, '[{"q":"بلوک else بعد از حلقه for چه زمانی اجرا می‌شود؟","opts":["همیشه","فقط وقتی حلقه بدون break به پایان برسد","فقط وقتی حلقه خالی باشد","هرگز"],"ans":1,"why":"else مکمل break است؛ اگر حلقه با break متوقف شود else اجرا نمی‌شود، پس معنای «پیدا نشد» می‌دهد."},{"q":"چرا پایتون به‌جای آکولاد از تورفتگی استفاده می‌کند؟","opts":["چون آکولاد نداشت","تا ساختار بصری و منطقی کد یکی شود و خطای بلوکِ اشتباه غیرممکن شود","برای سرعت اجرا","سلیقه سازنده"],"ans":1,"why":"تورفتگی اجباری، کدِ «ظاهرش داخل بلوک ولی واقعاً بیرون» را که در زبان‌های آکولادی رایج است حذف می‌کند."},{"q":"کدام استفاده از comprehension نادرست است؟","opts":["ساخت لیست مربع‌ها","فیلتر عناصر با یک شرط","جایگزینی هر حلقه‌ای حتی تودرتوی سه‌سطحی","ساخت دیکشنری با dict comprehension"],"ans":2,"why":"comprehension تودرتوی عمیق از حلقه ساده ناخواناتر است؛ هدف خوانایی است نه فشردگی."}]'::jsonb),
('py-r3', 'py', 'توابع و اصل مسئولیت واحد', 50, 3, '[{"k":"p","t":"توابع فقط راه تقسیم کد نیستند؛ واحدِ «فکر کردن» درباره برنامه‌اند. یک تابع خوب مثل یک جمله خوب است: یک فعل دارد، یک کار انجام می‌دهد و نامش دقیقاً همان کار را می‌گوید. کیفیت بقیه کدت مستقیماً از کیفیت توابع‌ت می‌آید."},{"k":"h","t":"یک تابع، یک مسئولیت"},{"k":"p","t":"وقتی یک تابع هم داده می‌خواند، هم پردازش می‌کند و هم نتیجه را چاپ می‌کند، سه دلیل برای تغییر دارد و تست‌کردنش تقریباً ناممکن است. اصل مسئولیت واحد می‌گوید هر تابع باید یک کار مشخص انجام دهد و یک دلیل برای تغییر داشته باشد. نشانه عملیِ نقض این اصل، کلمه «و» در توصیف تابع است: اگر بگویی «این تابع ورودی را می‌گیرد و اعتبارسنجی می‌کند و ذخیره می‌کند»، احتمالاً سه تابع در یک لباس داری."},{"k":"h","t":"پارامترها و مقدار پیش‌فرض خطرناک"},{"k":"p","t":"پارامترهای پیش‌فرض پایتون یک‌بار در زمان تعریف تابع ارزیابی می‌شوند، نه هر بار صدا. اگر پیش‌فرض یک شیء تغییرپذیر مثل لیست باشد، همان شیء بین همه فراخوانی‌ها به‌اشتراک می‌ماند و با هر بار صدا بزرگ‌تر می‌شود — یکی از معروف‌ترین باگ‌های پایتون. راه درست، پیش‌فرض None است و ساختن شیء جدید داخل تابع. این یک خط تفاوت، مرز بین کد قابل‌اتکا و کدی است که «یه روز یه جایی» خراب می‌شود."},{"k":"h","t":"توابع، شهروند درجه یک"},{"k":"p","t":"در پایتون تابع یک شیء است: می‌تواند داخل متغیر برود، به تابع دیگر پاس داده شود و از تابع برگردد. همین قابلیت پایه الگوهای بزرگی مثل callback، decorator و map/filter است. وقتی تابع را به‌عنوان داده ببینی، می‌توانی «رفتار» را هم مثل داده تنظیم و ترکیب کنی؛ مثلاً یک تابع validate بنویسی که اعتبارسنج‌های مختلف را به‌عنوان پارامتر می‌گیرد و بدون تغییر خودش، برای سناریوهای متفاوت استفاده می‌شود."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"func.py","code":"# ❌ پیش‌فرض تغییرپذیر — بین فراخوانی‌ها به‌اشتراک می‌ماند\ndef add_bad(item, bucket=[]):\n    bucket.append(item)\n    return bucket\nprint(add_bad(1))   # [1]\nprint(add_bad(2))   # [1, 2]  ← ۱ هنوز اینجاست!\n\n# ✓ پیش‌فرض None — هر بار لیست تازه\ndef add_ok(item, bucket=None):\n    if bucket is None:\n        bucket = []\n    bucket.append(item)\n    return bucket\n\n# تابع به‌عنوان پارامتر (رفتار قابل تنظیم)\ndef validate(value, check):\n    return ''ok'' if check(value) else ''bad''\nvalidate(''a@b.ir'', lambda v: ''@'' in v)"},{"k":"list","items":["در add_bad لیست [] فقط یک‌بار ساخته می‌شود؛ هر فراخوانی همان لیست را برمی‌گرداند و عناصر قبلی را هم دارد.","الگوی None + ساختن داخل تابع، برای هر فراخوانی یک لیست مستقل می‌سازد؛ این قاعده را برای dict و set هم رعایت کن.","تابع validate با گرفتن check به‌عنوان پارامتر، بدون اینکه بداند اعتبارسنجی چیست، برای هر قانونی کار می‌کند — این یعنی جداکردن «مکانیزم» از «سیاست»."]},{"k":"def","term":"ارزیابی پیش‌فرض در زمان تعریف","t":"عبارت‌های پیش‌فرض پارامترها وقتی تابع تعریف می‌شود (نه وقتی صدا زده می‌شود) یک‌بار ارزیابی و به تابع متصل می‌شوند. برای مقدارهای تغییرناپذیر مثل عدد و رشته بی‌خطر است، ولی برای لیست، دیکشنری و هر شیء تغییرپذیر، یک شیء مشترک بین همه فراخوانی‌ها می‌سازد."},{"k":"table","head":["نشانه تابع بد","مشکل","راه درست"],"rows":[["نامش «و» دارد","چند مسئولیت","به چند تابع تقسیم کن"],["بیش از ۳-۴ پارامتر","درهم‌تنیدگی زیاد","یک دیکشنری/کلاسِ پارامتر"],["پیش‌فرض تغییرپذیر","حالت مشترک پنهان","پیش‌فرض None"],["بدنه ۵۰+ خط","ناخوانا و غیرقابل‌تست","استخراج زیرتابع"]]},{"k":"warn","title":"دام رایج","t":"پنهان‌کردن «اثر جانبی» در تابعی که نامش قولش را نمی‌دهد؛ مثلاً تابعی به نام build_report که علاوه بر ساخت گزارش، آن را ایمیل هم می‌کند. فراخواننده انتظار ارسال ندارد و نمی‌تواند بدون ارسال، ساختن را تست کند. نام باید همه آثار را لو بدهد."},{"k":"tip","title":"نکته حرفه‌ای","t":"برای توابع کوچک از type hint و docstring یک‌خطی استفاده کن؛ نه برای ماشین، برای خودت. وقتی نتوانی در یک خط بگویی تابع چه برمی‌گرداند، یعنی هنوز مسئولیتش را درست جدا نکرده‌ای."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["هر تابع یک مسئولیت و یک دلیل برای تغییر","پیش‌فرض تغییرپذیر ممنوع؛ از None استفاده کن","توابع در پایتون شیء‌اند و می‌توانند پاس داده شوند","نام تابع باید همه کارها و آثارش را بگوید"]}]'::jsonb, '[{"q":"چرا def f(x, acc=[]) خطرناک است؟","opts":["چون لیست کند است","چون لیست پیش‌فرض یک‌بار ساخته و بین همه فراخوانی‌ها به‌اشتراک گذاشته می‌شود","چون پایتون لیست ندارد","چون [] مجاز نیست"],"ans":1,"why":"پیش‌فرض در زمان تعریف ارزیابی می‌شود؛ همان لیست بین فراخوانی‌ها می‌ماند و عناصر قبلی را حفظ می‌کند."},{"q":"نشانه عملیِ نقض مسئولیت واحد چیست؟","opts":["تعداد پارامتر صفر","وجود «و» در توصیف کار تابع","نام کوتاه","نداشتن return"],"ans":1,"why":"اگر برای گفتن کار تابع به «و» نیاز داری، احتمالاً چند مسئولیت در یک تابع جمع شده‌اند."},{"q":"«تابع شهروند درجه یک» یعنی چه؟","opts":["تابع اول فایل","تابع یک شیء است: قابل ذخیره، پاس‌دادن و برگرداندن","تابعی که ارث‌بری می‌کند","تابع داخلی"],"ans":1,"why":"تابع مثل هر داده دیگری می‌تواند داخل متغیر برود یا به تابع دیگر پاس داده شود؛ پایه callback و decorator."}]'::jsonb),
('c1-l1', 'py', 'شروع کار؛ متغیرها و اولین برنامه', 45, 4, '[{"k":"p","t":"برنامه‌نویسی یعنی دادن دستورهای دقیق و بدون ابهام به کامپیوتر. پایتون این کار را با سینتکسی انجام می‌دهد که به زبان انگلیسی روزمره شبیه است؛ به همین دلیل خواندن کد پایتون تقریباً مثل خواندن یک متن ساده است. قبل از هر چیز پایتون را نصب کنید و یک ویرایشگر مثل VS Code راه بیندازید."},{"k":"h","t":"متغیر؛ برچسب روی مقدار"},{"k":"p","t":"در پایتون برای ساخت متغیر نیازی به اعلام نوع نیست؛ مفسر خودش نوع را از روی مقدار تشخیص می‌دهد (Dynamic Typing). یک متغیر در واقع برچسبی است که به یک مقدار در حافظه اشاره می‌کند و می‌تواند بعداً به مقدار دیگری از نوعی دیگر وصل شود."},{"k":"code","lang":"py","title":"first.py","code":"# اولین برنامه هر مهندس نرم‌افزار\nprint(\"Hello, Engineer!\")\n\nname = \"Sara\"        # رشته (str)\nage = 22             # عدد صحیح (int)\ngpa = 18.75          # عدد اعشاری (float)\nis_student = True    # بولین (bool)\n\nprint(f\"{name} is {age} years old\")\nprint(type(gpa))     # <class ''float''>"},{"k":"def","term":"Dynamic Typing","t":"تشخیص نوع متغیر در زمان اجرا توسط مفسر؛ انعطاف بالا در برابر سرعت توسعه، به‌قیمت احتمال خطاهای نوعی که با Type Hints و ابزارهایی مثل mypy کنترل می‌شوند."},{"k":"tip","title":"نکته منتور","t":"از همان روز اول نام‌گذاری معنادار را تمرین کن: n1 و x2 ممنوع! نام‌هایی مثل student_count یا is_valid به‌مرور زمان کدت را برای خودت و هم‌تیمی‌هایت قابل‌فهم نگه می‌دارند."},{"k":"h","t":"ورودی گرفتن از کاربر"},{"k":"code","lang":"py","title":"input.py","code":"name = input(\"What is your name? \")\nyear = int(input(\"Birth year: \"))   # تبدیل رشته به عدد\nage = 1404 - year\nprint(f\"You are about {age} years old\")"},{"k":"warn","title":"خطای رایج","t":"تابع input همیشه رشته برمی‌گرداند. اگر بدون int() با آن ریاضی کنید، به خطای TypeError می‌خورید: ''22'' + 1 یعنی الحاق رشته و عدد که مجاز نیست."},{"k":"h","t":"عمیق‌تر: پایتون واقعاً چطور کار می‌کند؟"},{"k":"p","t":"در پایتون متغیر، برچسبی است که به یک شیء می‌چسبد — نه جعبه‌ای که مقدار در آن ریخته شود. وقتی می‌نویسی a = [1, 2] و بعد b = a، دو برچسب روی یک لیست نشسته‌اند؛ تغییر از طریق b از چشم a هم دیده می‌شود. این «مدل ارجاع» مهم‌ترین تفاوت ذهنی با زبان‌هایی مثل C است و منشأ بسیاری از باگ‌های اولیه — و بسیاری از قدرت پایتون. دستور id() نشانی حافظه شیء را نشان می‌دهد و ثابت می‌کند دو نام می‌توانند به یک شیء اشاره کنند."},{"k":"p","t":"خبر خوب این است که اشیای پایه — عدد، رشته و تاپل — تغییرناپذیرند؛ یعنی پس از ساخته‌شدن هرگز عوض نمی‌شوند و پاس‌دادن‌شان بین توابع کاملاً امن است. لیست، دیکشنری و مجموعه اما تغییرپذیرند و باید مراقب باشی چه کسی مرجع آن‌ها را نگه می‌دارد. قانون سرانگشتی مهندسان پایتون: اگر تابعی قرار است لیست ورودی را تغییر دهد، این را در نامش فریاد بزن (sort در برابر sorted همین تفاوت را دارد) و وقتی شک داری، کپی بگیر."},{"k":"code","lang":"py","title":"deepdive-references.py","code":"a = [1, 2, 3]\nb = a                  # برچسب دوم روی همان لیست\nb.append(4)\nprint(a)               # [1, 2, 3, 4]  ← a هم تغییر کرد!\nprint(a is b)          # True — هر دو به یک شیء اشاره دارند\n\nc = a.copy()           # حالا یک لیست جدا\nc.append(99)\nprint(a)               # [1, 2, 3, 4]  ← a دست‌نخورده ماند\n\nx = \"سلام\"\ny = x\nprint(x is y)          # True — رشته‌ها تغییرناپذیرند؛\n                       # پایتون حتی می‌تواند یک نسخه را بهینه‌سازی کند"},{"k":"p","t":"نکته ظریف دیگر تایپ پویاست: در پایتون «نوع» به شیء می‌چسبد نه به نام. متغیری که الان عدد است، می‌تواند خط بعد رشته باشد. این آزادی سرعت توسعه را چند برابر می‌کند، اما در پروژه‌های بزرگ باید با Type Hint مهار شود تا هم ابزارها کمک کنند و هم خواننده کد گیج نشود. از روز اول عادت کن بنویسی def total(items: list[int]) -> int — هزینه‌اش صفر و فایده‌اش بی‌نهایت است."},{"k":"tip","title":"نکته منتور","t":"برای دیدن ارجاع‌ها از Python Tutor (pythontutor.com) استفاده کن؛ فلش‌هایش دقیقاً همین مدل برچسب‌وبه‌شیء را نشان می‌دهند و در نیم‌ساعت، درکی می‌سازند که شاید هفته‌ها با خواندن متن ساخته نشود."}]'::jsonb, '[{"q":"خروجی print(type(3.0)) چیست؟","opts":["<class ''int''>","<class ''float''>","<class ''double''>","<class ''number''>"],"ans":1,"why":"در پایتون همه اعداد اعشاری از نوع float هستند؛ تایپی به نام double یا number وجود ندارد."},{"q":"کدام نام متغیر در پایتون نامعتبر است؟","opts":["user_name","_count","2nd_place","totalSum"],"ans":2,"why":"نام متغیر نمی‌تواند با رقم شروع شود؛ 2nd_place خطای SyntaxError می‌دهد."}]'::jsonb),
('c1-l2', 'py', 'کنترل جریان؛ تصمیم و تکرار', 60, 5, '[{"k":"p","t":"برنامه‌های واقعی خطی نیستند؛ بسته به شرایط مسیرهای مختلفی را طی می‌کنند و کارهای تکراری را بدون کپی‌کردن کد انجام می‌دهند. دو ابزار اصلی ما if برای تصمیم‌گیری و for/while برای تکرار هستند."},{"k":"h","t":"تورفتگی یعنی بلاک"},{"k":"p","t":"برخلاف زبان‌هایی که بلاک‌ها را با { } مشخص می‌کنند، در پایتون تورفتگی (Indentation) ساختار کد را می‌سازد. این اجبار، کد پایتون را به‌طور ذاتی منظم می‌کند؛ اما بی‌نظمی در تورفتگی خطای IndentationError می‌دهد."},{"k":"code","lang":"py","title":"flow.py","code":"score = 17.5\n\nif score >= 17:\n    grade = \"A\"\nelif score >= 14:\n    grade = \"B\"\nelse:\n    grade = \"C\"\n\nprint(f\"Grade: {grade}\")\n\n# حلقه با range\nfor i in range(1, 6):       # 1 تا 5\n    print(f\"{i} x 3 = {i * 3}\")\n\n# while تا برآورده‌شدن شرط\nn = 1\nwhile n < 100:\n    n *= 2\nprint(n)   # 128"},{"k":"list","items":["range(5) → اعداد ۰ تا ۴","range(2, 10, 3) → شروع ۲، گام ۳","حلقه for روی رشته، لیست و دیکشنری هم کار می‌کند","break خروج از حلقه، continue پرش به دور بعد"]},{"k":"def","term":"Iteration","t":"هر بار اجرای بدنه حلقه یک Iteration نام دارد. درک تعداد Iterationها کلید تحلیل پیچیدگی زمانی الگوریتم‌هاست."},{"k":"tip","title":"نکته منتور","t":"اگر شرط حلقه while هیچ‌وقت نادرست نشود، حلقه بی‌نهایت داری. همیشه قبل از اجرا از خودت بپرس: «چه چیزی در بدنه حلقه تغییر می‌کند که شرط را در نهایت نادرست می‌کند؟»"},{"k":"code","lang":"py","title":"comprehension — جادوی پایتون","code":"# لیست اعداد زوج ۰ تا ۹\nevens = [n for n in range(10) if n % 2 == 0]\nprint(evens)   # [0, 2, 4, 6, 8]\n\n# مربع اعداد\nsquares = {n: n ** 2 for n in range(5)}\nprint(squares[3])   # 9"},{"k":"h","t":"عمیق‌تر: منطق بولی پایتون از آنچه فکر می‌کنی عمیق‌تر است"},{"k":"p","t":"در پایتون تقریباً هر چیزی «ارزش منطقی» دارد: صفر، رشته خالی، لیست خالی و None همگی False ارزیابی می‌شوند و بقیه True. همین قاعده ساده باعث می‌شود if not items یا while stack بنویسیم — کدی کوتاه‌تر و خوانا‌تر از if len(items) == 0. اما همین راحتی، تله هم می‌سازد: if value روی عدد 0 یا رشته خالی هم False است، در حالی که شاید 0 یک مقدار کاملاً معتبر باشد؛ آنجا باید صریح نوشت if value is not None."},{"k":"p","t":"عملگرهای and و or در پایتون فقط مقدار منطقی برنمی‌گردانند — یکی از دو عملوند را برمی‌گردانند (اتصال کوتاه‌مدار): a and b اگر a نادرست باشد خودِ a را برمی‌گرداند و اصلاً سراغ b نمی‌رود. این هم ابزار بهینه‌سازی است (چک ارزان قبل از چک گران) و هم منشأ باگ‌های عجیب. از پایتون ۳٫۱۰ به بعد هم دستور match ساختارهای شرطی پیچیده را از تودرتوی if نجات می‌دهد و الگوهای داده را مستقیم تجزیه می‌کند — قابلیتی که از زبان‌های تابعی وام گرفته شده و کد پردازش داده را متحول می‌کند."},{"k":"code","lang":"py","title":"deepdive-match.py","code":"from dataclasses import dataclass\n\n@dataclass\nclass Circle:    radius: float\n@dataclass\nclass Rectangle: w: float; h: float\n\ndef area(shape):\n    match shape:\n        case Circle(radius=r) if r > 0:\n            return 3.14159 * r * r\n        case Rectangle(w=w, h=h):\n            return w * h\n        case _:\n            raise ValueError(f\"شکل ناشناخته: {shape}\")\n\nprint(area(Circle(2)))        # 12.566\nprint(area(Rectangle(3, 4)))  # 12\n\n# تله ارزش منطقی:\nvalue = 0\nprint(bool(value))            # False — ولی ۰ ممکن است معتبر باشد!\nprint(value is not None)      # True — چک درست برای «وجود داشتن»"},{"k":"table","head":["مقدار","bool()","چرا مهم است؟"],"rows":[["0 و 0.0","False","ممکن است مقدار معتبر باشد؛ از is not None استفاده کن"],["\"\" و [] و {}","False","بررسی «خالی بودن» کوتاه می‌شود: if not items"],["None","False","تنها نشانه «نبودن» — همیشه با is مقایسه کن"],["\"False\" (رشته)","True","رشته غیرخالی همیشه True است — تله کلاسیک!"]]},{"k":"warn","title":"تله کلاسیک حلقه","t":"تغییر یک لیست حین پیمایشش با for — مثل حذف عنصر هنگام شمارش — رفتار تعریف‌نشده‌ای دارد و عناصر را جا می‌اندازد. راه‌حل: روی کپی پیمایش کن (for x in items[:]) یا لیست جدید بساز؛ و حلقه‌های تو در توی زیاد را با Comprehension یا تابع کمکی بشکن."}]'::jsonb, '[{"q":"range(2, 10, 3) کدام اعداد را تولید می‌کند؟","opts":["2، 5، 8","2، 5، 8، 10","3، 6، 9","2 تا 10 با گام 3 شامل 10"],"ans":0,"why":"range از ۲ شروع می‌شود، ۳ تا اضافه می‌کند و قبل از رسیدن به ۱۰ متوقف می‌شود: ۲، ۵، ۸."},{"q":"تفاوت اصلی for و while چیست؟","opts":["while سریع‌تر است","for روی دنباله‌ها iterate می‌کند؛ while تا برقراربودن شرط تکرار می‌کند","for نمی‌تواند break داشته باشد","هیچ تفاوتی ندارند"],"ans":1,"why":"for برای پیمایش تعداد مشخص یا دنباله‌ها و while برای تکرار شرط‌دار طراحی شده است؛ کارایی‌شان در CPython یکسان است."}]'::jsonb),
('c1-l3', 'py', 'توابع و ساختارهای داده', 75, 6, '[{"k":"p","t":"وقتی یک تکه منطق بیش از یک بار لازم می‌شود، آن را داخل تابع می‌گذاریم. تابع ورودی می‌گیرد، کاری انجام می‌دهد و خروجی برمی‌گرداند — همین سادگی، پایه تمام مهندسی نرم‌افزار است: تقسیم مسئله بزرگ به قطعه‌های کوچک و تست‌پذیر."},{"k":"code","lang":"py","title":"functions.py","code":"def bmi(weight: float, height: float) -> float:\n    \"\"\"محاسبه شاخص توده بدنی\"\"\"\n    return weight / (height ** 2)\n\n# آرگومان پیش‌فرض و keyword argument\nresult = bmi(70, height=1.75)\nprint(round(result, 1))   # 22.9\n\ndef stats(*numbers):\n    return min(numbers), max(numbers), sum(numbers) / len(numbers)\n\nprint(stats(4, 8, 15, 16, 23, 42))"},{"k":"h","t":"چهار ساختار داده‌ای که همه‌چیز هستند"},{"k":"table","head":["ساختار","نمونه","ترتیب","تغییرپذیر"],"rows":[["list","[1, 2, 3]","دارد","بله"],["tuple","(1, 2, 3)","دارد","خیر"],["dict","{\"a\": 1}","دارد (از ۳.۷)","بله"],["set","{1, 2, 3}","ندارد","بله"]]},{"k":"code","lang":"py","title":"data-structures.py","code":"student = {\"name\": \"Ali\", \"courses\": [\"DB\", \"OS\"]}\nstudent[\"gpa\"] = 19.2              # افزودن کلید\nstudent[\"courses\"].append(\"AI\")\n\nfor key, value in student.items():\n    print(key, \"=>\", value)\n\n# set برای حذف تکراری‌ها\nunique = set([3, 1, 3, 2, 1])\nprint(unique)   # {1, 2, 3}"},{"k":"warn","title":"دام کلاسیک","t":"دیکشنری و لیست با ارجاع پاس داده می‌شوند؛ تغییر آن‌ها داخل تابع، روی داده اصلی هم اثر می‌گذارد. اگر نمی‌خواهی، از کپی استفاده کن: new_list = old_list.copy()"},{"k":"tip","title":"نکته منتور","t":"Type Hints (مثل weight: float) اجباری نیستند، اما ابزارهای IDE و mypy با آن‌ها خطاها را قبل از اجرا پیدا می‌کنند. در کد حرفه‌ای همیشه از آن‌ها استفاده کن."},{"k":"h","t":"عمیق‌تر: دیکشنری، قدرتمندترین ساختار پایتون"},{"k":"p","t":"دیکشنری پایتون یک جدول هش بهینه‌شده است: جست‌وجو، درج و حذف در آن — صرف‌نظر از اندازه — به‌طور میانگین O(1) است. به همین دلیل تقریباً همه‌چیز در اکوسیستم پایتون (از تنظیمات تا کش تا شمارش) دیکشنری است. کلید دیکشنری باید هش‌پذیر و تغییرناپذیر باشد (رشته، عدد، تاپل) — لیست نمی‌تواند کلید شود چون قابل تغییر است و هشش هم باید ثابت بماند. از پایتون ۳٫۷ به بعد، ترتیب درج در دیکشنری هم حفظ می‌شود که خوانایی خروجی را تضمین می‌کند."},{"k":"p","t":"در کنار دیکشنری، مجموعه (set) برای عضویت و یگانگی و Comprehension برای تبدیل داده، سه‌گانه‌ای را می‌سازند که بخش بزرگی از «کد پایتونی» را تشکیل می‌دهد. به‌جای ساختن لیست با حلقه و if، یک خط می‌نویسیم: [x * 2 for x in items if x > 0]. وقتی خروجی دیکشنری یا مجموعه بخواهیم فقط براکت عوض می‌شود. این سبک نه فقط کوتاه‌تر، که معمولاً سریع‌تر هم اجرا می‌شود چون در سطح C بهینه شده است."},{"k":"code","lang":"py","title":"deepdive-dict.py","code":"from collections import Counter, defaultdict\n\ntext = \"مهندسی نرم افزار یعنی ساختن نرم افزار با مهندسی\"\n\n# شمارش کلمات — کاری که با دیکشنری معمولی ۵ خط است:\nprint(Counter(text.split()))\n# Counter({''نرم'': 2, ''مهندسی'': 1, ...})\n\n# گروه‌بندی — defaultdict کلید غایب را خودش می‌سازد:\ngroups = defaultdict(list)\nfor name, team in [(\"سارا\", \"بک‌اند\"), (\"کیان\", \"فرانت\"), (\"نگار\", \"بک‌اند\")]:\n    groups[team].append(name)\nprint(dict(groups))\n\n# Comprehension دیکشنری:\nprices = {\"apple\": 30, \"kiwi\": 55, \"banana\": 20}\nexpensive = {k: v for k, v in prices.items() if v > 25}\nprint(expensive)       # {''apple'': 30, ''kiwi'': 55}"},{"k":"p","t":"دو متد طلایی دیکشنری را هیچ‌وقت فراموش نکن: .get(key, default) که به‌جای خطای KeyError مقدار پیش‌فرض برمی‌گرداند، و .setdefault که «بگیر و اگر نبود بساز» را در یک فراخوانی انجام می‌دهد. در کد واقعی، try/except دورِ d[k] تقریباً همیشه نشانه این است که باید از .get استفاده می‌شد — مگر وقتی نبودن کلید واقعاً یک خطای برنامه است که باید بلند فریاد بزند."},{"k":"tip","title":"نکته منتور","t":"*args و **kwargs را با یک مثال واقعی یاد بگیر: نوشتن یک تابع لاگ که هر تعداد پیام و هر تعداد تنظیم می‌گیرد. وقتی بفهمی **kwargs در واقع یک دیکشنری است که «باز» می‌شود، نصف جادوی کتابخانه‌های پایتون برایت روشن می‌شود — از print خود پایتون تا فریم‌ورک‌های بزرگ."}]'::jsonb, '[{"q":"کدام ساختار برای ذخیره کلید‌های یکتا مناسب است؟","opts":["list","tuple","set","هر سه"],"ans":2,"why":"set ذاتاً عناصر تکراری را حذف می‌کند و عملیات عضویت در آن O(1) است."},{"q":"خروجی stats(4, 8) با تعریف بالا چیست؟","opts":["(4, 8, 6.0)","(4, 8, 12)","خطا — فقط یک آرگومان مجاز است","(8, 4, 6.0)"],"ans":0,"why":"*numbers همه آرگومان‌ها را به‌صورت tuple جمع می‌کند؛ min=۴ و max=۸ و میانگین ۶.۰ می‌شود."}]'::jsonb),
('c6-l1', 'py', 'کلاس، شیء و کپسوله‌سازی', 50, 7, '[{"k":"p","t":"کلاس نقشه ساخت و شیء نمونه واقعی است. ایده مرکزی کپسوله‌سازی این است: داده‌ها را پشت یک رابط ساده پنهان کن و اجازه نده هرکس از بیرون، وضعیت شیء را به هر شکلی تغییر دهد. این کار، تغییرات داخلی را بدون شکستن بقیه کد ممکن می‌کند."},{"k":"code","lang":"py","title":"bank_account.py","code":"class BankAccount:\n    def __init__(self, owner: str):\n        self.owner = owner\n        self.__balance = 0.0     # خصوصی با __\n\n    def deposit(self, amount: float):\n        if amount <= 0:\n            raise ValueError(\"amount must be positive\")\n        self.__balance += amount\n\n    def withdraw(self, amount: float):\n        if amount > self.__balance:\n            raise ValueError(\"insufficient funds\")\n        self.__balance -= amount\n\n    @property\n    def balance(self):          # فقط خواندنی از بیرون\n        return self.__balance\n\nacc = BankAccount(\"Sara\")\nacc.deposit(500)\nprint(acc.balance)      # 500.0\n# acc.__balance = 9999  => بدون اثر (name mangling)"},{"k":"def","term":"Invariant","t":"شرطی که شیء باید همیشه برقرار نگه دارد؛ مثلاً «موجودی هیچ‌وقت منفی نیست». کپسوله‌سازی یعنی تمام تغییرات از مسیر متدها بگذرد تا Invariantها نقض نشوند."},{"k":"warn","title":"زیاده‌روی ممنوع","t":"هر متغیری getter/setter نساز! اگر هیچ اعتبارسنجی یا منطقی لازم نیست، فیلد عمومی ساده‌تر و خواناتر است. کپسوله‌سازی ابزار است، نه آیین."},{"k":"h","t":"عمیق‌تر: کپسوله‌سازی در پایتون — قرارداد، نه زندان"},{"k":"p","t":"پایتون برخلاف جاوا، private واقعی ندارد — و این یک تصمیم طراحی است، نه کمبود. قرارداد زبان این است: یک زیرخط پیش از نام (_value) یعنی «داخلی؛ لطفاً دست نزن»، دو زیرخط (__value) یعنی «اسم‌گُلی می‌شوم تا تصادفی بازنویسی نشوم» (Name Mangling)، نه امنیت. فلسفه پایتون این است: «همه بزرگسال‌اند» — کپسوله‌سازی را با قرارداد اجتماعی و API روشن نگه می‌داریم، نه با قفل کامپایلر. در عمل، تیم‌های پایتونی که Property و Dataclass درست استفاده می‌کنند، کپسوله‌سازی واقعی دارند: بیرون فقط با رابط عمومی حرف می‌زند و درون آزاد است تغییر کند."},{"k":"p","t":"Property همان پلی است که «فیلد ساده» را به «رفتار کنترل‌شده» ارتقا می‌دهد بدون اینکه کد فراخواننده عوض شود: بیرون می‌نویسد user.age = 17 و پشت صحنه، setter اعتبارسنجی می‌کند. این یعنی می‌توانی با فیلد ساده شروع کنی و هر وقت نیاز به منطق پیدا کردی، بدون شکستن API به Property تبدیلش کنی — یک اهرم طراحی که در زبان‌های بدون Property (مثل جاوا که از اول getter/setter می‌خواهد) وجود ندارد. Dataclass هم بویلرپلیت __init__ و __repr__ و __eq__ را حذف می‌کند و با frozen=True شیء تغییرناپذیر می‌سازد — ترکیبش با Property، پایه طراحی مدرن پایتون است."},{"k":"code","lang":"py","title":"deepdive-property.py","code":"from dataclasses import dataclass, field\n\nclass Account:\n    def __init__(self):\n        self._balance = 0            # قرارداد: داخلی است\n\n    @property\n    def balance(self):               # خواندن عمومی\n        return self._balance\n\n    @balance.setter\n    def balance(self, value):\n        if value < 0:\n            raise ValueError(\"موجودی منفی مجاز نیست\")\n        self._balance = value        # اعتبارسنجی پشت صحنه\n\nacc = Account()\nacc.balance = 100        # setter صدا می‌خورد — بدون پرانتز!\n# acc.balance = -5       → ValueError\n\n@dataclass(frozen=True)  # شیء تغییرناپذیر — hash هم دارد\nclass Money:\n    amount: int\n    currency: str = \"IRT\"\n\nprint(Money(1000) == Money(1000))   # True — eq خودکار"},{"k":"p","t":"سوال مصاحبه‌ای کلاسیک: «کپسوله‌سازی واقعاً چه چیزی می‌خرد؟» جواب یک‌کلمه‌ای: آزادیِ تغییر. وقتی بیرون فقط از سه متد عمومی استفاده می‌کند، می‌توانی الگوریتم داخل را ده بار عوض کنی، کش اضافه کنی، لاگ بزنی — بدون اینکه یک فایل بیرون از کلاس دست بخورد. کپسوله‌سازی یعنی مرزِ تغییر: باگ‌ها و تغییرات داخل جعبه می‌مانند. هرچه این جعبه‌ها کوچک‌تر و مستقل‌تر باشند، سیستم در برابر تغییر نرم‌تر است — و این تعریف واقعی «طراحی خوب» است."},{"k":"tip","title":"نکته منتور","t":"یک تمرین چشم‌بازکن: کلاسی از پروژه‌ات را بردار و از خودت بپرس «اگر فقط متدهای عمومی‌اش را ببینم، می‌فهمم چه می‌کند؟» اگر نه، یا نام‌ها بدند یا کلاس چند کار می‌کند. نام متد عمومی، قرارداد است — برای نام‌گذاری وقت بگذار؛ کد تمیز از خواندن شروع می‌شود."}]'::jsonb, '[{"q":"هدف اصلی کپسوله‌سازی چیست؟","opts":["سرعت بیشتر اجرا","محدودکردن دسترسی مستقیم به حالت داخلی","کاهش حجم کد","جلوگیری از ارث‌بری"],"ans":1,"why":"با پنهان‌کردن جزئیات، تغییر داخلی بدون شکستن کدِ استفاده‌کننده ممکن می‌شود و Invariantها محافظت می‌شوند."},{"q":"در پایتون کدام علامت قرارداد «خصوصی بودن» عضو است؟","opts":["private","!","__ پیش از نام","static"],"ans":2,"why":"__balance با Name Mangling از دسترسی تصادفی محافظت می‌کند؛ یک _ هم قرارداد «داخلی» بودن است اما اجباری ایجاد نمی‌کند."}]'::jsonb),
('c6-l2', 'py', 'ارث‌بری و چندریختی', 60, 8, '[{"k":"p","t":"ارث‌بری یعنی کلاسی رفتار کلاس دیگر را به ارث ببرد و چندریختی یعنی کدِ مشترک بدون دانستن نوع دقیق، با همه زیرمجموعه‌ها کار کند. اما قانون طلایی این است: ترکیب (Composition) را به ارث‌بری ترجیح بده؛ ارث‌بری فقط وقتی که رابطه «هست» واقعی باشد."},{"k":"code","lang":"py","title":"polymorphism.py","code":"class Notification:\n    def send(self, user, text):\n        raise NotImplementedError\n\nclass Email(Notification):\n    def send(self, user, text):\n        print(f\"Email to {user.email}: {text}\")\n\nclass Sms(Notification):\n    def send(self, user, text):\n        print(f\"SMS to {user.phone}: {text}\")\n\nclass Push(Notification):\n    def send(self, user, text):\n        print(f\"Push to {user.device}: {text}\")\n\n# چندریختی: بدون دانستن نوع دقیق\ndef notify_all(channels, user, text):\n    for ch in channels:\n        ch.send(user, text)\n\nnotify_all([Email(), Sms(), Push()], user, \"Welcome!\")"},{"k":"h","t":"ترکیب به‌جای ارث‌بری"},{"k":"code","lang":"py","title":"composition.py","code":"# بد: Engine از Car ارث ببرد؟ نه! رابطه «دارد» است\nclass Engine:\n    def start(self):\n        return \"vroom\"\n\nclass Car:\n    def __init__(self):\n        self.engine = Engine()    # ترکیب: Car یک Engine دارد\n\n    def drive(self):\n        self.engine.start()\n        print(\"moving...\")"},{"k":"tip","title":"نکته منتور","t":"قبل از ارث‌بری از خودت بپرس: آیا زیرکلاس واقعاً «یک نوع» از والد است؟ آیا می‌خواهم همه متدهای والد را به ارث ببرم؟ اگر جواب «نه» بود، ترکیب انتخاب کن — سبک‌تر، تست‌پذیرتر و قابل‌تغییرتر است."},{"k":"h","t":"عمیق‌تر: ترکیب در برابر ارث‌بری — بحث بزرگ شی‌گرایی"},{"k":"p","t":"ارث‌بری وسوسه‌انگیز است: کدی که یک بار نوشته و چندجا استفاده می‌شود. اما رابطه «هست» (is-a) سخت‌گیرانه‌تر از آن است که در دنیای واقعی پیدا شود: مربع مستطیل نیست (تغییر عرضش طول را هم عوض می‌کند و قرارداد مستطیل را می‌شکند)، پنگوئن پرنده‌ای نیست که پرواز کند. هر ارث‌بری یعنی فرزند به تمام قول‌های پدر متعهد است — و شکستن این تعهد (نقض اصل جایگزینی Liskov) باگی است که هیچ تست واحدی پیدایش نمی‌کند چون در «تعامل» پنهان است. به همین دلیل قانون مدرن این است: ترکیب (has-a) پیش‌فرض باشد، ارث‌بری فقط وقتی واقعاً سلسله‌مراتب «هست» داری و می‌خواهی چندریختی بدهی."},{"k":"p","t":"در پایتون، Abstract Base Class (ماژول abc) ابزار رسمی اعلام قرارداد است: متد انتزاعی یعنی «هر فرزند باید این را پیاده کند» و اگر نکند، حتی ساخته هم نمی‌شود. این همان «برنامه‌نویسی بر اساس قرارداد» است: کد بالا به شکلِ رفتار وابسته است نه به نوع مشخص. MRO (ترتیب حل متد) هم ترفند پایتون برای مسئله لوزی است — الگوریتم C3 تعیین می‌کند وقتی دو پدر متد هم‌نام دارند، کدام برنده است؛ دانستنش برای دیباگ کدهای چندوارثی واجب است، حتی اگر خودت هیچ‌وقت چندوارثی ننویسی (و بهتر است ننویسی؛ mixinها تنها استثناند)."},{"k":"code","lang":"py","title":"deepdive-abc.py","code":"from abc import ABC, abstractmethod\n\n# قرارداد: هر «ذخیره‌ساز» باید این دو کار را بکند\nclass Storage(ABC):\n    @abstractmethod\n    def save(self, key: str, value) -> None: ...\n\n    @abstractmethod\n    def load(self, key: str): ...\n\nclass MemoryStorage(Storage):\n    def __init__(self):\n        self._data = {}\n    def save(self, key, value): self._data[key] = value\n    def load(self, key):        return self._data[key]\n\n# ترکیب به‌جای ارث‌بری:\nclass UserService:\n    def __init__(self, storage: Storage):   # تزریق وابستگی\n        self._storage = storage\n    def register(self, user):  self._storage.save(user.id, user)\n    def find(self, uid):       return self._storage.load(uid)\n\nsvc = UserService(MemoryStorage())\n# فردا: UserService(RedisStorage()) — بدون یک خط تغییر در سرویس!"},{"k":"table","head":["نشانه","یعنی چه؟"],"rows":[["دارم یک ... را استفاده می‌کنم","ترکیب — فیلد/تزریق"],["واقعاً یک ... هستم و باید جایگزینش شوم","ارث‌بری + چندریختی"],["چند کلاس یک متد مشابه دارند","Mixin یا تابع مشترک — نه کپی!"],["پدر را override کردم ولی رفتار پایه فرق کرد","نقض Liskov — طراحی را بازنگری کن"]]},{"k":"warn","title":"ضدالگوی کلاسیک","t":"«کلاس پایه God»: BaseView/BaseService که صدها خط منطق دارد و همه چیز از آن ارث می‌برد. تغییر کوچک در پایه، همه فرزند‌ها را می‌لرزاند و تست‌کردنش غیرممکن می‌شود. اگر کلاس پایه‌ات از ۲۰۰ خط رد شد، زنگ خطر است — منطق مشترک را به کلاس‌های کوچک ترکیب‌شونده بشکن."}]'::jsonb, '[{"q":"چرا ارث‌بری «کتاب از محصول» معقول است ولی «موتور از ماشین» نه؟","opts":["چون موتور کوچک‌تر است","چون رابطه کتاب-محصول «هست» ولی موتور-ماشین «دارد» است","چون ماشین کلاس بزرگ‌تری است","فرقی ندارند"],"ans":1,"why":"موتور جزئی از ماشین است نه نوعی از آن؛ برای رابطه «دارد» باید ترکیب استفاده کرد نه ارث‌بری."},{"q":"مزیت چندریختی در تابع notify_all چیست؟","opts":["سرعت بیشتر ارسال","افزودن کانال جدید بدون تغییر تابع","حذف نیاز به کلاس پایه","کاهش تعداد کلاس‌ها"],"ans":1,"why":"برای افزودن کانال Telegram فقط یک کلاس جدید می‌سازیم؛ notify_all و هیچ کد دیگری تغییر نمی‌کند — Open/Closed در عمل."}]'::jsonb),
('c6-l3', 'py', 'اصول SOLID در عمل', 75, 9, '[{"k":"p","t":"SOLID پنج اصل برای طراحی شی‌گرای قابل‌نگهداری است. لازم نیست حفظ کنی؛ باید بفهمی هرکدام چه بویی از کدِ بد را از بین می‌برد. این درس را با مثال واقعی پیش می‌بریم: سیستم تولید گزارش."},{"k":"code","lang":"py","title":"SRP+OCP.py","code":"# نقض SRP و OCP: یک کلاس همه‌کاره\nclass Report:\n    def calc(self): ...\n    def save_pdf(self): ...\n    def send_email(self): ...\n# افزودن خروجی Excel => تغییر این کلاس!\n\n# بازنویسی: مسئولیت جدا، توسعه بدون تغییر\nclass ReportData:\n    def calc(self): ...\n\nclass PdfExporter:\n    def export(self, data): ...\n\nclass ExcelExporter:\n    def export(self, data): ...\n\nclass ReportService:\n    def __init__(self, exporter):\n        self.exporter = exporter    # تزریق وابستگی (DIP)\n\n    def run(self, data):\n        return self.exporter.export(data.calc())"},{"k":"list","items":["S — هر کلاس فقط یک دلیل برای تغییر داشته باشد","O — برای توسعه باز، برای تغییر بسته","L — زیرکلاس‌ها باید جایگزین والد شوند بدون شکستن کد","I — چند رابط کوچک بهتر از یک رابط بزرگ","D — به انتزاع وابسته باش نه پیاده‌سازی"]},{"k":"def","term":"تزریق وابستگی","t":"به‌جای ساختن وابستگی‌ها داخل کلاس، آن‌ها را از بیرون (معمولاً سازنده) دریافت کن. نتیجه: کد به هر Exporter واقعی نیاز ندارد و در تست می‌توان نمونه ساختگی تزریق کرد."},{"k":"warn","title":"SOLID بت نیست","t":"این اصول برای کدی‌اند که تغییر می‌کنند. برای یک اسکریپت ۵۰ خطی یا پروتوتایپ، SOLID کامل یعنی پیچیدگی بیهوده. اول کار کن، بعد وقتی بوی تغییر آمد، بازطراحی کن."},{"k":"h","t":"عمیق‌تر: SOLID به زبان کد واقعی"},{"k":"p","t":"SOLID پنج مخفف خشک نیست؛ پنج سوال است که قبل از هر تغییر کد باید بپرسی. S: آیا این کلاس/تابع فقط یک دلیل برای تغییر دارد؟ O: آیا می‌توانم رفتار جدید اضافه کنم بدون دست‌زدن به این فایل؟ L: آیا کلاس فرزندم می‌تواند هر جای پدر استفاده شود بدون غافلگیری؟ I: آیا مصرف‌کننده به متدهایی که استفاده نمی‌کند وابسته نیست؟ D: آیا ماژول‌هایم به انتزاع وابسته‌اند یا به جزئیات؟ بیشتر کدهای «سفت» که تغییرشان می‌ترساند، یکی از این پنج سوال را رد کرده‌اند — SOLID در واقع نقشه‌ای برای پیدا کردن همان نقطه شکستگی است."},{"k":"p","t":"مثال واقعی D (وارونگی وابستگی): سرویسی که مستقیم import requests می‌کند و API خارجی را صدا می‌زند، به جزئیات (کتابخانه، URL، فرمت پاسخ) گره خورده — تستش بدون اینترنت ممکن نیست و تعویض ارائه‌دهنده یعنی بازنویسی. اما اگر به یک انتزاع HttpClient وابسته شود و پیاده‌سازی واقعی از بیرون تزریق شود، همان سرویس با Mock در میلی‌ثانیه تست می‌شود و فردا با یک کلاس جدید، ارائه‌دهنده عوض می‌شود. DI Containerها (یا در پایتون، همان سازنده‌کلاس ساده) فقط همین وارونگی را مکانیکی می‌کنند — جادو در تصمیم طراحی است، نه در ابزار."},{"k":"code","lang":"py","title":"deepdive-srp.py","code":"# ضدالگو: یک کلاس، سه دلیل برای تغییر\nclass Invoice:\n    def total(self): ...          # منطق محاسبه\n    def save(self): ...           # دسترسی به دیتابیس\n    def render_html(self): ...    # قالب نمایش\n# تغییر مالیات؟ تغییر درگاه ذخیره؟ تغییر دیزاین؟\n# هر سه به همین فایل می‌خورند و تست‌های هم را خراب می‌کنند!\n\n# SOLID: هر مسئولیت، یک خانه\n@dataclass\nclass Invoice:                    # فقط داده و محاسبه\n    items: list\n    def total(self): return sum(i.price * i.qty for i in self.items)\n\nclass InvoiceRepository:          # فقط ذخیره‌سازی\n    def __init__(self, db): self.db = db\n    def save(self, inv): ...\n\ndef render_invoice_html(inv, template): ...   # فقط نمایش\n\n# حالا هر تغییر فقط یک فایل را لمس می‌کند —\n# و هر فایل مستقل از بقیه تست می‌شود."},{"k":"table","head":["اصل","بوی بدِ نقضش","درمان سریع"],"rows":[["S — تک‌مسئولیتی","کلاس/تابع ۳۰۰ خطی، نام‌های «مدیر» و «پردازنده»","هر مسئولیت یک کلاس/تابع"],["O — باز/بسته","if/elif برای هر مشتری جدید","Strategy یا رجیستری پلاگین"],["L — جایگزینی","override که raise می‌کند یا کاری نمی‌کند","انتزاع را باریک‌تر کن"],["I — جداسازی رابط","تست به متدهای استفاده‌نشده وابسته است","رابط‌های کوچک و تخصصی"],["D — وارونگی","import مستقیم کتابخانه در منطق","تزریق وابستگی"]]},{"k":"tip","title":"نکته منتور","t":"SOLID را مثل نمک ببین، نه دستور آشپزی: کدی که یک‌بار استفاده می‌شود و می‌میرد (اسکریپت مهاجرت داده)، لازم نیست D را رعایت کند. جایی که SOLID واجب است، کدی است که «زندگی می‌کند» — همان جایی که هزینه تغییرش را ماه‌ها می‌پردازی."}]'::jsonb, '[{"q":"کدام اصل می‌گوید «افزودن فرمت CSV نباید کلاس‌های موجود را تغییر دهد»؟","opts":["SRP","OCP","LSP","DIP"],"ans":1,"why":"Open/Closed: سیستم باید با افزودن ماژول جدید توسعه یابد (Exporter جدید) نه با ویرایش ماژول‌های قدیمی."},{"q":"مزیت اصلی تزریق وابستگی چیست؟","opts":["سرعت اجرا","جداسازی کد از وابستگی‌های واقعی و تست‌پذیری","کاهش تعداد کلاس‌ها","امنیت بیشتر"],"ans":1,"why":"کد به رابط وابسته می‌شود؛ در تست نمونه جعلی و در تولید پیاده‌سازی واقعی تزریق می‌شود بدون تغییر کد."}]'::jsonb),
('py-x1', 'py', 'فایل‌ها، استثناها و کدی که نمی‌شکند', 45, 10, '[{"k":"p","t":"برنامه واقعی با داده‌های واقعی کار می‌کند: فایلی که وجود ندارد، عددی که کاربر اشتباه تایپ کرده، اتصالی که قطع شده. تفاوت کد اسباب‌بازی و کد مهندسی دقیقاً اینجاست — کد مهندسی برای روزهای بد طراحی می‌شود، نه فقط روزهای خوب."},{"k":"h","t":"مدیریت فایل با Context Manager"},{"k":"p","t":"بازکردن فایل بدون بستن، نشت منابع است؛ حتی اگر خطایی وسط کار رخ بدهد. دستور with تضمین می‌کند فایل در هر شرایطی بسته شود — همان الگوی RAII که در دوره C++ دیدی، به سبک پایتون."},{"k":"code","lang":"py","title":"files.py","code":"from pathlib import Path\n\ndef read_scores(path: str) -> list[float]:\n    with open(path, encoding=''utf-8'') as f:\n        return [float(line) for line in f if line.strip()]\n\n# نوشتن امن — اگر فایل نبود، خودت پیام معنادار بده\ndef load_or_empty(path: str) -> list[float]:\n    try:\n        return read_scores(path)\n    except FileNotFoundError:\n        print(f''⚠ فایل {path} نیست؛ با لیست خالی شروع می‌کنیم'')\n        return []\n    except ValueError as e:\n        raise ValueError(f''داده خراب در {path}: {e}'') from e\n\nscores = load_or_empty(''scores.txt'')\nprint(f''{len(scores)} نمره خوانده شد'')"},{"k":"def","term":"Exception","t":"استثنا یعنی «مسیر عادی ادامه ندارد؛ تصمیم را به لایه بالاتر بسپار». پرتاب‌کردن استثنا شکست نیست — پنهان‌کردن آن (except: pass) شکست است."},{"k":"list","items":["فقط استثناهایی را بگیر که می‌توانی معنادار مدیریت کنی","except خالی یا pass ممنوع — قاتل خاموش باگ‌ها","از finally یا with برای پاک‌سازی منابع استفاده کن","استثنای اختصاصی تعریف کن: class InvalidScore(ValueError)"]},{"k":"code","lang":"py","title":"استثنای اختصاصی","code":"class InvalidScore(ValueError):\n    \"\"\"نمره خارج از بازه ۰ تا ۲۰\"\"\"\n\ndef validate(score: float) -> float:\n    if not 0 <= score <= 20:\n        raise InvalidScore(f''نمره {score} نامعتبر است'')\n    return score\n\ntry:\n    validate(25)\nexcept InvalidScore as e:\n    print(''خطای داده:'', e)   # خطای داده: نمره 25.0 نامعتبر است"},{"k":"warn","title":"ضدالگوی رایج","t":"گرفتن Exception پایه (except Exception) تقریباً همیشه اشتباه است؛ چون حتی باگ‌های برنامه‌نویسی (TypeError و…) را هم می‌بلعد و برنامه با داده غلط ادامه می‌دهد. خاص بگیر، خاص پرتاب کن."},{"k":"tip","title":"نکته منتور","t":"در کد حرفه‌ای پایتون، از EAFP استفاده می‌شود نه LBYL: به‌جای if os.path.exists(x): open(x) مستقیم open کن و FileNotFoundError را بگیر — سریع‌تر، تمیزتر و بدون Race Condition."}]'::jsonb, '[{"q":"چرا except: pass خطرناک‌ترین خط پایتون است؟","opts":["کند است","هر خطایی را بی‌صدا می‌بلعد و برنامه با حالت خراب ادامه می‌دهد","فقط در پایتون ۲ کار می‌کند","حافظه نشت می‌کند"],"ans":1,"why":"وقتی خطا دیده نمی‌شود، باگ ماه‌ها بعد جای دیگری سر درمی‌آورد — آن‌وقت پیدا کردنش تقریباً غیرممکن است. لااقل لاگ کن."},{"q":"with open(...) چه تضمینی می‌دهد؟","opts":["فایل سریع‌تر خوانده می‌شود","فایل حتی در صورت وقوع استثنا بسته می‌شود","فایل قفل می‌شود","کدگذاری خودکار تشخیص داده می‌شود"],"ans":1,"why":"with متد __exit__ را حتی هنگام پرتاب استثنا صدا می‌زند؛ معادل try/finally برای آزادسازی منبع."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('py-x2', 'py', 'Generator و Iterator — حافظه‌ی بی‌نهایت، مصرفِ اندک', 55, 11, '[{"k":"p","t":"فرض کن یک فایل لاگ ۱۰ گیگابایتی داری و فقط خطاهایش را می‌خواهی. خواندن همه‌اش در یک لیست یعنی ۱۰ گیگابایت RAM — و کرش. Generator راه حل پایتون است: تابعی که به‌جای return از yield استفاده می‌کند و هر بار فقط «یک قلم» تولید می‌کند، بعد مکث می‌کند تا مصرف‌کننده بعدی را بخواهد. حافظه مصرفی: یکی. همین ایده پشت خط‌های پردازش داده پایتون است — حلقه‌ای که از روی میلیاردها رکورد می‌گذرد ولی هیچ‌وقت بیشتر از یک رکورد را نگه نمی‌دارد."},{"k":"code","lang":"py","title":"generator.py","code":"import sys\n\n# لیست: همه‌چیز همین حالا در حافظه\nnums_list = [n * n for n in range(10_000_000)]\nprint(sys.getsizeof(nums_list))    # ≈ ۸۵ میلیون بایت!\n\n# Generator: همان داده، ولی «درخواستی»\nnums_gen = (n * n for n in range(10_000_000))\nprint(sys.getsizeof(nums_gen))     # ≈ ۱۰۰ بایت!\n\n# Generator واقعی با yield — پردازش فایل حجیم:\ndef errors(path):\n    with open(path, encoding=''utf-8'') as f:\n        for line in f:             # فایل هم خودش iterator است!\n            if ''ERROR'' in line:\n                yield line.strip() # فقط خطاهای واقعی در حافظه‌اند\n\nfor line in errors(''access.log''):\n    print(line)\n    # می‌توانی وسطش break کنی — بقیه فایل اصلاً خوانده نمی‌شود!"},{"k":"def","term":"Protocol Iterator","t":"هر چیزی که متد __iter__ و __next__ داشته باشد، در for و همه ابزارهای پایتون کار می‌کند — از لیست و دیکشنری تا Generator و فایل باز. یعنی می‌توانی برای کلاس خودت تعریف کنی «پیمایش یعنی چه» و همه اکوسیستم پایتون بدون تغییر، رویش کار کند. Comprehension و * و zip و sum همه همین قرارداد کوچک را مصرف می‌کنند."},{"k":"code","lang":"py","title":"pipeline.py","code":"# خط لوله تنبل — هر مرحله Generator، کل زنجیره یک‌عبوره:\ndef read_lines(path):\n    with open(path) as f:\n        yield from f\n\ndef parse(line):\n    parts = line.split()\n    return {''ip'': parts[0], ''status'': int(parts[8])}\n\ndef server_errors(rec):\n    return rec[''status''] >= 500\n\npipeline = filter(server_errors, map(parse, read_lines(''access.log'')))\nfirst_5 = list(itertools.islice(pipeline, 5))   # فقط ۵ تا پردازش شد!"},{"k":"table","head":["","لیست","Generator"],"rows":[["حافظه","O(n) — همه در RAM","O(1) — یکی در لحظه"],["سرعت شروع","باید همه ساخته شود","فوری"],["پیمایش دوم","ممکن","تمام‌شدنی — دوباره بساز"],["اینکس‌گذاری","lst[100]","ممکن نیست"],["مناسب","داده کوچک با استفاده مکرر","جریان‌های بزرگ یا بی‌پایان"]]},{"k":"tip","title":"نکته منتور","t":"yield from را یاد بگیر — وقتی یک Generator می‌خواهد خروجی Generator دیگری را «رد کند»، یک خط جایگزین حلقه for می‌شود و ساختن Pipelineهای چندلایه را خوانا نگه می‌دارد. و itertools (islice، chain، groupby) کتابخانه‌ای است که Generatorها را به ابزار صنعتی تبدیل می‌کند."}]'::jsonb, '[{"q":"چرا Generator روی فایل ۱۰ گیگابایتی کار می‌کند ولی لیست نه؟","opts":["چون فشرده‌سازی می‌کند","چون داده را درخواستی و یکی‌یکی تولید می‌کند — حافظه O(1) می‌ماند","چون دیسک سریع‌تر است","چون موازی است"],"ans":1,"why":"yield بعد از هر قلم متوقف می‌شود؛ مصرف‌کننده بعدی را بخواهد تا قلم بعدی ساخته شود. هیچ‌وقت کل مجموعه در RAM وجود ندارد."},{"q":"Generator تمام‌شده چه ویژگی‌ای دارد؟","opts":["دوباره از اول شروع می‌شود","یک‌بار مصرف است؛ پیمایش دوم خالی است — باید دوباره ساخته شود","کش می‌شود","خطا می‌دهد"],"ans":1,"why":"Generator وضعیت پیمایش را نگه می‌دارد و به انتها که برسد، StopIteration می‌دهد؛ برعکس لیست که هر بار از نو پیمایش می‌شود."}]'::jsonb),
('py-b1', 'py', 'رشته‌ها و قالب‌بندی مدرن', 63, 12, '[{"k":"p","t":"رشته‌ها تغییرناپذیرند و هر عملیات، رشته‌ای تازه می‌سازد. f-string خوانا‌ترین راه قالب‌بندی و join سریع‌ترین راه چسباندن است."},{"k":"h","t":"تغییرناپذیری یعنی چه، و چرا به قیمت‌اش می‌ارزد"},{"k":"p","t":"وقتی می‌گویی s = s + ''x''، پایتون رشته قبلی را دست نمی‌زند؛ یک رشته کاملاً تازه با کپیِ هر دو بخش می‌سازد و نام s را به آن وصل می‌کند. این «تغییرناپذیری» (Immutability) در نگاه اول اسراف به نظر می‌رسد، ولی سه هدیه بزرگ دارد: رشته‌ها قابل‌اعتمادند (هیچ کدی نمی‌تواند از پشت صحنه تغییرشان دهد)، قابل‌هش‌اند (پس کلید dict و عنصر set می‌شوند) و هم‌رسانی‌شان بدون قفل امن است. هزینه واقعی جایی ظاهر می‌شود که در حلقه، رشته را با + بزرگ کنی: n بار جمع یعنی ۱+۲+۳+...+n کپی — یعنی O(n²). برای چسباندن چند تکه، join راه درست است چون از اول اندازه نهایی را می‌داند و یک‌بار حافظه می‌گیرد."},{"k":"h","t":"فشار دادن کل زبانِ قالب‌بندی داخل f-string"},{"k":"p","t":"f-string فقط «جاگذاری متغیر» نیست — یک زبان قالب‌بندی کامل است. بعد از متغیر، دونقطه مشخصات می‌آورد: {x:,.0f} عدد را با جداکننده هزارگان و بدون اعشار می‌نویسد، {name:>12} در عرض ۱۲ راست‌چین می‌کند (^ وسط، < چپ)، {pct:.1%} عدد را به درصد تبدیل می‌کند و {d:%Y/%m/%d} تاریخ را قالب می‌دهد. حتی می‌توانی {x=} بنویسی تا خودِ عبارت هم چاپ شود (برای دیباگ عالی است: name=''ali''). قاعده خوانایی: اگر قالب از یک مشخصه ساده رد شد، یا format() جدا استفاده کن یا نتیجه را در متغیر بریز — f-string طولانی و تو در تو، ضدِ هدفِ خودش یعنی خوانایی است."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"ساخت گزارش از داده خام","code":"rows = [(''  لپ‌تاپ '', 12995000, 3), ('' موس '', 850000, 12)]\n\n# پاک‌سازی + قالب‌بندی در یک comprehension\nreport = ''\\n''.join(\n    f''{name.strip():<10} | {price:>12,} | {price*qty:>14,}''\n    for name, price, qty in rows\n)\ntotal = sum(p * q for _, p, q in rows)\nprint(report)\nprint(f''{\"جمع\":<10} | {\"\":>12} | {total:>14,}'')"},{"k":"def","term":"آمورتیزه (Amortized)","t":"وقتی هزینه یک عمل «به‌طور میانگین در درازمدت» کم است حتی اگر گاهی گران باشد؛ مثل join که یک‌بار هزینه بزرگ می‌کند ولی هر عضو تقریباً رایگان اضافه می‌شود."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["f''{price:,.0f}'' عدد را با جداکننده هزارگان قالب می‌کند","join روی لیست از جمع با + در حلقه بسیار سریع‌تر است","strip و split و replace ابزارهای پالایش متن‌اند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"strings.py","code":"name, price = ''لپ‌تاپ'', 1299.5\nprint(f''{name}: {price:,.0f} تومان'')\nprint('' | ''.join([''برق'', ''کامپیوتر'']))\nprint(''  سلام  ''.strip())"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: f''{price:,.0f}'' عدد را با جداکننده هزارگان قالب می‌کند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا join از جمع رشته در حلقه سریع‌تر است؟","opts":["کوتاه‌تر است","یک‌بار حافظه می‌گیرد نه کپی در هر تکرار","فشرده می‌کند","فرقی ندارد"],"ans":1,"why":"جمع با + در هر تکرار رشته تازه می‌سازد؛ join اندازه را از قبل می‌داند و یک‌جا می‌سازد."},{"q":"چرا s += c در حلقه برای n کاراکتر، O(n²) می‌شود؟","opts":["چون رشته فشرده می‌شود","چون هر جمع، کل رشته قبلی را در رشته‌ای تازه کپی می‌کند — جمع کپی‌ها مثلثی رشد می‌کند","چون حافظه پر می‌شود","نمی‌شود؛ خطی است"],"ans":1,"why":"رشته تغییرناپذیر است؛ هر بار کل محتوای قبلی کپی می‌شود. ۱+۲+...+n کپی یعنی O(n²) — ولی join همه را یک‌جا و خطی می‌سازد."},{"q":"خروجی f''{0.456:.1%}'' چیست؟","opts":["0.5%","45.6%","0.456%","45%"],"ans":1,"why":"مشخصه % اول عدد را در ۱۰۰ ضرب می‌کند (تبدیل به درصد) و .1 یک رقم اعشار نگه می‌دارد — پس 45.6%."}]'::jsonb),
('py-b2', 'py', 'لیست‌ها و Comprehension', 63, 13, '[{"k":"p","t":"لیست پرکاربرد‌ترین ساختار پایتون است و comprehension راهی فشرده برای ساخت لیست از یک دنباله — به‌شرطی که آن‌قدر پیچیده نشود که خوانایی از بین برود."},{"k":"h","t":"لیست پایتون آرایه نیست — آرایه‌ای از اشاره‌گرهاست"},{"k":"p","t":"در دل list پایتون، یک آرایه پیوسته از «اشاره‌گر به اشیا» نهفته، نه خود اشیا. این طراحی دو پیامد مهم دارد: اول، لیست می‌تواند انواع مخلوط نگه دارد چون فقط آدرس‌ها پشت‌سرهم‌اند؛ دوم، وقتی لیست پر می‌شود و append می‌زنی، پایتون ظرفیت را حدود ۱.۱۲۵ برابر می‌کند و اشاره‌گرها را جابه‌جا می‌کند — این رشد هندسی است که append را آمورتیزه O(1) نگه می‌دارد. ولی حذف از سر (pop(0)) همه اشاره‌گرها را یکی جلو می‌کشد: O(n). همین یک واقعیت ساده، دلیل وجود deque است و مرز بین «لیست خوب» و «صف بد» را تعیین می‌کند."},{"k":"h","t":"Comprehension: قدرت و نقطه شکستش"},{"k":"p","t":"Comprehension زیباست چون «ساختن یک مجموعه از یک دنباله با شرط و تبدیل» را در یک عبارت بیان می‌کند — دقیقاً همان‌طور که در ریاضی می‌نویسی {x² | x ∈ S, x > 0}. ولی نقطه شکستش مشخص است: لحظه‌ای که برای خواندنش مجبور شوی انگشت بگذاری و دنبال متغیرها بگردی، باید به حلقه معمولی برگردی. دو قاعده عملی: comprehension تو در تو فقط اگر «جدول» باشد (دو for در دو خط) و هر comprehension بیشتر از حدود ۸۰ کاراکتر، کاندیدای تبدیل‌شدن به حلقه یا تابع کوچک است. و هرگز داخل comprehension اثر جانبی نگذار — print یا append به لیست بیرونی؛ آن دیگر comprehension نیست، حلقه‌ای است که لباس عوض کرده."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"پاک‌سازی و تبدیل داده با ابزارهای پیمایش","code":"names  = [''  سارا '', ''علی'', ''نگار  '']\nscores = [18.5, 12, 19.75]\n\n# جفت‌سازی + پالایش + تبدیل در یک comprehension\naccepted = {\n    name.strip(): round(score)\n    for name, score in zip(names, scores)\n    if score >= 14\n}\nprint(accepted)   # {''سارا'': 18, ''نگار'': 20}\n\n# پیمایش با ایندکس وقتی واقعاً لازم است\nfor i, (n, s) in enumerate(zip(names, scores)):\n    print(f''{i + 1}. {n.strip()} — {s}'')"},{"k":"def","term":"زیپ (Zip)","t":"چند دنباله را قفل‌به‌قفل جفت می‌کند؛ طول خروجی برابر کوتاه‌ترین ورودی است. zip(a, b, strict=True) از جاوا ۱۰… نه — پایتون ۳.۱۰ به بعد، در نابرابری طول خطا می‌دهد."},{"k":"warn","title":"دام رایج","t":"لیست را حین پیمایش حذف نکن: for x in lst: lst.remove(x) عنصرها را رد می‌کند چون ایندکس‌ها زیر پایت جابه‌جا می‌شوند. یا روی کپی بگرد (for x in lst[:]) یا comprehension وارونه بساز: lst = [x for x in lst if x != bad]."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["[x*2 for x in nums if x>0] یک comprehension کامل است","nums[::-1] لیست را معکوس می‌کند","enumerate برای پیمایش با ایندکس و zip برای جفت‌سازی"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"lists.py","code":"nums = [3, -1, 4, -5, 9]\npos = [x for x in nums if x > 0]\nfor i, v in enumerate(pos):\n    print(i, v)"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: [x*2 for x in nums if x>0] یک comprehension کامل است بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"خروجی [x for x in range(5) if x % 2 == 0] چیست؟","opts":["[1,3]","[0,2,4]","[2,4]","[0,1,2]"],"ans":1,"why":"range(5) یعنی ۰ تا ۴ و شرط زوج، ۰ و ۲ و ۴ را نگه می‌دارد."},{"q":"چرا pop(0) روی لیست O(n) است ولی popleft در deque برابر O(1)؟","opts":["deque جدیدتر است","چون لیست باید همه اشاره‌گرها را یکی جلو بکشد؛ deque ساختار حلقه‌ای/دوسری دارد که سر را مستقیم برمی‌دارد","فرقی ندارند","لیست مرتب است"],"ans":1,"why":"حذف از سر آرایه یعنی شیفت کل عناصر؛ deque برای حذف از دو سر طراحی شده — برای صف همیشه deque."},{"q":"کدام نسخه خواناتر است؟","opts":["[f(x) for x in xs if g(x) if h(x) if k(x)]","یک comprehension ساده یا حلقه با شرط‌های ترکیب‌شده و نام‌دار","هر دو یکسان","نسخه طولانی‌تر"],"ans":1,"why":"زنجیره ifهای متعدد خواننده را مجبور به بازسازی منطق می‌کند؛ ترکیب شرط‌ها در یک عبارت boolean یا شکستن به حلقه، خوانایی را برمی‌گرداند."}]'::jsonb),
('py-b3', 'py', 'دیکشنری و مجموعه', 63, 14, '[{"k":"p","t":"dict نگاشت کلید به مقدار با دسترسی O(1) و set مجموعه‌ای بدون تکرار است. این دو، ستون پردازش داده در پایتون‌اند."},{"k":"h","t":"زیر کاپوت dict: چرا کلید باید تغییرناپذیر باشد"},{"k":"p","t":"دیکشنری پایتون جدول هش است: تابع hash کلید را به عدد و عدد به ایندکس آرایه‌ای از bucketها تبدیل می‌کند. حالا فرض کن کلید، یک لیست قابل‌تغییر بود؛ بعد از درج تغییرش می‌دادی — hash عوض می‌شد و آن ورودی برای همیشه در خانه‌ای گم می‌شد که دیگر هیچ‌کس دنبالش نمی‌گردد! به همین دلیل پایتون فقط اشیای hashable (تغییرناپذیر مثل str، int، tuple) را کلید می‌پذیرد. ضریب بار (نسبت ورودی به ظرفیت) که از حدود ⅔ رد شود، جدول بزرگ می‌شود و همه کلیدها دوباره پخش می‌شوند — پس dict با ظرفیت تقریبی شناخته‌شده، کمی سریع‌تر شروع می‌کند."},{"k":"h","t":"الگوهای پردازش داده با set و ابزارهای collections"},{"k":"p","t":"set یک سلاح unterschätzte… یعنی کم‌قدرشناخته برای مسائل واقعی است: حذف تکراری‌ها یک خط است (list(set(xs)) — ولی ترتیب می‌پرد؛ برای حفظش dict.fromkeys)، مقایسه دو دیتاست با عملگرهای مجموعه انجام می‌شود (a - b چه چیزی اضافه شده، a & b مشترکات) و تست عضویت O(1) است نه O(n) لیست. در کنارش Counter برای شمارش و پرکاربردترین‌ها (most_common)، و defaultdict برای گروه‌بندی بدون if «آیا کلید هست؟». این چهار ابزار — dict، set، Counter، defaultdict — حدود ۸۰٪ پردازش داده روزمره پایتون را پوشش می‌دهند و معمولاً جایگزین حلقه‌های تو در تو و دیکشنری‌های دستی‌اند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"گزارش تکرارها و اختلاف دو لیست","code":"from collections import Counter, defaultdict\n\norders = [(''سارا'', ''کتاب''), (''علی'', ''دفتر''), (''سارا'', ''خودکار''),\n          (''سارا'', ''کتاب'')]\n\nby_customer = defaultdict(list)\nfor name, item in orders:\n    by_customer[name].append(item)\nprint(by_customer[''سارا''])          # [''کتاب'', ''خودکار'', ''کتاب'']\n\nprint(Counter(i for _, i in orders))   # Counter({''کتاب'': 2, ...})\n\nold = {''کتاب'', ''دفتر''}\nnew = {''کتاب'', ''خودکار''}\nprint(new - old)    # {''خودکار''} — اضافه‌شده\nprint(old & new)    # {''کتاب''} — مشترک"},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["نیاز","ابزار","نکته"],"rows":[["شمارش تکرار","Counter","most_common(k) برای k تای برتر"],["گروه‌بندی","defaultdict(list)","بدون if «کلید هست؟»"],["حذف تکراری با حفظ ترتیب","dict.fromkeys(xs)","set ترتیب را می‌پرد"],["اختلاف/اشتراک دیتا","عملگرهای set","O(1) برای هر عضویت"]]},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["d.get(k, default) از KeyError جلوگیری می‌کند","defaultdict شمارنده‌ها را ساده می‌کند","set برای حذف تکراری و تست عضویت O(1) عالی است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"dict.py","code":"from collections import Counter\nwords = [''سیب'', ''گلابی'', ''سیب'']\nprint(Counter(words))\nd = {''a'': 1}\nprint(d.get(''b'', 0))"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: d.get(k, default) از KeyError جلوگیری می‌کند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"پیچیدگی دسترسی به مقدار dict با کلید چیست؟","opts":["O(n)","O(1) میانگین","O(log n)","O(n²)"],"ans":1,"why":"dict از هش استفاده می‌کند؛ در حالت میانگین جای کلید در یک محاسبه پیدا می‌شود."},{"q":"چرا لیست نمی‌تواند کلید dict باشد ولی tuple می‌تواند؟","opts":["tuple جدیدتر است","چون کلید باید hashable و تغییرناپذیر باشد؛ لیست با تغییرش هش را بی‌معنی می‌کند","لیست بزرگ‌تر است","ممکن نیست"],"ans":1,"why":"هش باید در طول عمر کلید ثابت بماند؛ تغییر کلید یعنی گم‌شدن دائمی ورودی. tuple تغییرناپذیر است پس هش‌پذیر."},{"q":"پیچیدگی «آیا x در این set هست؟» در برابر لیست چقدر است؟","opts":["هر دو O(n)","set برابر O(1) میانگین (هش مستقیم) در برابر O(n) لیست (پیمایش)","لیست سریع‌تر","بستگی به اندازه"],"ans":1,"why":"set مستقیم به bucket می‌پرد؛ لیست باید دانه‌دانه مقایسه کند. برای تست عضویت مکرر، تبدیل لیست به set سرمایه‌گذاری است."}]'::jsonb),
('py-b4', 'py', 'مدیریت خطا و استثناها', 63, 15, '[{"k":"p","t":"try/except راه برخورد با خطاهای قابل‌پیش‌بینی است. اصل: فقط جایی که واقعاً می‌توانی برخورد کنی بگیر، و هرگز except برهنه ننویس."},{"k":"h","t":"فلسفه EAFP؛ نگاه پایتونی به خطا"},{"k":"p","t":"دو مکتب برخورد با خطا هست: LBYL یعنی «اول نگاه کن بعد بپر» (if os.path.exists: open(...)) و EAFP یعنی «بپر و موقع فرود گرفتن بگیر» (try: open(...) except FileNotFoundError). پایتون طرفدار صریح دومی است — حتی ضرب‌المثلش هست: «درخواست بخشش راحت‌تر از کسب اجازه است». دلیل فنی: در LBYL بین چک و استفاده، وضعیت می‌تواند عوض شود (فایل را کسی پاک کند — race condition) و تازه در مسیرِ عادی هم هزینه چک می‌دهی؛ در EAFP مسیر عادی هیچ سرباری ندارد و فقط شکست هزینه دارد. استثنا در پایتون «گران» نیست؛ گران، مدیریت اشتباه آن است."},{"k":"h","t":"طراحی جریان خطا: پرتاب کن، زنجیره کن، پاک‌سازی کن"},{"k":"p","t":"سه مهارت حرفه‌ای: اول، استثناهای دقیق و معنادار پرتاب کن — raise ValueError(''سن باید مثبت باشد'') نه برگرداندن -1 که معنی‌اش در امضای تابع گم می‌شود؛ و برای دامنه‌ات استثناهای سفارشی بساز (class OrderError(Exception)) تا گیرنده بتواند دقیق بگیرد. دوم، زنجیره‌کردن: وقتی خطای سطح پایین را به خطای سطح خودت ترجمه می‌کنی، بنویس raise OrderError(''ثبت سفارش شکست خورد'') from e تا ردپای خطای اصلی حفظ شود — بدون from، زنجیره گسسته می‌شود و دیباگ سخت. سوم، finally و context manager برای پاک‌سازی؛ و برای نادیده‌گرفتنِ آگاهانه یک خطای مشخص، contextlib.suppress(FileNotFoundError) — تمیزتر از try/except: pass."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"ترجمه خطا با زنجیره و پاک‌سازی مطمئن","code":"class ConfigError(Exception):\n    pass\n\ndef read_port(path):\n    try:\n        with open(path, encoding=''utf-8'') as f:\n            return int(f.read().strip())\n    except FileNotFoundError as e:\n        raise ConfigError(f''فایل پیکربندی نیست: {path}'') from e\n    except ValueError as e:\n        raise ConfigError(''مقدار port عدد نیست'') from e\n\ntry:\n    port = read_port(''app.conf'')\nexcept ConfigError as e:\n    print(''پیکربندی خراب:'', e)        # __cause__ خطای اصلی را دارد"},{"k":"def","term":"زنجیره استثنا (Exception Chaining)","t":"هر استثنا می‌تواند __cause__ داشته باشد — خطایی که باعثش شد. raise X from y این زنجیره را می‌سازد و traceback هر دو را چاپ می‌کند؛ بدون آن، ریشه مشکل در ترجمه گم می‌شود."},{"k":"warn","title":"دام رایج","t":"except Exception: pass یعنی خفه‌کردن خطا — برنامه «کار می‌کند» ولی داده خراب است و هیچ ردی نیست. اگر واقعاً چاره‌ای نداری، حداقل لاگ کن: logging.exception() خودِ stack trace را ثبت می‌کند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["except ValueError as e خطا را برای لاگ در دسترس می‌گذارد","finally برای پاک‌سازی همیشه اجرا می‌شود","raise برای پرتاب عمدی و ساخت استثناهای سفارشی"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"errors.py","code":"try:\n    n = int(input())\nexcept ValueError as e:\n    print(''عدد نیست:'', e)\nelse:\n    print(''ok:'', n * 2)\nfinally:\n    print(''done'')"},{"k":"warn","title":"هشدار","t":"except: بدون نوع، همه‌چیز حتی KeyboardInterrupt را می‌گیرد و دیباگ را غیرممکن می‌کند — همیشه نوع مشخص بده."},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: except ValueError as e خطا را برای لاگ در دسترس می‌گذارد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"except برهنه چرا خطرناک است؟","opts":["کند است","همه خطاها حتی خروج برنامه را می‌گیرد","کامپایل نمی‌شود","حافظه می‌گیرد"],"ans":1,"why":"except: همه‌چیز را می‌گیرد و خطاهای واقعی را پنهان می‌کند؛ همیشه نوع استثنا را مشخص کن."},{"q":"چه زمانی finally اجرا نمی‌شود؟","opts":["وقتی خطا نگیریم","تقریباً هیچ‌وقت — حتی با return داخل try هم اجرا می‌شود؛ فقط os._exit و کشته‌شدن process","وقتی else باشد","همیشه اجرا می‌شود بدون استثنا"],"ans":1,"why":"finally برای پاک‌سازی طراحی شده و تقریباً در هر جریانی (خطا، return، حتی break) اجرا می‌شود — به‌جز خروج سخت از process."},{"q":"raise X from e چه چیزی اضافه می‌کند؟","opts":["سرعت","زنجیره: X.__cause__ برابر e می‌شود و traceback هر دو خطا چاپ می‌شود","catch خودکار","هیچ"],"ans":1,"why":"بدون from، وقتی خطای سطح پایین را ترجمه می‌کنی ریشه‌اش گم می‌شود؛ from ردپای کامل را تا علت اصلی نگه می‌دارد."}]'::jsonb),
('py-b5', 'py', 'فایل‌ها و JSON', 56, 16, '[{"k":"p","t":"with open ساختار امن کار با فایل است چون حتی در خطا، فایل را می‌بندد. ماژول json برای خواندن و نوشتن داده ساختاریافته استاندارد است."},{"k":"h","t":"چرا with و نه open ساده"},{"k":"p","t":"بازکردن فایل منبعی است که باید بسته شود؛ اگر وسط کار خطایی پرتاب شود و تو close را در finally نگذاشته باشی، فایل باز می‌ماند و در سیستم‌عامل تعداد فایل‌های باز محدود است. مدیریت‌گر زمینه (with) این را تضمین می‌کند: چه کار تمام شود چه خطا بیفتد، __exit__ صدا زده و فایل بسته می‌شود. پس with نه یک سینتکس خوشگل، بلکه تضمینِ درست‌بودن است."},{"k":"h","t":"encoding؛ جایی که فارسی می‌شکند"},{"k":"p","t":"متن در دیسک بایت است و encoding قرارداد تبدیل بایت به کاراکتر. اگر encoding را مشخص نکنی، پایتون از پیش‌فرض سیستم می‌گیرد که در ویندوز اغلب cp1256 یا latin است و فارسی را به‌هم می‌ریزد یا UnicodeDecodeError می‌دهد. قاعده: برای هر فایل متنی، صریحاً encoding=''utf-8'' بنویس — UTF-8 استاندارد وب و تقریباً همه ابزارهای مدرن است."},{"k":"def","term":"JSON","t":"قالب متنیِ استاندارد برای داده ساختاریافته (شیء، آرایه، عدد، رشته). چون زبانی مستقل است، برای تبادل داده بین پایتون و جاوااسکریپت و ذخیره تنظیمات استفاده می‌شود. json.load/dump برای فایل و json.loads/dumps برای رشته است."},{"k":"tip","title":"نکته منتور","t":"برای ذخیره فارسی، ensure_ascii=False را بگذار تا کاراکترها خوانا ذخیره شوند نه به‌صورت \\uXXXX. و هنگام خواندن تنظیمات، همیشه .get با مقدار پیش‌فرض استفاده کن تا کلیدِ غایب برنامه را کرش نکند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["with open(...) as f تضمین بستن فایل است","json.load از فایل و json.loads از رشته می‌خواند","encoding=''utf-8'' برای متن فارسی ضروری است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"files.py","code":"import json\nwith open(''data.json'', encoding=''utf-8'') as f:\n    data = json.load(f)\ndata[''count''] += 1\nwith open(''data.json'', ''w'', encoding=''utf-8'') as f:\n    json.dump(data, f, ensure_ascii=False)"},{"k":"tip","title":"نکته منتور","t":"ensure_ascii=False را بگذار تا فارسی به‌جای \\uXXXX خوانا ذخیره شود."},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: with open(...) as f تضمین بستن فایل است بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا with open توصیه می‌شود؟","opts":["سریع‌تر است","بستن فایل را حتی در خطا تضمین می‌کند","فایل را کوچک می‌کند","اجباری است"],"ans":1,"why":"بدون with اگر وسط کار خطا بیفتد فایل باز می‌ماند؛ with در هر صورت می‌بندد."},{"q":"چرا json.loads با json.load فرق دارد؟","opts":["هیچ","loads از رشته و load از فایلِ بازخوانده‌شده می‌خواند؛ s مخفف string است","سرعت","نسخه‌های متفاوت"],"ans":1,"why":"این دو برای دو منبع ورودی‌اند؛ اگر داده‌ات رشته است (مثلاً از یک API) از loads و اگر فایل است از load استفاده می‌کنی — انتخاب اشتباه خطای نوع می‌دهد."},{"q":"اگر فایلی فارسی با encoding اشتباه خوانده شود چه می‌شود؟","opts":["خودکار درست می‌شود","یا کاراکترها به‌هم می‌ریزند یا UnicodeDecodeError می‌گیری؛ راه‌حل صریح‌کردن encoding=''utf-8'' است","فایل پاک می‌شود","کند می‌شود"],"ans":1,"why":"پایتون باید بداند بایت‌ها را چطور به کاراکتر تبدیل کند؛ بدون encoding صریح، پیش‌فرض سیستم ممکن است با UTF-8 فایل جور درنیاید و نتیجه خرابی متن یا خطا است."}]'::jsonb),
('py-b6', 'py', 'ماژول‌ها و بسته‌ها', 63, 17, '[{"k":"p","t":"هر فایل .py یک ماژول است و import ابزار استفاده از کد دیگران یا کد قبلی خودت. ساختار درست پروژه، تفاوت کد اسباب‌بازی و کد حرفه‌ای است."},{"k":"h","t":"import دقیقاً چه می‌کند"},{"k":"p","t":"وقتی import utils می‌نویسی، پایتون فایل utils.py را یک‌بار اجرا و فضای نامش را به‌عنوان یک شیء در دسترس می‌گذارد؛ دفعات بعد همان شیء کش‌شده برمی‌گردد. پس import همزمان «اجرا» هم هست — هر کدی در سطح ماژول (خارج از تابع) همان لحظه اجرا می‌شود. این یعنی اگر در سطح ماژول اتصال دیتابیس بسازی، فقط با import کردنش اجرا می‌شود — پس کدِ اثردار را داخل تابع یا پشت __main__ بگذار."},{"k":"h","t":"from import و خطای نام"},{"k":"p","t":"from utils import clean فقط نام clean را به فضای نام فعلی می‌آورد، نه کل ماژول را. راحت است ولی اگر دو ماژول هم‌نام داشته باشند یا نامی را وارد کنی و یادت برود از کجاست، خوانایی کم می‌شود. قاعده عملی: import ماژول (و صدا با نقطه) برای شفافیت؛ from import فقط وقتی یک‌دو نام پرکاربرد است. و هرگز from x import * — چون فضای نام را بی‌سروصدا آلوده می‌کند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"ساختار یک پروژه واقعی","code":"myproj/\n├── src/myproj/\n│   ├── __init__.py      # این پوشه را بسته می‌کند\n│   ├── core.py\n│   └── utils.py\n├── tests/\n│   └── test_core.py\n├── requirements.txt     # وابستگی‌ها\n└── pyproject.toml       # متادیتا و ابزارها\n\n# اجرا به‌صورت بسته (نه فایل مستقیم):\n#   python -m myproj.core"},{"k":"tip","title":"نکته منتور","t":"اجرای python -m package.module به‌جای python file.py، ریشه بسته را درست تنظیم می‌کند و importهای داخلی را از خطای ModuleNotFoundError نجات می‌دهد — به‌ویژه وقتی پروژه چند پوشه دارد."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["from x import y فقط نام موردنیاز را می‌آورد","__name__ == ''__main__'' اجرای شرطی هنگام اسکریپت‌بودن","requirements.txt فهرست وابستگی‌های پروژه است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"main.py","code":"# utils.py را در همان پوشه فرض کن\nfrom utils import clean\nimport utils\n\nif __name__ == ''__main__'':\n    print(clean(''  a  ''))"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: from x import y فقط نام موردنیاز را می‌آورد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"__name__ چه زمانی برابر ''__main__'' است؟","opts":["همیشه","وقتی فایل مستقیم اجرا شود نه import شود","وقتی import شود","هیچ‌وقت"],"ans":1,"why":"پایتون فایل اجراشده را __main__ می‌نامد؛ فایل‌های import‌شده نام خودشان را دارند."},{"q":"چرا کد اثردار (مثل اتصال به سرور) را نباید در سطح ماژول نوشت؟","opts":["کند است","چون با هر import اجرا می‌شود؛ حتی اگر فقط می‌خواستی یک تابع را استفاده کنی — باید پشت تابع یا __main__ برود","اجازه ندارد","حافظه می‌گیرد"],"ans":1,"why":"import اجراست؛ پس هر چیزی در سطح ماژول، به‌محض import شدنِ ماژول انجام می‌شود. اگر کسی فقط یک تابع بخواهد، ناخواسته اتصال هم برقرار می‌شود — پس اثرها را عقب بینداز."},{"q":"نقش __init__.py چیست؟","opts":["سازنده است","به پایتون می‌گوید این پوشه یک بسته است و هنگام import بسته اجرا می‌شود؛ می‌تواند نام‌های عمومی را هم export کند","اجباری نیست دیگر","فقط برای تست"],"ans":1,"why":"این فایل مرز بسته را تعریف می‌کند؛ محتوایش (حتی خالی) هنگام importِ بسته اجرا می‌شود و می‌توانی در آن with __all__ مشخص کنی چه نام‌هایی عمومی‌اند."}]'::jsonb),
('py-b7', 'py', 'شی‌گرایی: کلاس و شیء', 63, 18, '[{"k":"p","t":"کلاس قالب ساخت اشیا و شیء نمونه‌ای از آن است. __init__ سازنده است و self به نمونه جاری اشاره می‌کند."},{"k":"h","t":"self؛ چرا همیشه اولین پارامتر است"},{"k":"p","t":"وقتی p.discount(10) را صدا می‌زنی، پایتون آن را به Product.discount(p, 10) تبدیل می‌کند — یعنی شیء فراخواننده را به‌عنوان اولین آرگومان پاس می‌دهد و نامش را self می‌گذاریم (یک قرارداد، نه کلمه رزرو). پس self یعنی «همین شیء». بدون self، متد نمی‌داند روی کدام نمونه کار می‌کند؛ به همین دلیل متدهای نمونه همیشه آن را می‌گیرند و فراموش‌کردنش خطای معروف «takes 1 positional argument but 2 were given» است."},{"k":"h","t":"dataclass؛ حذف boilerplate"},{"k":"p","t":"برای کلاس‌هایی که فقط داده نگه می‌دارند، نوشتن __init__ و __repr__ و __eq__ تکراری و پرخطاست. dataclass با یک دکوراتور همه این‌ها را از روی type hintها می‌سازد و کد را به چند خط می‌رساند. نکته مهم: dataclass فقط زمانی درست مقایسه می‌کند که فیلدها را با نوع اعلام کرده باشی؛ و برای داده تغییرناپذیر، frozen=True را بگذار تا مثل record رفتار کند و قابل hash شود."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"کلاس معمولی در برابر dataclass","code":"from dataclasses import dataclass\n\n# قبل — ۱۲ خط boilerplate:\nclass PointOld:\n    def __init__(self, x, y):\n        self.x, self.y = x, y\n    def __eq__(self, o):\n        return (self.x, self.y) == (o.x, o.y)\n    def __repr__(self):\n        return f''Point({self.x}, {self.y})''\n\n# بعد — ۳ خط، همان رفتار + __repr__ و __eq__:\n@dataclass(frozen=True)\nclass Point:\n    x: float\n    y: float\n\np = Point(3, 4)\nprint(p)              # Point(x=3, y=4)\nprint(p == Point(3, 4))  # True"},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["متدها همیشه self را اولین پارامتر می‌گیرند","ویژگی‌های نمونه در __init__ با self.x ساخته می‌شوند","dataclass برای کلاس‌های داده‌محور boilerplate را حذف می‌کند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"oop.py","code":"class Product:\n    def __init__(self, name, price):\n        self.name = name\n        self.price = price\n    def discount(self, pct):\n        return self.price * (1 - pct / 100)\n\np = Product(''کتاب'', 200)\nprint(p.discount(10))"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: متدها همیشه self را اولین پارامتر می‌گیرند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"self در متد چیست؟","opts":["کلاس","اشاره به نمونه جاری","یک کلمه رزرو ثابت","مقدار بازگشتی"],"ans":1,"why":"self همان شیء‌ای است که متد رویش صدا شده؛ پایتون آن را خودکار پاس می‌دهد."},{"q":"پیام خطای «takes 1 positional argument but 2 were given» معمولاً نشانه چیست؟","opts":["آرگومان زیاد","فراموش‌کردن self در تعریف متد؛ پایتون شیء را هم پاس می‌دهد ولی متد جایی برایش ندارد","باگ پایتون","نوع اشتباه"],"ans":1,"why":"پایتون همیشه شیء فراخواننده را به‌عنوان آرگومان اول می‌فرستد؛ اگر در تعریف متد self ننوشته باشی، آن آرگومان جایی ندارد و همین خطا ظاهر می‌شود."},{"q":"چه زمانی frozen=True در dataclass مفید است؟","opts":["همیشه","وقتی داده تغییرناپذیر است؛ اشیا قابل hash می‌شوند (قابل‌استفاده در set و dict) و تغییر تصادفی‌شان غیرممکن می‌شود","برای سرعت","برای JSON"],"ans":1,"why":"تغییرناپذیری دو برد دارد: می‌توانی شیء را کلید dict یا عضو set کنی (نیاز به hash دارد) و خیالت راحت است که جایی از کد ناخواسته مقدارش عوض نمی‌شود."}]'::jsonb),
('py-b8', 'py', 'وراثت و چندریختی', 63, 19, '[{"k":"p","t":"وراثت اجازه می‌دهد کلاسی رفتار کلاس دیگر را بگیرد و گسترش دهد. چندریختی یعنی کد با نوع پایه کار کند و رفتار واقعی از نوع مشتق بیاید."},{"k":"h","t":"وراثت برای اشتراک رفتار، نه فقط کد"},{"k":"p","t":"وراثت می‌گوید این کلاس «نوعی از» آن کلاس است؛ پس باید بتواند überall جایگزینش شود (اصل جایگزینی). اگر Dog از Animal ارث ببرد، هر جا Animal انتظار می‌رود Dog هم کار کند. خطر رایج استفاده از وراثت فقط برای «کد مشترک» است وقتی رابطه «نوعی از» برقرار نیست — مثلاً ارث‌بردن Stack از List فقط برای استفاده از append؛ در این حالت ترکیب (داشتن یک لیست داخلی) درست‌تر از ارث‌بردن است."},{"k":"h","t":"چندریختی؛ قدرت واقعی وراثت"},{"k":"p","t":"ارزش وراثت در چندریختی است: تابعی که با نوع پایه (Animal) کار می‌کند، با هر زیرکلاسی (Dog، Cat) هم کار می‌کند بدون اینکه بداند دقیقاً چیست — رفتار واقعی در اجرا از نوع مشتق می‌آید. این یعنی اضافه‌کردن یک حیوان جدید هیچ تغییری در کدِ مصرف‌کننده نمی‌خواهد. اگر دیدی داری با if و بررسی نوع، رفتار زیرکلاس‌ها را جدا می‌کنی، احتمالاً داری از چندریختی درست استفاده نمی‌کنی."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"چندریختی بدون ifِ نوع","code":"from abc import ABC, abstractmethod\n\nclass Shape(ABC):\n    @abstractmethod\n    def area(self): ...\n\nclass Circle(Shape):\n    def __init__(self, r): self.r = r\n    def area(self): return 3.14159 * self.r ** 2\n\nclass Square(Shape):\n    def __init__(self, s): self.s = s\n    def area(self): return self.s ** 2\n\ndef total_area(shapes):\n    return sum(s.area() for s in shapes)  # نمی‌داند و نمی‌خواهد بداند چه شکلی‌اند\n\nprint(total_area([Circle(1), Square(2)]))  # 7.14..."},{"k":"tip","title":"نکته منتور","t":"وقتی می‌خواهی «مجبور کنی» زیرکلاس‌ها متدی را پیاده کنند، از ABC و @abstractmethod استفاده کن؛ اگر فراموش کنند، همان لحظه ساخت شیء خطا می‌گیرند نه وسط اجرا — کشف خطا هرچه زودتر، ارزان‌تر."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["super().__init__() سازنده پدر را صدا می‌کند","بازتعریف متد، رفتار را در فرزند عوض می‌کند","isinstance برای بررسی نوع و ABC برای کلاس انتزاعی"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"inherit.py","code":"class Animal:\n    def speak(self): return ''...''\nclass Dog(Animal):\n    def speak(self): return ''واق''\n\nfor a in [Animal(), Dog()]:\n    print(a.speak())   # چندریختی"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: super().__init__() سازنده پدر را صدا می‌کند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چندریختی چه فایده‌ای دارد؟","opts":["سرعت بیشتر","کد با نوع پایه کار می‌کند و رفتار از نوع واقعی می‌آید","حافظه کمتر","کد کوتاه‌تر می‌شود"],"ans":1,"why":"تابعی که Animal می‌گیرد با هر زیرکلاسی کار می‌کند بدون اینکه بداند دقیقاً چیست."},{"q":"چرا super().__init__() را در سازنده فرزند صدا می‌زنیم؟","opts":["اختیاری است","چون بخشِ به‌ارث‌برده‌شده شیء باید با منطق سازنده پدر مقداردهی شود؛ وگرنه فیلدهای پدر ساخته نمی‌شوند","برای سرعت","اجبار سینتکسی"],"ans":1,"why":"فرزند فقط فیلدهای خودش را در __init__ خودش می‌سازد؛ فیلدهای پدر را سازنده پدر می‌سازد. اگر super() را صدا نزنی، آن فیلدها وجود ندارند و دسترسی‌شان AttributeError می‌دهد."},{"q":"چه زمانی ترکیب بر وراثت اولویت دارد؟","opts":["هرگز","وقتی رابطه «نوعی از» برقرار نیست و فقط دنبال کد مشترک هستی — مثل Stack که نباید از List ارث ببرد ولی می‌تواند یک لیست داخلی داشته باشد","همیشه","وقتی کد کوتاه‌تر شود"],"ans":1,"why":"وراثت یک تعهد است: فرزند باید überall جایگزین پدر شود. اگر فقط کد مشترک می‌خواهی بدون این تعهد، ترکیب (نگه‌داشتن یک شیء داخلی) انعطاف‌پذیرتر و کم‌خطرتر است."}]'::jsonb),
('py-b9', 'py', 'دکوراتورها', 63, 20, '[{"k":"p","t":"دکوراتور تابعی است که تابعی دیگر را می‌گیرد و نسخه تقویت‌شده‌اش را برمی‌گرداند — بدون تغییر کد اصلی. برای لاگ، کش و زمان‌سنجی عالی است."},{"k":"h","t":"دکوراتور در یک جمله"},{"k":"p","t":"دکوراتور تابعی است که یک تابع می‌گیرد و یک تابع (معمولاً تقویت‌شده) برمی‌گرداند؛ نوشتن @timed بالای def work دقیقاً معادل work = timed(work) است. پس دکوراتور جایگزینِ تابع اصلی با نسخه‌ای می‌شود که قبل و بعد از آن کاری اضافه می‌کند — بدون اینکه بدنه اصلی دست بخورد. این جداسازی، قدرت اصلی‌اش است: منطق اصلی و منطق جانبی (لاگ، زمان، کش) جدا می‌مانند."},{"k":"h","t":"چرا functools.wraps لازم است"},{"k":"p","t":"وقتی timed تابع wrap را به‌جای work برمی‌گرداند، نام و docstring و امضای اصلی زیر آن گم می‌شود — پس work.__name__ می‌شود ''wrap'' و ابزارهای مستندسازی و دیباگ گیج می‌شوند. @functools.wraps(fn) این متادیتا را از تابع اصلی کپی می‌کند. بدون آن، دکوراتور کارش را می‌کند ولی هویت تابع را می‌دزدد — و ردیابی خطا در stacktrace سخت می‌شود."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"دکوراتور با آرگومان (یک لایه بیشتر)","code":"import functools\n\ndef retry(times):                    # دکوراتورِ سازنده‌ی دکوراتور\n    def deco(fn):\n        @functools.wraps(fn)\n        def wrap(*a, **k):\n            for i in range(times):\n                try:\n                    return fn(*a, **k)\n                except Exception:\n                    if i == times - 1: raise\n        return wrap\n    return deco                      # ← لایه اضافه برای گرفتن آرگومان\n\n@retry(times=3)\ndef fetch(url): ...\n# معادل: fetch = retry(times=3)(fetch)"},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["@name معادل f = name(f) است","functools.wraps نام و docstring اصلی را حفظ می‌کند","دکوراتور با آرگومان، یک لایه تابع دیگر می‌خواهد"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"deco.py","code":"import time, functools\ndef timed(fn):\n    @functools.wraps(fn)\n    def wrap(*a, **k):\n        t0 = time.perf_counter()\n        r = fn(*a, **k)\n        print(f''{fn.__name__}: {time.perf_counter()-t0:.4f}s'')\n        return r\n    return wrap\n\n@timed\ndef work(): return sum(range(10**6))\nwork()"},{"k":"tip","title":"نکته منتور","t":"بدون functools.wraps، نام و مستندات تابع اصلی زیر دکوراتور گم می‌شود و دیباگ سخت می‌شود."},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: @name معادل f = name(f) است بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"@timed دقیقاً معادل چیست؟","opts":["work = timed(work)","timed = work","work(timed)","هیچ‌کدام"],"ans":0,"why":"دکوراتور تابع را می‌گیرد و جایگزینش می‌کند؛ یعنی work = timed(work)."},{"q":"@retry(times=3) چه تفاوتی با @retry ساده دارد؟","opts":["هیچ","چون آرگومان می‌گیرد، یک لایه تابع اضافه لازم است: retry(times=3) اول اجرا و دکوراتور واقعی را برمی‌گرداند","سریع‌تر است","جدیدتر است"],"ans":1,"why":"دکوراتورِ ساده مستقیم تابع را می‌گیرد؛ ولی وقتی آرگومان دارد، باید اول آرگومان‌ها را بگیری و دکوراتور بسازی — پس سه سطح تابع می‌شود: سازنده، دکوراتور، و wrapper."},{"q":"کدام کار برای دکوراتور مناسب نیست؟","opts":["لاگ‌کردن فراخوانی‌ها","تغییر منطق اصلی تابع به‌شکلی که رفتارش غیرقابل‌پیش‌بینی شود — دکوراتور باید رفتار را شفاف تقویت کند نه پنهان‌کاری","زمان‌سنجی","کش‌کردن نتیجه"],"ans":1,"why":"قدرت دکوراتور در شفافیت است: خواننده می‌داند @logged یعنی لاگ. اگر دکوراتور رفتار را بی‌سروصدا عوض کند، دیگر جداسازیِ تمیز نیست — بلکه دامی برای دیباگ."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('py-b10', 'py', 'ژنراتورها و پیمایش تنبل', 63, 21, '[{"k":"p","t":"ژنراتور دنباله‌ای است که مقادیر را یکی‌یکی و در لحظه نیاز تولید می‌کند؛ برای داده‌های بزرگ، حافظه را از O(n) به O(1) می‌رساند."},{"k":"h","t":"yield؛ توقف و ادامه"},{"k":"p","t":"تابعی که yield دارد ژنراتور است: وقتی به yield می‌رسد، مقداری برمی‌گرداند و «متوقف» می‌شود — همه متغیرهای محلی‌اش زنده می‌مانند — و دفعه بعد که از آن مقدار بخواهی، از همان‌جا ادامه می‌دهد. پس برخلاف return که تابع را تمام می‌کند، yield آن را معلق نگه می‌دارد. این یعنی می‌توانی دنباله‌ای بی‌نهایت یا خیلی بزرگ را تعریف کنی بدون اینکه همه‌اش را یک‌جا در حافظه بسازی."},{"k":"h","t":"حافظه O(1) برای داده بزرگ"},{"k":"p","t":"اگر بخواهی مربعِ ده میلیون عدد را جمع بزنی، ساختن لیست یعنی ده میلیون عدد همزمان در حافظه؛ ولی (x*x for x in range(10**7)) یک generator expression است که هر بار فقط یک عدد می‌سازد — حافظه ثابت می‌ماند. قاعده: وقتی فقط یک‌بار پیمایش می‌کنی و کل داده لازم نیست، ژنراتور بزن؛ وقتی چندبار یا با ایندکس لازم داری، لیست."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"خواندن فایل بزرگ، خط به خط","code":"def big_lines(path):\n    with open(path, encoding=''utf-8'') as f:\n        for line in f:          # خودِ f یک ژنراتورِ خط است!\n            if len(line) > 1000:\n                yield line.strip()\n\n# حتی اگر فایل ۱۰ گیگابایت باشد، حافظه ثابت است\nfor line in big_lines(''huge.log''):\n    process(line)              # هر لحظه فقط یک خط در حافظه"},{"k":"tip","title":"نکته منتور","t":"فایل‌باز در پایتون خودش پیمایش‌پذیرِ تنبل است — for line in f هر بار فقط یک خط می‌خواند. پس هیچ‌وقت f.readlines() را برای فایل بزرگ نزن؛ همان حلقه مستقیم، هم ساده‌تر است هم حافظه‌اش ثابت."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["yield تابع را به ژنراتور تبدیل می‌کند","ژنراتور یک‌بار مصرف است؛ بعد از پیمایش تمام می‌شود","generator expression مثل (x for x in ...) تنبل است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"gen.py","code":"def countdown(n):\n    while n > 0:\n        yield n\n        n -= 1\n\nfor v in countdown(3):\n    print(v)\nsquares = (x * x for x in range(10**7))  # حافظه O(1)"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: yield تابع را به ژنراتور تبدیل می‌کند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"مزیت ژنراتور بر لیست برای داده بزرگ چیست؟","opts":["سریع‌تر جمع می‌زند","مقادیر را در لحظه نیاز می‌سازد و حافظه O(1) دارد","مرتب‌تر است","قابل‌تکرارتر است"],"ans":1,"why":"ژنراتور همه داده را یک‌جا در حافظه نگه نمی‌دارد؛ هر مقدار را هنگام درخواست تولید می‌کند."},{"q":"تفاوت اصلی return و yield چیست؟","opts":["سینتکس","return تابع را تمام و مقدار را برمی‌گرداند؛ yield تابع را معلق می‌کند و دفعه بعد از همان‌جا ادامه می‌دهد","سرعت","نوع مقدار"],"ans":1,"why":"این تعلیق و ادامه کلید ژنراتور است؛ چون حالت تابع بین فراخوانی‌ها حفظ می‌شود، می‌تواند دنباله‌ای تولید کند بدون اینکه همه‌اش را یک‌جا بسازد — همان صرفه‌جویی حافظه."},{"q":"چرا ژنراتور «یک‌بار مصرف» است؟","opts":["باگ است","چون وقتی پیمایش تمام شد به انتها رسیده و دیگر yield ندارد؛ پیمایش دوباره خالی برمی‌گرداند","کند است","حافظه ندارد"],"ans":1,"why":"ژنراتور حالتِ پیشرفت را نگه می‌دارد و به عقب برنمی‌گردد؛ پس بعد از مصرف، تمام شده. اگر چندبار پیمایش لازم داری، یا لیست بساز یا ژنراتور تازه بساز."}]'::jsonb),
('py-b11', 'py', 'Type Hints و کد خودمستند', 63, 22, '[{"k":"p","t":"Type hint به ابزارها و انسان‌ها می‌گوید هر متغیر چه نوعی است. اجرا را تغییر نمی‌دهد ولی با mypy خطاهای نوع را قبل از اجرا پیدا می‌کنی."},{"k":"h","t":"type hint اجرا را تغییر نمی‌دهد"},{"k":"p","t":"پایتون hintها را در اجرا کاملاً نادیده می‌گیرد — def f(x: int) هیچ اجباری نمی‌سازد و اگر رشته بدهی هم اجرا می‌شود. ارزش hint برای «ابزارها» است: ویرایشگر با آن تکمیل دقیق می‌دهد، mypy قبل از اجرا خطای نوع را پیدا می‌کند، و خواننده بدون خواندن بدنه می‌فهمد قرارداد چیست. پس hint یک مستندِ ماشین‌خوان و قابل‌بررسی است، نه یک guard زمان اجرا."},{"k":"h","t":"Optional و جایی که None ممکن است"},{"k":"p","t":"وقتی تابعی ممکن است هیچ برگرداند، امضایش باید بگوید: Optional[int] یعنی int یا None. این مهم‌تر از چیزی است که به‌نظر می‌رسد، چون mypy را وادار می‌کند هر جایی که از نتیجه استفاده می‌کنی چک کنی None نیست — و همین، کلاس بزرگی از باگ‌های AttributeError: ''NoneType'' را قبل از اجرا حذف می‌کند. قاعده: اگر None برمی‌گردانی، حتماً در امضا اعلامش کن."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"امضاهای گویا","code":"from typing import Optional\n\ndef find_user(uid: int) -> Optional[dict]:\n    ...\n\nuser = find_user(42)\nif user is not None:        # mypy بعد از این می‌داند user یک dict است\n    print(user[''name''])\n# print(user[''name''])  ← بدون چک، mypy خطا می‌دهد\n\n# mypy file.py → خطا را قبل از اجرا گزارش می‌کند"},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["def f(x: int) -> str امضای کامل است","list[str] و Optional[int] از ماژول typing","mypy با mypy file.py بررسی نوع ایستا می‌کند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"types.py","code":"from typing import Optional\ndef greet(name: str, times: int = 1) -> str:\n    return (f''salam {name}! '' * times).strip()\n\ndef find(d: dict[str, int], k: str) -> Optional[int]:\n    return d.get(k)\nprint(greet(''ali'', 2))"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: def f(x: int) -> str امضای کامل است بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"type hint چه چیزی را تغییر می‌دهد؟","opts":["رفتار زمان اجرا","هیچ‌کدام — فقط برای بررسی ایستا و خوانایی است","سرعت را","حافظه را"],"ans":1,"why":"پایتون hintها را اجرا نمی‌کند؛ ابزارهایی مثل mypy از آن برای یافتن خطا استفاده می‌کنند."},{"q":"اگر به تابعی که امضایش (x: int) است رشته بدهی، چه می‌شود؟","opts":["خطای زمان اجرا","هیچ — پایتون hint را اجرا نمی‌کند؛ فقط mypy می‌تواند قبل از اجرا هشدار بدهد","کامپایل نمی‌شود","تبدیل خودکار"],"ans":1,"why":"hint یک قرارداد برای ابزارهاست نه یک بررسی زمان اجرا؛ اجرای پایتون هیچ‌چیزش عوض نمی‌شود. قدرتش وقتی است که mypy را در CI بزنی تا این قراردادها شکسته نشوند."},{"q":"چرا اعلام Optional[int] برای خروجی مهم است؟","opts":["زیباتر است","چون ابزار را مجبور می‌کند همه مصرف‌کننده‌ها چک کنند None نیست؛ پس باگ‌های NoneType قبل از اجرا کشف می‌شوند","سرعت می‌دهد","برای JSON لازم است"],"ans":1,"why":"بدون Optional، mypy فرض می‌کند خروجی همیشه int است و استفاده‌های ناامن را خطا نمی‌گیرد؛ با آن، هر مصرف باید None را handle کند — و این دقیقاً همان باگ‌هایی است که در اجرا ظاهر می‌شدند."}]'::jsonb),
('py-b12', 'py', 'محیط مجازی و ساختار پروژه', 63, 23, '[{"k":"p","t":"venv وابستگی‌های هر پروژه را جدا نگه می‌دارد تا نسخه‌ها با هم نجنگند. ساختار استاندارد پروژه، کد را قابل‌انتشار و قابل‌تست می‌کند."},{"k":"h","t":"چرا محیط مجازی، نه پایتون سراسری"},{"k":"p","t":"اگر همه پروژه‌ها از پایتون سراسری استفاده کنند، نسخه کتابخانه‌ها با هم می‌جنگند: پروژه الف requests نسخه ۲ می‌خواهد و پروژه ب نسخه ۱ — یکی نصب شود، دیگری می‌شکند. venv برای هر پروژه یک پایتون و یک site-packages جدا می‌سازد، پس هر پروژه دقیقاً نسخه‌های خودش را دارد. این ایزولاسیون پیش‌شرطِ قابل‌اعتمادبودن است، نه یک تشریفات."},{"k":"h","t":"requirements و بازتولیدپذیری"},{"k":"p","t":"pip freeze > requirements.txt دقیقاً همان نسخه‌های نصب‌شده را با = ثبت می‌کند تا هم‌تیمی و سرور تولید همان را نصب کنند و «روی ماشین من کار می‌کرد» از بین برود. برای پروژه‌های جدی‌تر، pyproject.toml استاندارد مدرن است که متادیتا، وابستگی‌ها و تنظیم ابزارها را یک‌جا نگه می‌دارد و جایگزین setup.py قدیمی شده."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"جریان کاری استاندارد پروژه","code":"# ۱. ساخت و فعال‌سازی محیط مجازی\npython -m venv .venv\nsource .venv/bin/activate        # لینوکس/مک\n# .venv\\Scripts\\activate         # ویندوز\n\n# ۲. نصب وابستگی‌ها و ثبت دقیق آن‌ها\npip install requests pytest\npip freeze > requirements.txt\n\n# ۳. هم‌تیمی یا سرور، دقیقاً همان را می‌سازد:\npython -m venv .venv && source .venv/bin/activate\npip install -r requirements.txt"},{"k":"tip","title":"نکته منتور","t":".venv را هرگز به git اضافه نکن — چند صد مگابایت است و وابسته به سیستم‌عامل؛ فقط requirements.txt (یا pyproject.toml) را کامیت کن و .venv/ را در .gitignore بگذار. محیط مجازی بازساختنی است، پس نیازی به نسخه‌کنترلش نیست."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["python -m venv .venv محیط مجازی می‌سازد","pip freeze > requirements.txt وابستگی‌ها را ثبت می‌کند","کد در src یا یک بسته، تست‌ها در tests/"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"terminal","code":"python -m venv .venv\nsource .venv/bin/activate    # لینوکس/مک\npip install requests\npip freeze > requirements.txt\npython -m pytest"},{"k":"tip","title":"نکته منتور","t":"هرگز requirements.txt را بدون pin نسخه ننویس؛ pip freeze خروجی دقیق می‌دهد و بازتولیدپذیری می‌سازد."},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: python -m venv .venv محیط مجازی می‌سازد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا venv لازم است؟","opts":["پایتون را سریع می‌کند","وابستگی‌های پروژه‌ها را جدا می‌کند تا نسخه‌ها تداخل نکنند","کد را فشرده می‌کند","اجباری است"],"ans":1,"why":"بدون venv نصب یک نسخه جدید برای یک پروژه، پروژه دیگر را می‌شکند؛ venv هر پروژه را ایزوله می‌کند."},{"q":"اگر .venv را در requirements.txt ثبت نکنی و فقط محیط را نگه داری، چه مشکلی پیش می‌آید؟","opts":["هیچ","هم‌تیمی و سرور نمی‌توانند دقیقاً همان نسخه‌ها را بازسازی کنند و برنامه ممکن است روی ماشین آن‌ها متفاوت رفتار کند یا بشکند","کند می‌شود","حافظه می‌گیرد"],"ans":1,"why":"محیط مجازی محلی است و منتقل نمی‌شود؛ تنها چیزی که قابل‌انتقال است لیست وابستگی‌هاست. بدون آن، «کار می‌کرد» وابسته به ماشین توست — و بازتولیدپذیری از بین می‌رود."},{"q":"چرا در پروژه جدی، نسخه‌ها را در requirements pin می‌کنیم (requests==2.31.0)؟","opts":["برای خوانایی","چون بدون pin، نصب بعدی ممکن است نسخه جدیدتر و ناسازگاری بیاورد که برنامه را ناگهان می‌شکند — pin بازتولیدِ قطعی می‌سازد","اجباری است","سریع‌تر نصب می‌شود"],"ans":1,"why":"کتابخانه‌ها گاهی در نسخه جدید رفتارشان را عوض می‌کنند (breaking change)؛ اگر نسخه باز باشد، یک نصب تازه می‌تواند برنامه سالم را خراب کند. pin یعنی همه همیشه همان نسخه‌ی تست‌شده را می‌گیرند."}]'::jsonb),
('dsa-r1', 'dsa', 'آرایه، لیست پیوندی و هنر انتخاب', 55, 1, '[{"k":"p","t":"ساختمان داده یعنی یک معامله: هیچ ساختاری در همه عملیات بهترین نیست، هرکدام در یک عملیات عالی و در عملیات دیگر ضعیف است. مهارت مهندس، شناختن دقیق این معامله و انتخاب بر اساس «کدام عملیات در برنامه من بیشتر تکرار می‌شود» است."},{"k":"h","t":"آرایه: سرعت با قیمت انعطاف"},{"k":"p","t":"آرایه عناصر را پشت‌سرهم در حافظه نگه می‌دارد؛ همین پیوستگی دو موهبت دارد: دسترسی به هر ایندکس در O(1) چون آدرس با یک ضرب ساده حساب می‌شود، و «محبوبیت نزد کش پردازنده» که پیمایش را عملاً چند برابر سریع‌تر از ساختارهای پراکنده می‌کند. قیمتش این است که درج و حذف وسط، نیاز به جابه‌جایی همه عناصر بعدی دارد و در بدترین حالت O(n) می‌شود؛ پس آرایه برای داده‌ای که زیاد خوانده و کم تغییر اندازه می‌دهد عالی است."},{"k":"h","t":"لیست پیوندی: انعطاف با قیمت دسترسی"},{"k":"p","t":"لیست پیوندی عناصر را در گره‌های پراکنده نگه می‌دارد که هرکدام به بعدی اشاره می‌کند. نتیجه معکوس آرایه است: درج و حذف در هر نقطه‌ای که «اشاره‌گرش را داری» O(1) است چون هیچ عنصری جابه‌جا نمی‌شود؛ اما رسیدن به عنصر kاُم نیاز به پیمایش از اول دارد و O(k) است. ضمناً هر گره هزینه اضافیِ نگهداری اشاره‌گر دارد و پراکندگی در حافظه، کش را ناخشنود می‌کند؛ پس لیست پیوندی برای صف‌ها و ساختارهایی که مدام در دو سر تغییر می‌کنند مناسب است."},{"k":"h","t":"انتخاب واقعی"},{"k":"p","t":"در عمل پایتون list پیاده‌سازی آرایه پویا و deque لیست پیوندی دوطرفه است. قاعده: اگر زیاد ایندکس می‌زنی یا slice می‌گیری، list؛ اگر مدام از دو سر اضافه/حذف می‌کنی (صف، پشته بزرگ، بافر)، deque. اشتباه رایج استفاده از list به‌عنوان صف با pop(0) است که هر بار همه عناصر را جابه‌جا می‌کند و یک برنامه ظاهراً درست را در داده بزرگ به زانو درمی‌آورد."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"structures.py","code":"from collections import deque\nimport time\n\nl = list(range(1_000_000))\nq = deque(range(1_000_000))\n\nt0 = time.perf_counter()\nfor _ in range(10_000):\n    l.pop(0)          # هر بار جابه‌جایی ~یک میلیون عنصر!\nprint(''list.pop(0):'', time.perf_counter() - t0)\n\nt0 = time.perf_counter()\nfor _ in range(10_000):\n    q.popleft()       # همیشه O(1)\nprint(''deque.popleft():'', time.perf_counter() - t0)\n# تفاوت معمولاً چند صد برابر است"},{"k":"list","items":["pop(0) روی list همه عناصر بعدی را یک خانه جلو می‌کشد؛ با یک میلیون عنصر، ده‌هزار بار این کار یعنی فاجعه.","deque یک لیست پیوندیِ بلوکی است؛ popleft فقط سر را جدا می‌کند و هزینه‌اش ثابت است.","این آزمایش ساده بهترین راه «باور کردن» Big-O است؛ چون تفاوت را با کرونومتر می‌بینی نه با فرمول."]},{"k":"def","term":"مبادله فضا-زمان (Space-Time Tradeoff)","t":"اصلی‌ترین قانون ساختمان داده: برای سرعت بیشتر معمولاً حافظه بیشتری می‌دهی و برعکس. لیست پیوندی حافظه بیشتری مصرف می‌کند تا درج O(1) بگیرد؛ هش‌تیبل فضای خالی نگه می‌دارد تا جست‌وجو O(1) بماند. هیچ ساختاری «رایگان» بهتر نمی‌شود."},{"k":"table","head":["عملیات","آرایه (list)","لیست پیوندی (deque)"],"rows":[["دسترسی با ایندکس","O(1)","O(n)"],["افزودن به انتها","O(1)*","O(1)"],["افزودن/حذف از ابتدا","O(n)","O(1)"],["حذف از وسط","O(n)","O(n) بدون اشاره‌گر"],["کش‌دوستی حافظه","عالی","ضعیف‌تر"]]},{"k":"warn","title":"دام رایج","t":"استفاده از list به‌عنوان صف با pop(0) یا insert(0). روی داده کوچک درست کار می‌کند و تست‌ها را پاس می‌کند، ولی در تولید با داده بزرگ ناگهان کند می‌شود — چون O(n) است. از روز اول deque انتخاب کن."},{"k":"tip","title":"نکته حرفه‌ای","t":"ستاره O(1)* یعنی «سرشکن» (amortized): آرایه پویا گاهی برای بزرگ‌شدن همه را کپی می‌کند، ولی چون ظرفیت را دو برابر می‌کند، هزینه کپی‌ها روی عملیات‌ها پخش و میانگین O(1) می‌ماند."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["آرایه: دسترسی O(1) و کش‌دوست، درج وسط O(n)","لیست پیوندی: درج/حذف دو سر O(1)، دسترسی O(n)","صف و پشته بزرگ را با deque بساز، نه list","انتخاب بر اساس پرکاربردترین عملیات برنامه توست"]}]'::jsonb, '[{"q":"چرا دسترسی با ایندکس در آرایه O(1) است؟","opts":["چون کوچک است","چون عناصر پیوسته‌اند و آدرس با یک ضرب و جمع حساب می‌شود","چون کش دارد","چون مرتب است"],"ans":1,"why":"آدرس عنصر k برابر است با آدرس شروع + k×اندازه عنصر؛ یک محاسبه ثابت بدون پیمایش."},{"q":"pop(0) روی list چرا کند است؟","opts":["چون list قدیمی است","چون همه عناصر بعدی باید یک خانه جابه‌جا شوند","چون قفل می‌گذارد","کند نیست"],"ans":1,"why":"حذف از ابتدا یعنی جابه‌جایی n-1 عنصر؛ هر عملیات O(n) و تکرارش O(n²) می‌شود."},{"q":"کجا لیست پیوندی بر آرایه برتری واقعی دارد؟","opts":["دسترسی تصادفی","درج و حذف مکرر از دو سر","پیمایش با کش","ذخیره عدد"],"ans":1,"why":"در دو سر، درج/حذف بدون جابه‌جایی عناصر O(1) است؛ همان جایی که آرایه O(n) دارد."}]'::jsonb),
('dsa-r2', 'dsa', 'پشته و صف؛ نظمِ ورود و خروج', 45, 2, '[{"k":"p","t":"بیشتر باگ‌های «ترتیب» در برنامه‌ها ریشه در یک سوال ساده دارند: چه کسی باید اول خارج شود؟ پشته و صف دو جواب بنیادین به این سوال‌اند و جالب اینجاست که نیمی از ساختارهای پیچیده‌تر — از فراخوانی توابع تا BFS — روی همین دو اصل ساده سوارند."},{"k":"h","t":"پشته: آخرین وارد، اولین خارج"},{"k":"p","t":"پشته مثل یک ستون بشقاب است؛ فقط از بالا برمی‌داری و فقط بالا می‌گذاری. این محدودیت ظاهراً ساده، دقیقاً همان چیزی است که «تاریخچه» را ممکن می‌کند: آخرین کاری که کردی اولین چیزی است که برمی‌گردی. دکمه Undo، فراخوانی توابع (هر فراخوانی روی پشته می‌رود و با برگشت برمی‌دارد)، ارزیابی عبارت‌ها و پیمایش بازگشتی عمق‌اول همه از همین نظم LIFO استفاده می‌کنند. در پایتون append و pop روی لیست، یک پشته کارآمد است."},{"k":"h","t":"صف: اولین وارد، اولین خارج"},{"k":"p","t":"صف یعنی نوبت واقعی؛ هرکه زودتر آمد زودتر خدمت می‌گیرد. این نظم برای هر جایی که «ترتیب ورود مهم است» ضروری است: صف چاپ، صف پیام‌ها، پردازش درخواست‌ها به ترتیب رسیدن، و پیمایش سطح‌به‌سطح گراف (BFS) که لایه‌ها را به ترتیب نزدیکی طی می‌کند. چون عملیات در دو سر انجام می‌شود، پیاده‌سازی درست با deque است؛ عملیات‌های O(1) در هر دو انتها."},{"k":"h","t":"دو نوعر که همه‌جا هست"},{"k":"p","t":"هر وقت در کدت خواستی چیزی را «به تعویق بیندازی تا بعد برگردی»، به پشته فکر کن؛ و هر وقت خواستی «به ترتیب رسیدگی کنی»، به صف. تشخیص اینکه مسئله‌ات کدام است، اغلب یعنی فهمیدن اینکه آیا ترتیب معکوسِ ورود برایت معنا دارد یا نه. خیلی از راه‌حل‌های بازگشتی را می‌توان با یک پشته صریح بازنویسی کرد و برعکس؛ این دو در واقع دو روی یک سکه‌اند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"stack_queue.py","code":"from collections import deque\n\n# پشته: بررسی پرانتزهای متوازن\nbalanced = lambda s: (st := []) is not None and all(\n    st.append(c) if c in ''(['' else (st and st.pop())\n    for c in s if c in ''()[]'') and not st\n\n# نسخه خوانا:\ndef is_balanced(s):\n    st = []\n    pair = {'')'': ''('', '']'': ''[''}\n    for c in s:\n        if c in ''(['': st.append(c)\n        elif c in '')]'':\n            if not st or st.pop() != pair[c]: return False\n    return not st\n\n# صف: پردازش به ترتیب رسیدن\njobs = deque([''a'', ''b'', ''c''])\nwhile jobs:\n    job = jobs.popleft()     # همیشه قدیمی‌ترین\n    jobs_done = job          # پردازش..."},{"k":"list","items":["پرانتز باز روی پشته می‌رود؛ وقتی پرانتز بسته رسید، باید با جدیدترین باز (رأس پشته) جفت شود — دقیقاً LIFO.","شرط not st قبل از pop از «برداشتن از پشته خالی» جلوگیری می‌کند؛ این مرزبندی‌ها قلب کد پشته‌ای‌اند.","popleft روی deque قدیمی‌ترین عنصر را می‌دهد؛ اگر به‌جایش pop() می‌گرفتی، نظم صف به پشته تبدیل می‌شد."]},{"k":"def","term":"LIFO و FIFO","t":"دو نظم بنیادین خروج: LIFO (آخرین ورود، اولین خروج) مربوط به پشته و مناسب «برگشت به تازه‌ترین»، و FIFO (اولین ورود، اولین خروج) مربوط به صف و مناسب «رعایت نوبت». انتخاب بین این دو، اغلب کل طراحی یک سامانه صف یا تاریخچه را تعیین می‌کند."},{"k":"table","head":["کاربرد","ساختار","چرا"],"rows":[["Undo / Back","پشته","آخرین عمل باید اول برگردد"],["فراخوانی توابع","پشته","آخرین فراخوانی اول تمام می‌شود"],["BFS در گراف","صف","لایه‌ها به ترتیب نزدیکی"],["صف پیام/چاپ","صف","رعایت نوبت رسیدن"],["ارزیابی عبارت","پشته","عملگرها به ترتیب اولویت"]]},{"k":"warn","title":"دام رایج","t":"برداشتن از پشته خالی یا صف خالی بدون بررسی. این خطا معمولاً در حالت‌های مرزی ظاهر می‌شود؛ همیشه قبل از pop/popleft مطمئن شو ساختار خالی نیست، یا در پایتون با try یا بررسی طول، حالت خالی را صریح مدیریت کن."},{"k":"tip","title":"نکته حرفه‌ای","t":"وقتی یک الگوریتم بازگشتی خطای RecursionError می‌دهد، همان منطق را با یک پشته صریح بازنویسی کن؛ عمق پشته را خودت کنترل می‌کنی و دیگر محدود به عمق فراخوانی پایتون نیستی."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["پشته LIFO است: Undo، فراخوانی توابع، DFS","صف FIFO است: نوبت‌ها، BFS، پردازش ترتیبی","پشته با append/pop و صف با deque پیاده می‌شود","همیشه حالت خالی‌بودن را قبل از برداشتن بررسی کن"]}]'::jsonb, '[{"q":"برای پیاده‌سازی دکمه Undo کدام ساختار مناسب است؟","opts":["صف","پشته","هش‌تیبل","درخت"],"ans":1,"why":"آخرین عمل انجام‌شده باید اول لغو شود؛ این دقیقاً نظم LIFO پشته است."},{"q":"پیمایش BFS گراف چرا از صف استفاده می‌کند؟","opts":["چون سریع‌تر است","چون باید گره‌ها به ترتیب لایه/نزدیکی بازدید شوند و صف نوبت را حفظ می‌کند","چون حافظه کمتر","تصادفی است"],"ans":1,"why":"BFS اول همه همسایه‌های لایه فعلی را می‌بیند؛ صف تضمین می‌کند ترتیب لایه‌ها به‌هم نریزد."},{"q":"در بررسی پرانتز متوازن، پرانتز بسته باید با چه چیزی جفت شود؟","opts":["اولین پرانتز باز","جدیدترین پرانتز باز روی پشته","هر پرانتز بازی","هیچ‌کدام"],"ans":1,"why":"داخلی‌ترین پرانتز باید اول بسته شود؛ پس جفتش رأس پشته (جدیدترین باز) است."}]'::jsonb),
('dsa-r3', 'dsa', 'هش‌تیبل؛ جست‌وجوی O(1) و قیمتش', 55, 3, '[{"k":"p","t":"جست‌وجوی O(1) در نگاه اول جادوست: چطور پیدا کردن یک عنصر بین یک میلیون، فقط یک قدم طول می‌کشد؟ پاسخ هش‌تیبل است — ساختاری که به‌جای «گشتن»، مستقیم به «آدرس» می‌رود. اما این سرعت رایگان نیست و فهمیدن قیمتش، تفاوت استفاده درست و اشتباه است."},{"k":"h","t":"ایده اصلی: از مقدار به آدرس"},{"k":"p","t":"در آرایه برای یافتن یک مقدار باید عناصر را یکی‌یکی مقایسه کنی. هش‌تیبل مسیر را برعکس می‌کند: یک تابع هش، کلید را به یک عدد (آدرس سطل) تبدیل می‌کند و مقدار همان‌جا ذخیره می‌شود. موقع جست‌وجو، همان تابع دوباره آدرس را حساب می‌کند و مستقیم سراغش می‌روی؛ بدون مقایسه با بقیه. شرط حیاتی این است که کلیدهای برابر همیشه هش برابر بدهند؛ اگر این نقض شود، داده‌ات را گذاشته‌ای ولی هرگز پیدایش نمی‌کنی."},{"k":"h","t":"برخورد و زنجیره"},{"k":"p","t":"دو کلید مختلف می‌توانند به یک سطل برسند؛ به این می‌گویند «برخورد». راه‌حل کلاسیک، زنجیره است: هر سطل به‌جای یک عنصر، یک لیست کوچک نگه می‌دارد و عناصر هم‌سطل در آن لیست خطی جست‌وجو می‌شوند. اگر تابع هش خوب پخش کند و جدول به‌اندازه کافی بزرگ باشد، این لیست‌ها ۱-۲ عضوی می‌مانند و جست‌وجو عملاً O(1) است؛ ولی اگر همه کلیدها به یک سطل بریزند، همان لیست خطی O(n) می‌شود — پس کیفیت تابع هش و ضریب بار، همه‌چیزند."},{"k":"h","t":"ضریب بار و بزرگ‌شدن"},{"k":"p","t":"ضریب بار یعنی نسبت تعداد عناصر به تعداد سطل‌ها. وقتی از آستانه‌ای (معمولاً ۰٫۷۵) رد شود، جدول ظرفیتش را چند برابر می‌کند و همه عناصر با هش‌های جدید دوباره پخش می‌شوند؛ این «بازپخش» گران است ولی چون به‌ندرت رخ می‌دهد، هزینه‌اش سرشکن و O(1) باقی می‌ماند. این همان دلیل است که ساختن دیکشنری با ظرفیت اولیه مناسب، در داده بزرگ سرعت را محسوس بهتر می‌کند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"hash_use.py","code":"from collections import Counter\n\nwords = [''سیب'', ''گلابی'', ''سیب'', ''انار'', ''سیب'']\n\n# شمارش با دیکشنری (هش‌تیبل) — هر کلید یک‌بار\nfreq = {}\nfor w in words:\n    freq[w] = freq.get(w, 0) + 1\nprint(freq)   # {''سیب'': 3, ''گلابی'': 1, ''انار'': 1}\n\n# یا با Counter که همین کار را تمیزتر می‌کند\nprint(Counter(words).most_common(1))\n\n# جست‌وجوی عضویت: O(1) در برابر O(n) لیست\nprint(''سیب'' in freq)        # هش → یک سطل\nprint(''سیب'' in words)       # پیمایش کل لیست"},{"k":"list","items":["freq.get(w, 0) یعنی «مقدار قبلی یا صفر»؛ این یک خط، الگوی کلاسیک «بساز یا به‌روز کن» در هش‌تیبل است.","هر w فقط یک کلید است؛ مهم نیست چند بار تکرار شود، هشِ ''سیب'' همیشه به همان سطل می‌رود و شمارنده همان‌جاست.","عملگر in روی دیکشنری هش کلید را حساب می‌کند و مستقیم می‌رود؛ روی لیست باید همه را بگردد. در یک میلیون عنصر، تفاوت یعنی «فوری» در برابر «چند ثانیه»."]},{"k":"def","term":"تابع هش","t":"تابعی که داده‌ای با اندازه دلخواه را به یک عدد ثابت تبدیل می‌کند؛ طوری که داده‌های برابر همیشه عدد برابر و داده‌های مختلف تا حد امکان عدد متفاوت بگیرند. هش یک‌طرفه است (از عدد نمی‌توان داده را برگرداند) و پایه هش‌تیبل، checksum و ذخیره رمز عبور است."},{"k":"table","head":["عملیات","هش‌تیبل (dict)","لیست"],"rows":[["جست‌وجوی عضویت","O(1) میانگین","O(n)"],["درج/به‌روزرسانی","O(1) میانگین","O(n) برای درج وسط"],["پیمایش همه","O(n)","O(n)"],["ترتیب/ایندکس","ندارد (ترتیب درج)","دارد"],["کلید","باید هش‌پذیر و تغییرناپذیر","—"]]},{"k":"warn","title":"دام رایج","t":"استفاده از لیست یا دیکشنری به‌عنوان کلید دیکشنری دیگر. کلید باید تغییرناپذیر باشد چون اگر بعد از ذخیره تغییر کند، هزش عوض می‌شود و دیگر در سطل درستش نیست؛ پایتون برای همین اجازه نمی‌دهد لیست کلید شود و باید از tuple استفاده کنی."},{"k":"tip","title":"نکته حرفه‌ای","t":"وقتی می‌خواهی بدانی «کدام عناصر مشترک‌اند» یا «چند بار تکرار شده»، قبل از نوشتن حلقه تودرتو به set و Counter فکر کن؛ حلقه تودرتوی روی دو لیست O(n²) است، ولی با set به O(n) می‌رسد."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["هش‌تیبل با تبدیل کلید به آدرس، جست‌وجو را O(1) می‌کند","برخورد با زنجیره حل می‌شود؛ تابع هش خوب = لیست کوتاه","ضریب بار که بالا برود جدول بزرگ و بازپخش می‌شود","کلید باید تغییرناپذیر باشد؛ برای عضویت از set استفاده کن"]}]'::jsonb, '[{"q":"چرا جست‌وجو در هش‌تیبل O(1) است؟","opts":["چون مرتب است","چون تابع هش مستقیماً آدرس سطل را حساب می‌کند و نیازی به مقایسه با بقیه نیست","چون کوچک است","چون کش دارد"],"ans":1,"why":"هش کلید را به آدرس تبدیل می‌کند؛ پس بدون پیمایش، مستقیم به جای درست می‌روی."},{"q":"اگر همه کلیدها به یک سطل برسند چه می‌شود؟","opts":["خطا","جست‌وجو به O(n) تنزل می‌کند چون سطل یک لیست خطی می‌شود","جدول پاک می‌شود","هیچ"],"ans":1,"why":"همه عناصر در یک زنجیره قرار می‌گیرند و پیدا کردن هرکدام نیاز به پیمایش کل زنجیره دارد."},{"q":"چرا کلید دیکشنری باید تغییرناپذیر باشد؟","opts":["سلیقه‌ای است","چون تغییر کلید بعد از ذخیره، هزش را عوض و از سطل درستش گم می‌کند","برای سرعت","برای حافظه"],"ans":1,"why":"آدرس ذخیره با هش زمانِ درج تعیین شده؛ اگر کلید تغییر کند، هش جدید به سطل دیگری اشاره می‌کند و داده گم می‌شود."}]'::jsonb),
('c3-l1', 'dsa', 'Big-O؛ زبان مشترک کارایی', 50, 4, '[{"k":"p","t":"وقتی می‌گوییم یک تابع «سریع» است، دقیق حرف نزده‌ایم؛ سرعت به سخت‌افزار وابسته است. Big-O رشد تعداد عملیات را نسبت به اندازه ورودی اندازه می‌گیرد و مستقل از ماشین، کارایی الگوریتم را توصیف می‌کند. این همان زبانی است که در مصاحبه‌های فنی و Code Reviewها استفاده می‌شود."},{"k":"code","lang":"py","title":"complexity.py","code":"# O(1) — دسترسی مستقیم\ndef first(items):\n    return items[0]\n\n# O(n) — پیمایش کامل\ndef find(items, target):\n    for x in items:\n        if x == target:\n            return True\n    return False\n\n# O(n^2) — حلقه تو در تو\ndef has_duplicate(items):\n    for i in range(len(items)):\n        for j in range(i + 1, len(items)):\n            if items[i] == items[j]:\n                return True\n    return False"},{"k":"visual","visual":"bigo","title":"شبیه‌ساز: منحنی‌های پیچیدگی"},{"k":"table","head":["پیچیدگی","نام","مثال"],"rows":[["O(1)","ثابت","دسترسی به آرایه با اندیس"],["O(log n)","لگاریتمی","جست‌وجوی دودویی"],["O(n)","خطی","پیمایش لیست"],["O(n log n)","شبه‌خطی","مرج‌سورت"],["O(n²)","درجه دو","حلقه تو در تو"]]},{"k":"def","term":"Trade-off","t":"در مهندسی هیچ‌چیز رایگان نیست: Hash Table جست‌وجو را O(1) می‌کند اما حافظه بیشتری مصرف می‌کند. هنر مهندس، انتخاب آگاهانه این مصالحه‌هاست."},{"k":"tip","title":"نکته منتور","t":"در تحلیل Big-O فقط بزرگ‌ترین جمله مهم است و ضرایب حذف می‌شوند: 3n² + 100n + 7 می‌شود O(n²). وقتی n بزرگ شود، جمله غالب همه‌چیز را تعیین می‌کند."},{"k":"h","t":"عمیق‌تر: چرا ثابت‌ها مهم نیستند و مرتبه‌ها مهم‌اند"},{"k":"p","t":"Big-O عمداً ثابت‌ها و ضرایب را دور می‌ریزد چون در مقیاس، بی‌اثر می‌شوند: الگوریتمی با 10n همیشه از الگوریتم 2n² جلو می‌زند — به‌محض اینکه n از ۵ رد شود. درس مهم‌تر این است که Big-O درباره «شکل رشد» است نه سرعت لحظه‌ای؛ یک عملیات O(1) می‌تواند در عمل کندتر از O(n) برای nهای کوچک باشد، اما وقتی ورودی ده برابر شود، رفتارها قابل پیش‌بینی‌اند. مهندسی یعنی همین: انتخاب ساختاری که با رشد داده نشکند، نه ساختاری که امروز سریع‌تر به‌نظر می‌رسد."},{"k":"p","t":"پیچیدگی مکانی هم فراموش نشود — گاهی وقت را با حافظه می‌خریم (جدول هش: O(n) حافظه برای O(1) جست‌وجو) و گاهی برعکس. در دستگاه‌های محدود مثل موبایل یا Embedded، حافظه می‌تواند گلوگاه اصلی باشد. یک قاعده عملی دیگر: وقتی دو مرتبه نزدیک‌اند (مثلاً O(n log n) در برابر O(n√n))، پیاده‌سازی، کش و سخت‌افزار تعیین‌کننده است و فقط اندازه‌گیری واقعی (Profiling) جواب می‌دهد. تحلیل مرتبه، نقشه راه است نه حکم نهایی."},{"k":"code","lang":"py","title":"deepdive-measure.py","code":"import time\n\ndef time_it(fn, data):\n    t0 = time.perf_counter()\n    fn(data)\n    return (time.perf_counter() - t0) * 1000  # میلی‌ثانیه\n\ndef linear(lst, x):      # O(n)\n    return any(v == x for v in lst)\n\ndef with_set(lst, x):    # O(n) ساخت + O(1) جست‌وجو\n    return x in set(lst)\n\ndata = list(range(2_000_000))\ntarget = 1_999_999\n\nprint(f''جست‌وجوی خطی: {time_it(linear, (data, target)):.1f} ms'')\nprint(f''عضویت در set: {time_it(with_set, (data, target)):.1f} ms'')\n# تفاوت ۱۰ تا ۵۰ برابری — همین است قدرت انتخاب ساختار داده!"},{"k":"table","head":["مرتبه","نام","n=۱۰۰۰","نمونه واقعی"],"rows":[["O(1)","ثابت","۱","خواندن از دیکشنری/آرایه با ایندکس"],["O(log n)","لگاریتمی","۱۰","جست‌وجوی دودویی، درخت متوازن"],["O(n)","خطی","۱۰۰۰","پیمایش لیست"],["O(n log n)","شبه‌خطی","۱۰٬۰۰۰","مرتب‌سازی کارآمد (مرج/هیپ)"],["O(n²)","مربعی","۱٬۰۰۰٬۰۰۰","حلقه تو در توی کامل"],["O(2ⁿ)","نمایی","غیرقابل‌تصور","زیرمجموعه‌های یک مجموعه"]]},{"k":"warn","title":"تله اندازه‌گیری","t":"اندازه‌گیری یک‌بار اجرا بی‌معنی است: کش CPU، گرم‌بودن مفسر و سرویس‌های پس‌زمینه نتیجه را تا ده برابر جابه‌جا می‌کنند. همیشه چند بار اجرا کن، بهترین یا میانه را گزارش کن و ورودی‌های چند اندازه (۱۰۰، ۱۰۰۰، ۱۰۰۰۰) را مقایسه کن تا «شکل رشد» را ببینی نه یک عدد شانسی را."}]'::jsonb, '[{"q":"پیچیدگی جست‌وجوی یک نام در دفترچه تلفن مرتب‌شده (با بازکردن وسط) چیست؟","opts":["O(n)","O(log n)","O(1)","O(n²)"],"ans":1,"why":"هر بار نیمی از گزینه‌ها حذف می‌شوند؛ برای یک میلیون نام حدود ۲۰ مقایسه کافی است — این یعنی لگاریتم."},{"q":"چرا ضرایب در Big-O حذف می‌شوند؟","opts":["چون بی‌اهمیت‌اند","چون فقط رشد مجانبی مهم است","برای سادگی نوشتن","چون زبان‌ها خودشان بهینه می‌کنند"],"ans":1,"why":"Big-O رفتار را برای nهای بزرگ توصیف می‌کند؛ در مقیاس بزرگ، ضریب ثابت در برابر نرخ رشد ناچیز است."}]'::jsonb),
('c3-l2', 'dsa', 'آرایه در برابر لیست پیوندی', 60, 5, '[{"k":"p","t":"آرایه‌ها داده را پشت‌سرهم در حافظه نگه می‌دارند؛ همین پیوستگی، دسترسی با اندیس را O(1) می‌کند اما درج در وسط را گران. لیست پیوندی برعکس: هر گره جداست و با اشاره‌گر به بعدی وصل می‌شود؛ درج و حذف سریع، اما دسترسی فقط با پیمایش."},{"k":"code","lang":"py","title":"linked_list.py","code":"class Node:\n    def __init__(self, value):\n        self.value = value\n        self.next = None\n\nclass LinkedList:\n    def __init__(self):\n        self.head = None\n\n    def push_front(self, value):      # O(1)\n        node = Node(value)\n        node.next = self.head\n        self.head = node\n\n    def contains(self, value):        # O(n)\n        current = self.head\n        while current:\n            if current.value == value:\n                return True\n            current = current.next\n        return False"},{"k":"visual","visual":"arrayInsert","title":"شبیه‌ساز: درج در آرایه"},{"k":"table","head":["عملیات","آرایه","لیست پیوندی"],"rows":[["دسترسی با اندیس","O(1)","O(n)"],["درج در ابتدا","O(n)","O(1)"],["حذف در ابتدا","O(n)","O(1)"],["کش‌پذیری حافظه (Cache)","عالی","ضعیف"]]},{"k":"visual","visual":"linkedList","title":"شبیه‌ساز: لیست پیوندی"},{"k":"warn","title":"واقعیت مهندسی","t":"در عمل آرایه‌ها تقریباً همیشه برنده‌اند! چون سخت‌افزار حافظه پشت‌سرهم را سریع‌تر می‌خواند (Cache Locality). لیست پیوندی را زمانی انتخاب کن که درج و حذف در ابتدا زیاد است و پیمایش تصادفی نداری."},{"k":"h","t":"عمیق‌تر: چرا کشِ پردازنده، نتیجه را عوض می‌کند"},{"k":"p","t":"تا اینجا آرایه و لیست پیوندی را از نظر «تعداد عمل» مقایسه کردیم؛ ولی در سخت‌افزار واقعی، یک عامل پنهان اغلب تعیین‌کننده‌تر از خودِ Big-O است: کشِ پردازنده. پردازنده داده را بلوک‌بلوک (خط کش) از حافظه می‌خواند و در کش نگه می‌دارد. آرایه چون پیوسته است، وقتی به خانه i می‌رسی، خانه‌های i+1 تا i+15 هم خودشان در کش حاضرند — دسترسی بعدی تقریباً رایگان است. لیست پیوندی هر گره را از جای تصادفی حافظه می‌آورد و تقریباً هر قدم یک «کش‌میس» است که ده‌ها برابر کندتر از خواندن از کش تمام می‌شود. نتیجه عملی: روی داده‌های کوچک و متوسط، حتی عمل‌های O(n) آرایه مثل درج، اغلب از عمل‌های O(1) لیست پیوندی سریع‌ترند — چون ضریب پنهانِ حافظه، عددِ ظاهری را می‌بلعد."},{"k":"code","lang":"py","title":"اندازه‌گیری واقعی — نه روی کاغذ","code":"import time\n\nn = 200_000\narr = list(range(n))\n\n# جمع بستن روی آرایه (پیمایش پیوسته)\nt0 = time.perf_counter()\ns = sum(arr)\nprint(''array :'', round((time.perf_counter() - t0) * 1000, 2), ''ms'')\n\n# همین حجم در لیست پیوندی (شبیه‌سازی با پیمایش تصادفی)\nimport random\nidx = [random.randrange(n) for _ in range(n)]\nt0 = time.perf_counter()\ns = sum(arr[i] for i in idx)\nprint(''random:'', round((time.perf_counter() - t0) * 1000, 2), ''ms'')\n# هر دو O(n) — ولی دومی چند برابر کندتر است: کش!"},{"k":"p","t":"همین ایده توضیح می‌دهد که چرا «پیمایش ماتریس سطر به سطر» در زبان‌هایی مثل C چند برابر سریع‌تر از «ستون به ستون» است، چرا دیتابیس‌ها داده را بلوکی می‌خوانند، و چرا B-Tree (نه درخت دودویی) ساختار ایندکس دیتابیس‌هاست: گره‌های پهن و پیوسته یعنی خطاهای کمتر هنگام خواندن از دیسک. پس دفعه بعد که می‌خواستی بگویی «این عمل O(1) است پس سریع‌تر است»، یک لحظه مکث کن و بپرس: «و الگوی دسترسی حافظه‌اش چطور است؟» — این سوال، تفاوت کسی است که پیچیدگی را حفظ کرده با کسی که فهمیده است."},{"k":"tip","title":"نکته منتور","t":"در مصاحبه‌های حرفه‌ای، بعد از جواب درستِ Big-O معمولاً می‌پرسند «در عمل چه؟». اگر بگویی «ضریب کش و Locality را هم در نظر می‌گیرم؛ مثلاً برای پیمایش، آرایه معمولاً برنده است»، چند پله از بقیه جلوتر می‌ایستی — چون نشان می‌دهی مدل ذهنی‌ات از تخته‌سیاه به سخت‌افزار رسیده است."}]'::jsonb, '[{"q":"چرا دسترسی با اندیس در آرایه O(1) است؟","opts":["چون آرایه‌ها کوچک‌اند","چون آدرس هر عنصر با یک ضرب محاسبه می‌شود","چون سخت‌افزار آرایه را می‌شناسد","چون پایتون بهینه‌سازی می‌کند"],"ans":1,"why":"آدرس عنصر i برابر است با آدرس شروع + i × اندازه هر عنصر؛ یک محاسبه ساده بدون پیمایش."},{"q":"لیست پیوندی در چه سناریویی از آرایه بهتر است؟","opts":["خواندن تصادفی عناصر","درج و حذف مکرر در ابتدای لیست","مرتب‌سازی","هیچ‌وقت"],"ans":1,"why":"درج در ابتدا فقط جابه‌جایی دو اشاره‌گر است (O(1))؛ در آرایه باید همه عناصر شیفت داده شوند."}]'::jsonb),
('c3-l3', 'dsa', 'پشته، صف و Hash Table', 70, 6, '[{"k":"p","t":"پشته (Stack) مثل دسته بشقاب است: آخرین چیزی که گذاشتی، اول برمی‌داری (LIFO) — اساس فراخوانی توابع و دکمه Undo. صف (Queue) مثل صف نانوایی: اول آمده، اول سرویس می‌گیرد (FIFO) — اساس صف پیام‌ها و BFS. و Hash Table شاهکار مهندسی: تبدیل کلید به اندیس با تابع هش و جست‌وجوی میانگین O(1)."},{"k":"code","lang":"py","title":"stack_queue.py","code":"# Stack با لیست پایتون\nstack = []\nstack.append(\"a\")     # push\nstack.append(\"b\")\ntop = stack.pop()     # ''b'' — LIFO\n\n# Queue صحیح با deque (نه list!)\nfrom collections import deque\nq = deque()\nq.append(\"job1\")        # enqueue\nq.append(\"job2\")\nfirst = q.popleft()     # ''job1'' — FIFO"},{"k":"visual","visual":"stack","title":"شبیه‌ساز: پشته"},{"k":"h","t":"Hash Table چگونه O(1) می‌شود؟"},{"k":"visual","visual":"queue","title":"شبیه‌ساز: صف"},{"k":"p","t":"تابع هش، کلید را به عددی در محدوده اندازه جدول تبدیل می‌کند و مقدار در همان خانه ذخیره می‌شود. اگر دو کلید به یک خانه برسند (برخورد)، با زنجیره‌کردن لیست کوچک در آن خانه مشکل حل می‌شود. با بار عامل مناسب، طول زنجیره‌ها کوتاه و سرعت نزدیک O(1) می‌ماند."},{"k":"code","lang":"py","title":"dict-power.py","code":"# شمارش تکرار کلمات: O(n) با dict\nfrom collections import Counter\n\nwords = [\"go\", \"stop\", \"go\", \"run\", \"go\"]\nfreq = Counter(words)\nprint(freq[\"go\"])        # 3\n\n# آیا در O(n^2) یا O(n)؟\ntext = open(\"book.txt\").read().split()\nfor w in text:\n    if w in freq:        # جست‌وجوی dict: میانگین O(1)\n        freq[w] += 1"},{"k":"tip","title":"نکته منتور","t":"هر وقت در کدت حلقه‌ای دیدی که داخلش عملیات in روی لیست انجام می‌شود، زنگ خطر بزن: این یعنی O(n²). با تبدیل لیست به set یا dict معمولاً به O(n) می‌رسی — یکی از رایج‌ترین بهینه‌سازی‌های دنیای واقعی."},{"k":"h","t":"عمیق‌تر: پشته و صف در قلب برنامه‌های واقعی"},{"k":"p","t":"پشته فقط یک ساختمان داده آموزشی نیست؛ الگوی «واگرد کردن» هر کاری است که مرحله‌به‌مرحله انجام شده. سیستم «Undo» ویرایشگرها دقیقاً همین است: هر عمل یک رکورد می‌سازد و روی پشته می‌رود؛ Ctrl+Z یعنی Pop و اجرای عکسِ عمل. مرورگر هم برای دکمه Back از پشته تاریخچه استفاده می‌کند و برای «بازکردن لینک در تب جدید» از صفِ درخواست‌ها. حتی خودِ اجرای برنامه تو روی یک پشته واقعی (Call Stack) سوار است: هر فراخوانی تابع، یک قاب روی پشته می‌گذارد و با return برمی‌دارد — و StackOverflow یعنی همین پشته پر شده است."},{"k":"code","lang":"py","title":"Undo ساده با پشته","code":"class Editor:\n    def __init__(self):\n        self.text = ''''\n        self.ops = []                # پشته عمل‌ها\n\n    def type(self, s):\n        self.text += s\n        self.ops.append((''del'', len(s)))   # عمل معکوس را ذخیره کن\n\n    def undo(self):\n        if not self.ops:\n            return\n        kind, n = self.ops.pop()     # LIFO: آخر از همه، اول از همه\n        if kind == ''del'':\n            self.text = self.text[:-n]\n\ne = Editor()\ne.type(''سلام '')\ne.type(''دنیا'')\nprint(e.text)     # سلام دنیا\ne.undo()\nprint(e.text)     # سلام"},{"k":"p","t":"و صف، الگوی «نوبت عادلانه» است: صف چاپگر، صف درخواست‌های سرور، صف رویدادها در رابط کاربری (Event Queue)، و صف پردازش ویدیو. هرجا تولیدکننده سریع‌تر از مصرف‌کننده است و نمی‌خواهی درخواستی گم شود، صف در میان است. نکته ظریف: در پایتون، list برای پشته عالی است (append/pop از انتها O(1)) ولی برای صف ضعیف — چون pop(0) همه را شیفت می‌دهد و O(n) است؛ به همین دلیل collections.deque وجود دارد که هر دو انتها را O(1) می‌کند. انتخاب داده‌ساختارِ اشتباه برای صف، یکی از رایج‌ترین گلوگاه‌های پنهان است."}]'::jsonb, '[{"q":"برای شبیه‌سازی فراخوانی توابع (Call Stack) کدام ساختار مناسب است؟","opts":["Queue","Stack","LinkedList","Heap"],"ans":1,"why":"آخرین تابع فراخوانی‌شده باید اولین تابعی باشد که برمی‌گردد — دقیقاً رفتار LIFO پشته."},{"q":"چرا جست‌وجوی dict پایتون میانگین O(1) است؟","opts":["چون dictها کوچک‌اند","چون کلید هش می‌شود و مستقیم به خانه جدول می‌رویم","چون پایتون کش دارد","چون dictها مرتب‌اند"],"ans":1,"why":"هش کلید، اندیس خانه را می‌دهد و بدون پیمایش کل داده، مستقیم به سراغش می‌رویم؛ فقط در برخوردها کمی پیمایش لازم است."}]'::jsonb),
('dsa-x1', 'dsa', 'آرایه در برابر لیست پیوندی — با چشم خودت ببین', 50, 7, '[{"k":"p","t":"انتخاب بین آرایه و لیست پیوندی اولین تصمیم ساختمان داده‌ای هر برنامه است و هنوز هم در مصاحبه‌ها سوال می‌شود — چون درکش یعنی فهم حافظه. هر دو فقط n عنصر نگه می‌دارند؛ تفاوت در «چطور» است: آرایه بلوک پیوسته است، لیست پیوندی زنجیره‌ای از گره‌های پراکنده."},{"k":"visual","visual":"arrayInsert","title":"شبیه‌ساز: درج در آرایه"},{"k":"visual","visual":"linkedList","title":"شبیه‌ساز: درج و حذف در لیست پیوندی"},{"k":"h","t":"مقایسه هزینه‌ها"},{"k":"table","head":["عملیات","آرایه","لیست پیوندی","چرا"],"rows":[["خواندن ایندکس i","O(1)","O(n)","آدرس آرایه با یک ضرب محاسبه می‌شود؛ لیست باید قدم بزند"],["درج/حذف در سر","O(n)","O(1)","آرایه همه را شیفت می‌دهد؛ لیست فقط اشاره‌گر عوض می‌کند"],["درج/حذف در انتها","O(1) استهلاکی","O(1)*","آرایه با ظرفیت دوبرابر؛ لیست با نگه‌داشتن دم"],["پیدا کردن با مقدار","O(n)","O(n)","هر دو باید ببینند"]]},{"k":"p","t":"یک راز مهم: در دنیای واقعی، آرایه تقریباً همیشه برنده است — حتی برای درج! دلیلش Cache Locality است: پردازنده داده‌های پشت‌سرهم را یکجا به حافظه نهان می‌آورد. لیست پیوندی با گره‌های پراکنده، هر بار Cache Miss می‌خورد."},{"k":"tip","title":"نکته منتور","t":"لیست پایتون (list) آرایه پویاست نه لیست پیوندی. اگر واقعاً درج در سر زیاد داری، از collections.deque استفاده کن — پیاده‌سازی بلوکی که هر دو سرش O(1) است."},{"k":"warn","title":"دام مصاحبه","t":"«لیست پیوندی همیشه برای درج بهتر است» غلط است: برای درج در وسط، اول باید با O(n) به محلش برسی! لیست پیوندی فقط وقتی می‌برد که اشاره‌گر به گره را از قبل داری."}]'::jsonb, '[{"q":"چرا خواندن ایندکس ۱۰۰۰ام در آرایه O(1) است؟","opts":["چون سریع است","چون آدرس = آدرس_شروع + ۱۰۰۰ × اندازه_عنصر — یک محاسبه","چون کش شده","چون آرایه مرتب است"],"ans":1,"why":"پیوستگی حافظه یعنی آدرس هر عنصر با یک فرمول ساده حساب می‌شود؛ نیازی به گشتن نیست."},{"q":"چرا در عمل آرایه اغلب از لیست پیوندی سریع‌تر است؟","opts":["حافظه کمتری می‌گیرد","Cache Locality — دسترسی پیوسته به حافظه","همیشه O(1) است","زبان‌ها آن را بهینه نکرده‌اند"],"ans":1,"why":"سخت‌افزار بلوک‌های پیوسته را prefetch می‌کند؛ گره‌های پراکنده لیست پیوندی هر بار پردازنده را معطل می‌کنند."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('dsa-x2', 'dsa', 'درخت جست‌وجوی دودویی و جادوی پیمایش', 55, 8, '[{"k":"p","t":"درخت جست‌وجوی دودویی (BST) یک قرارداد ساده است: همه مقادیر کوچک‌تر در زیردرخت چپ، بزرگ‌تر در راست. همین یک جمله، جست‌وجو را از O(n) به O(log n) می‌رساند — چون در هر مقایسه نصف درخت حذف می‌شود. دقیقاً منطق جست‌وجوی دودویی، ولی با ساختار داده پویا."},{"k":"visual","visual":"bst","title":"شبیه‌ساز: پیمایش درخت"},{"k":"code","lang":"py","title":"bst.py","code":"class Node:\n    def __init__(self, v):\n        self.v, self.l, self.r = v, None, None\n\ndef insert(root, v):\n    if root is None:\n        return Node(v)\n    if v < root.v:\n        root.l = insert(root.l, v)\n    else:\n        root.r = insert(root.r, v)\n    return root\n\ndef inorder(root):          # خروجی: مرتب صعودی\n    if root:\n        yield from inorder(root.l)\n        yield root.v\n        yield from inorder(root.r)\n\nroot = None\nfor v in [50, 30, 70, 20, 40, 60, 80]:\n    root = insert(root, v)\nprint(list(inorder(root)))  # [20, 30, 40, 50, 60, 70, 80]"},{"k":"def","term":"ارتفاع درخت","t":"طولانی‌ترین مسیر از ریشه تا برگ. در BST متوازن ارتفاع log n است؛ در بدترین حالت (ورودی از قبل مرتب!) به n تبدیل می‌شود و عملاً لیست پیوندی می‌شود. درخت‌های خودمتوازن (AVL، Red-Black) این کابوس را حل می‌کنند."},{"k":"table","head":["پیمایش","ترتیب بازدید","کاربرد"],"rows":[["میان‌ترتیب In-order","چپ، ریشه، راست","خروجی مرتب از BST"],["پیش‌ترتیب Pre-order","ریشه، چپ، راست","کپی/سریال‌کردن درخت"],["پس‌ترتیب Post-order","چپ، راست، ریشه","حذف درخت، عبارات ریاضی"],["سطحی BFS","سطح به سطح","کوتاه‌ترین مسیر، عرض درخت"]]},{"k":"warn","title":"کابوس ورودی مرتب","t":"اگر ۱ تا n را به‌ترتیب وارد BST ساده کنی، درخت به یک زنجیره خطی تبدیل می‌شود و همه عملیات O(n). برای همین کتابخانه‌ها از درخت‌های متوازن استفاده می‌کنند — TreeMap جاوا و dictهای مرتب همین‌طورند."},{"k":"tip","title":"نکته منتور","t":"بسیاری از ساختارهای واقعی — ایندکس دیتابیس (B-Tree)، فایل‌سیستم، Redis — نسخه‌های پیشرفته همین درخت‌اند. BST را عمیق بفهم، بقیه فقط جزئیات‌اند."}]'::jsonb, '[{"q":"چرا In-order در BST خروجی مرتب می‌دهد؟","opts":["شانسی است","چون قرارداد «چپ < ریشه < راست» در هر زیردرخت برقرار است و استقرا می‌شود","چون درخت متوازن است","چون بازگشتی است"],"ans":1,"why":"هر زیردرخت خودش یک BST است؛ پس چپ (همه کوچک‌تر، مرتب) + ریشه + راست (همه بزرگ‌تر، مرتب) = کل مرتب."},{"q":"بدترین حالت جست‌وجو در BST ساده کی رخ می‌دهد؟","opts":["وقتی درخت خالی است","وقتی درخت به زنجیره خطی تبدیل شده باشد — O(n)","وقتی تعداد گره‌ها زوج است","بدترین حالت وجود ندارد"],"ans":1,"why":"ورودی از قبل مرتب (یا معکوسش) همه گره‌ها را در یک راستا می‌چیند؛ ارتفاع n می‌شود و خاصیت log n از بین می‌رود."}]'::jsonb),
('dsa-x3', 'dsa', 'جدول هش از نزدیک — سریع‌ترین ساختار تاریخ', 50, 9, '[{"k":"p","t":"dict پایتون، Map جاوا، object جاوااسکریپت، ایندکس دیتابیس، کش Redis — همه یک ایده‌اند: تابعی که کلید را به یک ایندکس تبدیل می‌کند تا مستقیم سراغ خانه‌اش برویم. بدون گشتن، بدون مقایسه — فقط یک محاسبه. این یعنی میانگین O(1) برای خواندن، نوشتن و حذف."},{"k":"visual","visual":"hashTable","title":"شبیه‌ساز: از کلید تا سطل"},{"k":"h","t":"برخورد و راه‌حل‌هایش"},{"k":"p","t":"دو کلید مختلف ممکن است هش یکسان بدهند (تولد مشترک!). به این می‌گویند Collision و دو راه‌حل کلاسیک دارد: زنجیره‌کردن (هر سطل یک لیست کوچک) یا نشانی باز (پیدا کردن خانه خالی بعدی). پایتون از نشانی باز استفاده می‌کند."},{"k":"table","head":["روش","مزیت","عیب"],"rows":[["زنجیره (Separate Chaining)","ساده؛ حذف راحت","اشاره‌گر اضافه، Cache بدتر"],["نشانی باز (Open Addressing)","حافظه پیوسته، Cache عالی","حذف پیچیده (نشان‌گذاری Tombstone)"]]},{"k":"def","term":"ضریب بار (Load Factor)","t":"نسبت تعداد عناصر به تعداد سطل‌ها. وقتی از آستانه (مثلاً ۰٫۷۵) رد شود، جدول ظرفیت را دوبرابر و همه عناصر را Rehash می‌کند — یک عمل O(n) که چون بندرت رخ می‌دهد، میانگین هزینه همچنان O(1) استهلاکی می‌ماند."},{"k":"code","lang":"py","title":"dict زیر کاپوت","code":"seen = {}\nfor name in [''ali'', ''sara'', ''ali'', ''omid'', ''sara'', ''ali'']:\n    seen[name] = seen.get(name, 0) + 1\nprint(seen)   # {''ali'': 3, ''sara'': 2, ''omid'': 1}\n\n# چرا این سریع است؟ چون dict مستقیم سراغ خانه name می‌رود.\n# معادل لیستی‌اش برای n عنصر، O(n) مقایسه می‌خواست."},{"k":"warn","title":"هش بد = فاجعه","t":"اگر تابع هش کلیدها را یکجا پخش نکند، همه در چند سطل جمع می‌شوند و O(1) می‌شود O(n). هش خوب: قطعی، سریع، و پخش یکنواخت. برای کلیدهای خودت __hash__ و __eq__ را با هم و سازگار تعریف کن."},{"k":"tip","title":"نکته منتور","t":"وقتی در مصاحبه می‌پرسند «چطور این را سریع‌تر کنی؟» و جواب «هش‌تیبل» است، معمولاً درست است — تبدیل جست‌وجوی O(n) داخل حلقه به O(1)، کلاسیک‌ترین بهینه‌سازی دنیاست."}]'::jsonb, '[{"q":"چرا عملیات هش‌تیبل «میانگین» O(1) است نه «همیشه»؟","opts":["چون زبان‌ها ضعیف‌اند","چون در صورت برخورد یا پرشدن جدول، هزینه بالا می‌رود","چون کلیدها رشته‌اند","O(1) نیست"],"ans":1,"why":"Rehash هنگام دوبرابرشدن و سطل‌های شلوغ هنگام برخورد، موارد نادری‌اند که هزینه می‌برند؛ میانگینِ آماری همچنان ثابت است."},{"q":"ضریب بار ۰٫۷۵ یعنی چه و چرا مهم است؟","opts":["۷۵٪ حافظه خراب است","سه‌چهارم سطل‌ها پرند — آستانه‌ای که بعد از آن Rehash می‌شود تا سرعت حفظ شود","نسخه هش","تعداد کلیدهای تکراری"],"ans":1,"why":"اگر جدول خیلی پر شود برخوردها زیاد و سرعت کم می‌شود؛ با دوبرابرکردن به‌موقع، تعادل حافظه/سرعت حفظ می‌شود."}]'::jsonb),
('dsa-b1', 'dsa', 'آرایه و تحلیل هزینه عملیات', 63, 10, '[{"k":"p","t":"آرایه داده‌ها را پشت‌سرهم در حافظه نگه می‌دارد؛ همین یعنی دسترسی O(1) با ایندکس، ولی درج وسط، شیفت O(n) می‌خواهد."},{"k":"h","t":"چرا «پشت‌سرهم بودن» این‌همه مهم است؛ کش و Locality"},{"k":"p","t":"Big-O می‌گوید آرایه و لیست پیوندی در پیمایش هر دو O(n)‌اند — ولی در عمل، آرایه می‌تواند ده برابر سریع‌تر باشد. رازش کش CPU است: پردازنده داده را بلوک‌بلوک (cache line، معمولاً ۶۴ بایت) از حافظه می‌آورد؛ وقتی عناصر پشت‌سرهم‌اند، آوردن یک بلوک، عناصر بعدی را هم «مفت» می‌آورد (Spatial Locality). گره‌های لیست پیوندی در heap پراکنده‌اند؛ هر گره یک miss و سفر به RAM (صدها برابر کندتر از کش). پس هنگام انتخاب ساختار، فقط Big-O را نبین: برای پیمایش‌های سنگین، پیوستگی حافظه یک ضریب پنهان اما واقعی است که مصاحبه‌گرهای خوب دنبالش می‌گردند."},{"k":"h","t":"داستان رشد دینامیک؛ از O(n) تا آمورتیزه O(1)"},{"k":"p","t":"append لیست چطور O(1) است با اینکه گاهی کل آرایه کپی می‌شود؟ وقتی ظرفیت پر است، پایتون آرایه‌ای بزرگ‌تر (حدود ۱.۱۲۵ برابر) می‌سازد و همه را کپی می‌کند — این یک عمل O(n) است. ولی چون ظرفیت هندسی رشد می‌کند، بین دو کپیِ بزرگ، تعداد زیادی append ارزان جا می‌گیرد؛ اگر هزینه همه کپی‌ها را بر تعداد کل appendها تقسیم کنی، سهم هر append یک عدد ثابت می‌شود. به این می‌گویند هزینه آمورتیزه: «ممکن است گاهی گران شود، ولی میانگینِ بلندمدت هر عمل، ثابت است». دقیقاً مثل وام: قسط‌ها ثابت‌اند حتی اگر ماه‌هایی اصل پول پرداخت شود."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"اندازه‌گیری واقعی تفاوت O(1) و O(n)","code":"from time import perf_counter\nimport random\n\nlst = list(range(200_000))\n\nt0 = perf_counter()\nfor _ in range(1000): lst.append(1)      # انتها: آمورتیزه O(1)\nt1 = perf_counter()\nfor _ in range(1000): lst.insert(0, 1)   # ابتدا: O(n) شیفت\nt2 = perf_counter()\n\nprint(f''append:  {(t1-t0)*1e6:,.0f} میکروثانیه'')\nprint(f''insert0: {(t2-t1)*1e6:,.0f} میکروثانیه'')\n# insert معمولاً چند صد برابر کندتر است"},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["عملیات","پیچیدگی","دلیل فیزیکی"],"rows":[["خواندن ایندکس","O(1)","آدرس = پایه + i×اندازه؛ یک جمع و ضرب"],["append","O(1) آمورتیزه","رشد هندسی، کپی‌ها را پخش می‌کند"],["insert(0) / pop(0)","O(n)","شیفت همه اشاره‌گرها"],["جست‌وجوی بی‌ترتیب","O(n)","بدترین حالت: کل پیمایش"]]},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["خواندن با ایندکس O(1) چون آدرس = پایه + ایندکس×اندازه","افزودن به انتها آمورتیزه O(1) با دو برابر کردن ظرفیت","حذف و درج وسط O(n) به‌خاطر جابه‌جایی بقیه"]},{"k":"h","t":"کاربرد و مقایسه"},{"k":"table","head":["عملیات","پیچیدگی"],"rows":[["خواندن با ایندکس","O(1)"],["افزودن به انتها","O(1) آمورتیزه"],["درج/حذف وسط","O(n)"],["جست‌وجوی خطی","O(n)"]]},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: خواندن با ایندکس O(1) چون آدرس = پایه + ایندکس×اندازه بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا خواندن آرایه با ایندکس O(1) است؟","opts":["کش دارد","آدرس حافظه با یک ضرب و جمع حساب می‌شود","کوچک است","مرتب است"],"ans":1,"why":"عناصر پشت‌سرهم‌اند؛ آدرس هر ایندکس مستقیم محاسبه می‌شود بدون پیمایش."},{"q":"چرا دو لیست با Big-O یکسان می‌توانند ده برابر اختلاف سرعت داشته باشند؟","opts":["باگ پایتون","Locality و کش: آرایه پیوسته با هر بار خواندن، همسایه‌ها را هم به کش می‌آورد؛ گره‌های پراکنده miss می‌خورند","اندازه داده","نسخه پایتون"],"ans":1,"why":"Big-O ثابت‌ها را پنهان می‌کند؛ در عمل کش CPU همان ثابت است — و می‌تواند ۱۰ تا ۱۰۰ برابر باشد. ساختار پیوسته برای پیمایش، برنده پنهان است."},{"q":"چرا آرایه‌ها هنگام پر شدن معمولاً ۲ برابر (نه ۱۰ واحد) رشد می‌کنند؟","opts":["حافظه ارزان است","رشد هندسی، هزینه کپی را بین عمل‌های بعدی پخش و append را آمورتیزه O(1) نگه می‌دارد؛ رشد خطی آن را O(n) می‌کرد","ساده‌تر است","استاندارد است"],"ans":1,"why":"با رشد +۱۰، هر ده append یک کپی O(n) می‌خواهد و میانگین خطی می‌شود؛ با ×۲ تعداد کپی‌ها لگاریتمی و میانگین ثابت می‌ماند."}]'::jsonb),
('dsa-b2', 'dsa', 'لیست پیوندی و انواع آن', 63, 11, '[{"k":"p","t":"لیست پیوندی گره‌هایی است که با اشاره‌گر به هم وصل‌اند؛ درج و حذف سر O(1) ولی دسترسی با ایندکس O(n) است."},{"k":"h","t":"قدرت واقعی لیست پیوندی؛ Splice و ساختارهای درونی"},{"k":"p","t":"درج در سرِ لیست پیوندی O(1) است چون هیچ داده‌ای جابه‌جا نمی‌شود — فقط دو اشاره‌گر عوض می‌شود. این ویژگی جایی می‌درخشد که وسط لیست را داری: «برش و دوخت» (Splice) یعنی خارج‌کردن یک بازه و وصل‌کردن جای دیگر، فقط با وصل‌و‌قطع اشاره‌گرها — بدون هیچ کپی. به همین دلیل است که LRU Cacheها (حذف از وسط + درج در سر)، لیست مجاورت گراف‌ها و buffer ویرایشگرها اغلب روی لیست پیوندی سوارند. ولی صداقت مهندسی: برای بیشتر کاربردهای روزمره، آرایه دینامیک به‌خاطر کش و سادگی می‌برد؛ لیست پیوندی را برای زمانی نگه دار که واقعاً درج/حذفِ میانیِ پرتکرار داری."},{"k":"h","t":"دو اشاره‌گر؛ الگویی که نیمی از سوالات مصاحبه است"},{"k":"p","t":"بیشتر سوالات کلاسیک لیست پیوندی با یک الگو حل می‌شوند: دو اشاره‌گر با سرعت متفاوت. اشاره‌گر تند دو گره و کند یک گره جلو برود — اگر حلقه‌ای باشد، تند به کند می‌رسد (تشخیص سیکل فلوید). اگر تند به انتها برسد، کند دقیقاً وسط ایستاده (پیدا کردن وسط در یک پاس، برای مرج‌سورت روی لیست). و معکوس‌کردن لیست هم سه اشاره‌گر می‌خواهد (قبلی، جاری، بعدی) که در هر گام جهت یک next را برمی‌گرداند. این سه الگو — تشخیص سیکل، پیدا کردن وسط، معکوس — را با دست روی کاغذ یک‌بار بکش؛ بعد از آن، ده‌ها سوال مصاحبه شکلِ تغییر‌یافته‌ی همین‌هاست."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"معکوس‌کردن لیست پیوندی درجا","code":"class Node:\n    def __init__(self, val, nxt=None):\n        self.val, self.next = val, nxt\n\ndef reverse(head):\n    prev = None\n    cur = head\n    while cur:\n        nxt = cur.next   # بعدی را قبل از قطع ذخیره کن\n        cur.next = prev  # جهت را برگردان\n        prev = cur       # prev جلو برود\n        cur = nxt        # cur جلو برود\n    return prev          # prev سر جدید است\n\n# 1 -> 2 -> 3  می‌شود  3 -> 2 -> 1"},{"k":"def","term":"گره سرِ نگهبان (Sentinel/Dummy Head)","t":"یک گره مصنوعی قبل از سر واقعی که باعث می‌شود «درج/حذف در سر» با بقیه جاها یک‌جور شود — بدون ifهای جدا برای حالت تهی. در پیاده‌سازی‌های LRU و لیست‌های دوطرفه، نیمی از باگ‌های حالت‌مرزی را از اساس حذف می‌کند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["هر گره داده + next دارد؛ دوطرفه prev هم دارد","درج سر بدون شیفت، فقط چند اشاره‌گر عوض می‌شود","کش‌ناپذیر است چون گره‌ها پراکنده‌اند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"linked.py","code":"class Node:\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\ndef push_front(head, val):\n    n = Node(val)\n    n.next = head\n    return n"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: هر گره داده + next دارد؛ دوطرفه prev هم دارد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"در کدام عملیات لیست پیوندی از آرایه بهتر است؟","opts":["خواندن با ایندکس","درج و حذف از سر","جست‌وجوی دودویی","پیمایش معکوس یک‌طرفه"],"ans":1,"why":"درج سر فقط اشاره‌گرها را عوض می‌کند O(1)؛ آرایه باید همه را شیفت دهد O(n)."},{"q":"اشاره‌گر تند و کند چطور وسط لیست را در یک پاس پیدا می‌کنند؟","opts":["شانسی","وقتی تند به انتها می‌رسد (n گره رفته)، کند دقیقاً n/۲ رفته — یعنی وسط","با شمارش","ممکن نیست"],"ans":1,"why":"تند دو برابر کند حرکت می‌کند؛ پس مسافت تند دو برابر مسافت کند است. وقتی تند تمام کرد، کند در نیمه راه است — بدون پاس دوم."},{"q":"در معکوس‌کردن، چرا قبل از تغییر cur.next باید آن را در nxt ذخیره کنیم؟","opts":["برای سرعت","چون بعد از cur.next = prev، تنها راه رسیدن به ادامه لیست همان مقدار قبلی است — وگرنه بقیه لیست گم می‌شود","عادت است","برای GC"],"ans":1,"why":"تغییر اشاره‌گر پلِ پشت سرت را خراب می‌کند؛ ذخیره‌کردن قبلی، طناب نجاتی است که تا پایان حلقه دنبالش می‌روی."}]'::jsonb),
('dsa-b3', 'dsa', 'پشته و کاربردهایش', 63, 12, '[{"k":"p","t":"پشته ساختاری LIFO است: آخرین ورودی، اولین خروجی. push و pop هر دو O(1)‌اند و برای بازگشت، undo و تحلیل عبارت استفاده می‌شود."},{"k":"h","t":"پشته‌ای که همین حالا داری استفاده می‌کنی؛ Call Stack"},{"k":"p","t":"هر بار تابعی صدا می‌شود، مفسر یک Frame روی پشته می‌گذارد: متغیرهای محلی، پارامترها و آدرس برگشت. وقتی تابع تمام شد، frame برمی‌گردد و اجرای تابعِ صدا‌زننده از همان‌جا ادامه می‌یابد. این یعنی بازگشت، رایگان نیست: عمق n یعنی n فریم در حافظه — و پایتون عمق پیش‌فرض را ۱۰۰۰ گذاشته (RecursionError بعد از آن). حالا یک باگ معروف را می‌فهمی: بازگشت بدون حالت پایه یعنی فریم‌های بی‌نهایت و سرریز پشته. و یک کاربرد روزمره: وقتی دیوتولز یا traceback را می‌خوانی، داری خودِ پشته فراخوانی را از بالا (آخرین فراخوانی) به پایین (main) نگاه می‌کنی."},{"k":"h","t":"پشته monotonic؛ حل «اولین بزرگ‌تر بعدی» در O(n)"},{"k":"p","t":"سوال کلاسیک: برای هر روز دما، چند روز صبر تا گرم‌تر؟ راه ساده، دو حلقه O(n²) است. راه پشته‌ای: یک پشته نگه دار از ایندکس روزهایی که هنوز «روز گرم‌ترشان» را ندیده‌اند — و دماهایشان از پایین پشته به بالا نزولی است (برای همین monotonic). روز جدید که می‌آید، تا وقتی از سر پشته گرم‌تر است، جواب همه آن‌هاست: pop کن و فاصله را ثبت کن. هر ایندکس حداکثر یک‌بار وارد و یک‌بار خارج می‌شود، پس کل الگوریتم O(n) است. این الگو — «نگه‌داشتن نامزدهای بی‌جواب در پشته با ترتیب مشخص» — قفل گشای ده‌ها سوال مشابه است: مساحت مستطیل در هیستوگرام، محدوده‌های قیمت، و دیدن ساختمان‌ها."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"روزهای تا دمای گرم‌تر با پشته monotonic","code":"def days_until_warmer(temps):\n    n = len(temps)\n    answer = [0] * n\n    stack = []                       # ایندکس‌های بی‌جواب\n    for i, t in enumerate(temps):\n        while stack and temps[stack[-1]] < t:\n            j = stack.pop()          # امروز جواب روز j است\n            answer[j] = i - j\n        stack.append(i)\n    return answer\n\nprint(days_until_warmer([30, 25, 28, 35, 24]))\n# [3, 1, 1, 0, 0]"},{"k":"def","term":"پشته Monotonic","t":"پشته‌ای که عناصرش با ترتیب مشخص (صعودی یا نزولی) نگه داشته می‌شوند؛ هنگام درج، عناصر ناقضِ ترتیب pop می‌شوند. قدرتش این است که «نامزدِ منتظرِ رویداد بعدی» را در O(1) پیدا می‌کند و کل پیمایش را O(n) نگه می‌دارد."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["call stack همان پشته فراخوانی توابع است","بررسی پرانتزهای متوازن با پشته حل می‌شود","پیاده‌سازی با list: append برای push و pop برای pop"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"stack.py","code":"def balanced(s):\n    pairs = {'')'': ''('', '']'': ''['', ''}'': ''{''}\n    st = []\n    for c in s:\n        if c in pairs.values(): st.append(c)\n        elif c in pairs:\n            if not st or st.pop() != pairs[c]:\n                return False\n    return not st\nprint(balanced(''{[()]}''))"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: call stack همان پشته فراخوانی توابع است بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا بررسی پرانتز متوازن با پشته حل می‌شود؟","opts":["چون رشته کوتاه است","چون هر بست باید با آخرین بازِ بسته‌نشده جفت شود — دقیقاً LIFO","چون مرتب است","تصادفی است"],"ans":1,"why":"LIFO تضمین می‌کند آخرین پرانتز باز، اولین چیزی است که باید بسته شود."},{"q":"چرا هر ایندکس در الگوریتم بالا حداکثر یک‌بار pop می‌شود؟","opts":["شانسی","چون بعد از pop جوابش ثبت شده و دیگر وارد پشته نمی‌شود — ورود و خروج هر عنصر یک‌بار یعنی O(n) جمع","پشته کوچک است","ورودی محدود"],"ans":1,"why":"معیار آمورتیزه کلاسیک: اگر مجموع pushها n و هر عنصر حداکثر یک‌بار pop شود، کل عملیات‌های پشته ۲n است — پس حلقه درونی با وجود ظاهرش، خطی است."},{"q":"RecursionError در پایتون نشانه چیست؟","opts":["باگ سخت‌افزاری","پر شدن Call Stack — بازگشت عمیق‌تر از ظرفیت فریم‌ها رفته (حالت پایه دور است یا نیست)","خطای تایپ","حافظه heap پر است"],"ans":1,"why":"هر فراخوانی بازگشتی یک فریم می‌سازد؛ عمق ۱۰۰۰+ یعنی هزاران فریم. درمان: حالت پایه درست، یا تبدیل به حلقه با پشته صریح."}]'::jsonb),
('dsa-b4', 'dsa', 'صف و دوطرفه', 63, 13, '[{"k":"p","t":"صف FIFO است: اولین ورودی اولین خروجی — برای نوبت‌دهی و BFS. deque پایتون از دو سر O(1) دارد و جایگزین درست list برای صف است."},{"k":"h","t":"صف؛ جایی که نظمِ ورود، عدالت سیستم است"},{"k":"p","t":"صف FIFO یک قرارداد انصاف است: اولین درخواست، اولین خدمت. ولی قدرت مهندسی‌اش فراتر از عدالت است — صف «تولیدکننده و مصرف‌کننده» را از هم جدا می‌کند: یکی با سرعت خودش می‌سازد، دیگری با سرعت خودش برمی‌دارد و صف بینشان ضربه‌گیر است. این همان ایده‌ای است که در چاپگر سیستم‌عامل، صف پیام‌های RabbitMQ، بیلد سرورهای CI و حتی Event Loop جاوااسکریپت می‌بینی. هر جا دو سرعتِ متفاوت باید به هم برسند بدون اینکه کسی معطلِ دیگری بایستد، یک صف وسط است — و BFS روی گراف هم دقیقاً همین است: مرزِ کشف‌شده‌ها، صفی از گره‌هایی است که نوبت بررسی‌شان می‌رسد."},{"k":"h","t":"انواع صف و زمانِ هرکدام"},{"k":"p","t":"سه گونه اصلی را با معیار انتخاب بشناس. صف ساده (deque): ترتیب ورود مقدس است — برای BFS و بافر. صف اولویت‌دار (heapq در پایتون): ترتیب را «اهمیت» تعیین می‌کند نه زمان ورود — برای زمان‌بندی taskها، مسیر یابی دایکسترا و ادغام k لیست مرتب؛ خروجی همیشه کوچک‌ترین (یا بزرگ‌ترین با قرینه) است و درج و برداشت هر دو O(log n). و بافر حلقه‌ای (ring buffer): اندازه ثابت، داده قدیمی خودکار دور ریخته می‌شود — برای لاگ‌های «آخرین N اتفاق» و بافرهای صدا. قاعده انتخاب: اگر پرسیدی «بعدی کیست؟» و جواب «اولین آمده» بود، deque؛ اگر «مهم‌ترین» بود، heap."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"BFS سطح‌به‌سطح با deque","code":"from collections import deque\n\ngraph = {''الف'': [''ب'', ''ج''], ''ب'': [''د''], ''ج'': [''د''], ''د'': []}\n\ndef bfs_levels(start):\n    seen = {start}\n    q = deque([start])\n    level = 0\n    while q:\n        for _ in range(len(q)):      # فقط هم‌سطحی‌ها\n            v = q.popleft()\n            print(f''سطح {level}: {v}'')\n            for w in graph[v]:\n                if w not in seen:\n                    seen.add(w)\n                    q.append(w)\n        level += 1\n\nbfs_levels(''الف'')"},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["ساختار","ترتیب خروج","درج/برداشت","کاربرد"],"rows":[["deque","FIFO (یا LIFO)","O(1) از دو سر","BFS، بافر"],["heapq","اولویت (کوچک‌ترین)","O(log n)","دایکسترا، زمان‌بندی"],["Ring buffer","قدیمی‌ها می‌ریزند","O(1) ثابت‌اندازه","لاگ آخر N"]]},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["collections.deque برای صف واقعی استفاده کن","append و popleft در deque هر دو O(1)","لیست معمولی برای صف بد است چون pop(0) برابر O(n)"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"queue.py","code":"from collections import deque\nq = deque([''الف'', ''ب''])\nq.append(''ج'')          # ورود از انتها\nprint(q.popleft())     # خروج از ابتدا: الف"},{"k":"warn","title":"هشدار","t":"استفاده از list و pop(0) برای صف، هر خروج را O(n) می‌کند — برای هزاران عمل، تفاوت ثانیه‌هاست. همیشه deque."},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: collections.deque برای صف واقعی استفاده کن بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا deque برای صف از list بهتر است؟","opts":["مرتب‌تر است","خروج از سرش O(1) است ولی pop(0) لیست برابر O(n)","حافظه کمتری دارد","بزرگ‌تر است"],"ans":1,"why":"deque از دو سر بهینه است؛ لیست برای حذف از سر باید همه را شیفت دهد."},{"q":"در BFS چرا popleft می‌زنیم نه pop؟","opts":["هر دو یکی‌ست","چون BFS به ترتیبِ فاصله از مبدأ نیاز دارد — FIFO؛ pop از انتها یعنی DFS و ترتیب فاصله به‌هم می‌ریزد","سریع‌تر است","عادت است"],"ans":1,"why":"FIFO تضمین می‌کند گره‌های فاصله k همه قبل از فاصله k+1 پردازش شوند — خاصیت «اولین ملاقات = کوتاه‌ترین مسیر» از همین‌جا می‌آید."},{"q":"برای صف کاری که مهم‌ترین job اول اجرا شود، کدام ساختار؟","opts":["deque","heapq (صف اولویت‌دار) — چون ترتیب را اهمیت تعیین می‌کند نه زمان ورود","لیست مرتب","پشته"],"ans":1,"why":"FIFO به زمان ورود وفادار است؛ صف اولویت با هر بار برداشت، کوچک‌ترین/بزرگ‌ترین را می‌دهد — دقیقاً تعریف «مهم‌ترین اول» با هزینه log n."}]'::jsonb),
('dsa-b5', 'dsa', 'جدول هش و برخورد', 56, 14, '[{"k":"p","t":"جدول هش کلید را با تابع هش به ایندکس آرایه تبدیل می‌کند؛ دسترسی میانگین O(1). برخورد وقتی دو کلید یک ایندکس بخواهند رخ می‌دهد."},{"k":"h","t":"چرا هش به O(1) می‌رسد"},{"k":"p","t":"ایده جدول هش این است: به‌جای گشتن دنباله‌ی داده، از خودِ کلید «جای» آن را حساب کنی. تابع هش کلید را به یک عدد و بعد با پیمانهِ تعداد سطل‌ها به یک ایندکس تبدیل می‌کند؛ پس دسترسی یعنی یک محاسبه و رفتن سرِ خانه — نه پیمایش. این همان تفاوت O(1) با O(n) است. شرطش این است که تابع هش خوب، کلیدها را یکنواخت پخش کند تا برخوردها کم بمانند."},{"k":"h","t":"برخورد و دو راه‌حلش"},{"k":"p","t":"چون تعداد سطل‌ها محدود است، دو کلید متفاوت می‌توانند به یک ایندکس برسند — برخورد. دو راه اصلی: زنجیره‌سازی که هر سطل یک لیست از ورودی‌های هم‌خانه نگه می‌دارد (ساده و رایج)، و آدرس‌بازی باز که هنگام برخورد سراغ خانه بعدی می‌رود (حافظه فشرده‌تر ولی حذف سخت‌تر). وقتی ضریب بار (نسبت ورودی‌ها به سطل‌ها) بالا می‌رود، برخوردها زیاد و دسترسی از O(1) به سمت O(n) میل می‌کند — پس جدول خوب، اندازه‌اش را با داده بزرگ می‌کند."},{"k":"def","term":"ضریب بار (Load Factor)","t":"نسبت تعداد ورودی‌ها به تعداد سطل‌ها. هرچه بالاتر، برخوردها بیشتر و دسترسی کندتر. جدول‌های هش خوب وقتی ضریب از آستانه‌ای (مثل 0.75) رد شد، خودشان را بزرگ و همه ورودی‌ها را دوباره پخش می‌کنند تا O(1) میانگین حفظ شود."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["روش برخورد","ایده","نقطه قوت","نقطه ضعف"],"rows":[["زنجیره‌سازی","هر سطل یک لیست","ساده، حذف آسان","سربار اشاره‌گر"],["آدرس‌بازی باز","خانه بعدی را امتحان کن","حافظه فشرده، کش‌دوست","حذف و rehash سخت‌تر"]]},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["زنجیره‌سازی: هر ایندکس یک لیست از ورودی‌ها","آدرس‌بازی باز: جست‌وجوی خانه بعدی هنگام برخورد","ضریب بار بالا یعنی برخوردهای بیشتر و کندتر"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"hash.py","code":"class SimpleMap:\n    def __init__(self, size=8):\n        self.buckets = [[] for _ in range(size)]\n    def put(self, k, v):\n        i = hash(k) % len(self.buckets)\n        self.buckets[i].append((k, v))\n    def get(self, k):\n        i = hash(k) % len(self.buckets)\n        for key, v in self.buckets[i]:\n            if key == k: return v"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: زنجیره‌سازی: هر ایندکس یک لیست از ورودی‌ها بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"برخورد در جدول هش یعنی چه؟","opts":["دو کلید متفاوت به یک ایندکس نگاشت شوند","هش خراب شده","حافظه پر شده","کلید تکراری است"],"ans":0,"why":"چون تعداد ایندکس‌ها محدود است، دو کلید می‌توانند هم‌خانه شوند و باید با زنجیره یا آدرس‌بازی باز حل شود."},{"q":"چرا دسترسی جدول هش «میانگین» O(1) است نه همیشه؟","opts":["تصادفی","چون در صورت برخورد، باید زنجیره همان سطل را هم بگردی؛ اگر هش بد باشد و همه به یک سطل بریزند، O(n) می‌شود","کند است","وابسته به حافظه"],"ans":1,"why":"O(1) با فرض پخش یکنواخت است؛ در بدترین حالت (همه کلیدها هم‌سطل) دسترسی یعنی پیمایش یک لیست بلند. پس کیفیت تابع هش و ضریب بار است که این تضمین را واقعی می‌کند."},{"q":"اگر جدول هش بدون بزرگ‌شدن پر شود چه اتفاقی برای سرعت می‌افتد؟","opts":["همان می‌ماند","ضریب بار بالا می‌رود، برخوردها زیاد می‌شود و زنجیره‌ها بلند — دسترسی از O(1) به سمت O(n) می‌رود","کرش می‌کند","حافظه خالی می‌شود"],"ans":1,"why":"سرعت جدول هش به کوتاه‌بودن زنجیره‌ها وابسته است؛ با ثابت‌ماندن تعداد سطل‌ها و رشد داده، هر سطل شلوغ‌تر می‌شود. به همین دلیل جدول‌های خوب خودشان rehash و بزرگ می‌شوند."}]'::jsonb),
('dsa-b6', 'dsa', 'درخت دودویی و پیمایش‌ها', 63, 15, '[{"k":"p","t":"درخت دودویی هر گره حداکثر دو فرزند دارد. سه پیمایش اصلی — پیش‌ترتیب، میان‌ترتیب، پس‌ترتیب — ترتیب بازدید ریشه نسبت به فرزندان‌اند."},{"k":"h","t":"سه پیمایش، سه کاربرد"},{"k":"p","t":"تفاوت پیش‌ترتیب (ریشه اول)، میان‌ترتیب (ریشه وسط) و پس‌ترتیب (ریشه آخر) فقط در جای بازدید ریشه نسبت به فرزندان است — و همین تفاوت، کاربردشان را تعیین می‌کند. پیش‌ترتیب برای کپی‌کردن درخت خوب است چون پدر را قبل از فرزند می‌بینی؛ میان‌ترتیب در BST خروجی مرتب می‌دهد؛ و پس‌ترتیب برای حذف درخت مناسب است چون اول فرزندان را پردازش می‌کنی بعد پدر را."},{"k":"h","t":"بازگشت یا پشته؟"},{"k":"p","t":"پیمایش بازگشتی طبیعی‌ترین بیان است چون خودِ درخت بازگشتی تعریف می‌شود؛ ولی هر فراخوان بازگشتی یک قاب stack می‌گیرد و برای درخت خیلی عمیق ممکن است سرریز کند. نسخه غیربازگشتی با یک stack صریح همان منطق را بدون محدودیت عمق اجرا می‌کند — برای BFS هم از صف استفاده می‌شود نه stack. دانستن هر دو شکل، هم فهم را عمیق می‌کند هم دستت را در مصاحبه باز می‌گذارد."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"میان‌ترتیب غیربازگشتی با stack","code":"def inorder_iter(root):\n    out, stack, cur = [], [], root\n    while cur or stack:\n        while cur:                 # تا تهِ چپ برو و در راه ذخیره کن\n            stack.append(cur)\n            cur = cur.l\n        cur = stack.pop()          # برگرد به آخرین پدر\n        out.append(cur.v)\n        cur = cur.r                # حالا برو سراغ راست\n    return out\n# در BST، out مرتب است"},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["میان‌ترتیب (چپ، ریشه، راست) در BST خروجی مرتب می‌دهد","پیمایش با بازگشت طبیعی و با پشته/صف غیربازگشتی است","ارتفاع درخت، هزینه عملیات‌ها را تعیین می‌کند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"tree.py","code":"class N:\n    def __init__(s, v, l=None, r=None):\n        s.v, s.l, s.r = v, l, r\n\ndef inorder(n):\n    if n is None: return []\n    return inorder(n.l) + [n.v] + inorder(n.r)\n\nt = N(2, N(1), N(3))\nprint(inorder(t))   # [1, 2, 3]"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: میان‌ترتیب (چپ، ریشه، راست) در BST خروجی مرتب می‌دهد بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"کدام پیمایش در BST خروجی مرتب می‌دهد؟","opts":["پیش‌ترتیب","میان‌ترتیب","پس‌ترتیب","سطحی"],"ans":1,"why":"میان‌ترتیب اول چپ (کوچک‌ترها)، بعد ریشه، بعد راست (بزرگ‌ترها) را می‌بیند — پس مرتب است."},{"q":"برای حذف امن همه گره‌های یک درخت، کدام پیمایش منطقی‌تر است؟","opts":["پیش‌ترتیب","پس‌ترتیب — چون اول فرزندان پردازش/آزاد می‌شوند و بعد پدر","میان‌ترتیب","سطحی"],"ans":1,"why":"برای آزادکردن، باید اول به فرزندان دسترسی داشته باشی؛ پس‌ترتیب تضمین می‌کند وقتی به پدر می‌رسی، فرزندانش قبلاً پردازش شده‌اند — پس می‌توانی امن حذفش کنی."},{"q":"چرا BFS از صف استفاده می‌کند نه stack؟","opts":["قرارداد","چون باید لایه‌به‌لایه پیش برود: هر گره‌ای که کشف شد به انتها می‌رود و نوبتش بعد از هم‌لایه‌ای‌هاست — FIFO؛ با stack عمیق می‌شد (DFS)","سرعت","حافظه"],"ans":1,"why":"ترتیب پردازش با ساختار داده عوض می‌شود: صف (FIFO) هم‌لایه‌ها را قبل از لایه بعد تمام می‌کند که تعریف BFS است؛ stack (LIFO) همیشه جدیدترین را برمی‌دارد و به عمق می‌رود."}]'::jsonb),
('dsa-b7', 'dsa', 'درخت جست‌وجوی دودویی', 56, 16, '[{"k":"p","t":"BST درختی است که چپِ هر گره کوچک‌تر و راستش بزرگ‌تر است؛ جست‌وجو، درج و حذف میانگین O(log n) ولی در بدترین حالت O(n)."},{"k":"h","t":"توازن؛ مرز بین log n و n"},{"k":"p","t":"BST فقط وقتی جست‌وجوی O(log n) می‌دهد که ارتفاعش حدود log n باشد — یعنی متوازن. اگر داده‌ها مرتب وارد شوند (۱،۲،۳،...)، هر گره فقط یک فرزند راست می‌گیرد و درخت به یک لیست زنجیری تبدیل می‌شود با ارتفاع n؛ پس همه عملیات‌ها خطی می‌شوند. به همین دلیل BSTهای واقعی (AVL، Red-Black) بعد از هر درج و حذف، با چرخش‌های موضعی خودشان را متوازن نگه می‌دارند تا ارتفاع همیشه log n بماند."},{"k":"h","t":"حذف گره دوفرزندی"},{"k":"p","t":"حذف گره بدون فرزند یا تک‌فرزند ساده است، ولی گره دوفرزندی را نمی‌توان مستقیم برداشت چون دو زیردرخت دارد. راه‌حل: جانشین میان‌ترتیب را پیدا کن — کوچک‌ترین گره زیردرخت راست (یا بزرگ‌ترینِ چپ) — که خودش حداکثر یک فرزند دارد، مقدارش را جای گره حذفی بگذار و آن را از جای اصلی‌اش حذف کن. چون جانشین از همه سمت راست کوچک‌تر و از همه چپ بزرگ‌تر است، خاصیت BST حفظ می‌شود."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["ساختار","جست‌وجو","مرتب‌بودن زنده","نیاز به توازن"],"rows":[["BST ساده","میانگین O(log n)، بدترین O(n)","بله","دستی"],["AVL / Red-Black","همیشه O(log n)","بله","خودکار"],["جدول هش","میانگین O(1)","خیر","ندارد"]]},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["توازن شرط O(log n) است؛ درخت کج به لیست تبدیل می‌شود","حذف گره دوفرزندی با جانشین میان‌ترتیب انجام می‌شود","AVL و Red-Black خودشان را متوازن نگه می‌دارند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"bst.py","code":"def insert(root, v):\n    if root is None: return N(v)\n    if v < root.v: root.l = insert(root.l, v)\n    elif v > root.v: root.r = insert(root.r, v)\n    return root\n\ndef search(root, v):\n    if root is None or root.v == v: return root\n    return search(root.l, v) if v < root.v else search(root.r, v)"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: توازن شرط O(log n) است؛ درخت کج به لیست تبدیل می‌شود بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا BST کج به O(n) می‌رسد؟","opts":["حافظه کم می‌آورد","وقتی داده‌ها مرتب وارد شوند، درخت مثل لیست زنجیری می‌شود","هش خراب می‌شود","ممکن نیست"],"ans":1,"why":"ورود داده‌های مرتب همه را در یک شاخه می‌چیند؛ ارتفاع n می‌شود و همه عملیات‌ها خطی."},{"q":"چرا واردکردن داده‌های ازپیش‌مرتب‌شده به BST ایده بدی است؟","opts":["کند می‌شود چون","درخت به یک زنجیره یک‌طرفه تبدیل می‌شود و همه عملیات‌ها O(n) می‌شوند — مزیت درخت از بین می‌رود","حافظه می‌گیرد","ممکن نیست"],"ans":1,"why":"BST با مقایسه چپ/راست پخش می‌کند؛ داده مرتب همیشه یک سمت را می‌گیرد و عمق n می‌سازد. اگر مجبوری داده مرتب بدهی، از درخت خودمتوازن یا ساخت هیپ استفاده کن."},{"q":"جانشین میان‌ترتیب برای حذف گره دوفرزندی چرا خاصیت BST را حفظ می‌کند؟","opts":["تصادفی","چون کوچک‌ترینِ سمت راست است — از همه چپ بزرگ‌تر و از بقیه راست کوچک‌تر؛ پس جابه‌جایش ترتیب را به‌هم نمی‌زند","همیشه برگ است","سریع‌تر است"],"ans":1,"why":"خاصیت BST می‌گوید چپ < ریشه < راست. جانشین میان‌ترتیب دقیقاً در این مرز قرار دارد؛ وقتی جایش را با گره حذفی عوض می‌کنی، همه نابرابری‌ها برقرار می‌مانند."}]'::jsonb),
('dsa-b8', 'dsa', 'هیپ و صف اولویت', 63, 17, '[{"k":"p","t":"هیپ درخت کاملی است که پدر همیشه از فرزند کوچک‌تر (یا بزرگ‌تر) است؛ ریشه همیشه کمینه است و درج/برداشت O(log n)."},{"k":"h","t":"خاصیت هیپ، نه ترتیب کامل"},{"k":"p","t":"هیپ درخت کاملی است که فقط یک رابطه را تضمین می‌کند: پدر ≤ فرزندان (در هیپ کمینه). همین یک رابطه کافی است تا ریشه همیشه کمینه باشد — چون برای رسیدن به هر گره باید از پدرش گذشت و پدر کوچک‌تر است. ولی هیپ بقیه عناصر را مرتب نمی‌کند؛ فقط «کمینه همیشه در دسترس» است. این تفاوت مهم است: هیپ برای «همیشه کوچک‌ترین را بده» است نه برای «همه را مرتب کن»."},{"k":"h","t":"heapify در O(n)؛ نه O(n log n)"},{"k":"p","t":"ساختن هیپ با heappushهای مکرر می‌شود O(n log n)، ولی heapify هوشمندانه از پایین به بالا عمل می‌کند: از آخرین پدر شروع و هر زیردرخت را sink می‌کند. چون بیشتر گره‌ها پایین‌اند و مسافت sinkشان کوتاه، جمع کل عملیات به O(n) می‌رسد. این یکی از آن تحلیل‌های ظریف است که نشان می‌دهد چرا heapq.heapify(list) را باید به‌جای pushهای مکرر برای ساخت اولیه بزنی."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"k عنصر بزرگ با هیپ کمینه","code":"import heapq\n\ndef top_k(nums, k):\n    h = []\n    for x in nums:\n        heapq.heappush(h, x)\n        if len(h) > k:\n            heapq.heappop(h)   # کوچک‌ترینِ فعلی را بینداز\n    return sorted(h, reverse=True)\n\n# h همیشه k بزرگ‌ترینِ دیده‌شده را نگه می‌دارد\n# پیچیدگی: O(n log k) — برای n بزرگ و k کوچک عالی\nprint(top_k([3, 9, 1, 7, 5], 3))  # [9, 7, 5]"},{"k":"tip","title":"نکته منتور","t":"برای گرفتن k بزرگ‌ترین از n عنصر، هیپ کمینه‌ی سایز k نگه دار و هر بار که بزرگ‌تر از k شد، کمینه را بینداز — این O(n log k) است و برای n میلیونی و k کوچک، خیلی بهتر از مرتب‌کردن کل O(n log n)."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["heapq پایتون هیپ کمینه در list پیاده می‌کند","heapify یک لیست را در O(n) هیپ می‌کند","برای k عنصر بزرگ و زمان‌بندی کار عالی است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"heap.py","code":"import heapq\nh = [5, 1, 8, 3]\nheapq.heapify(h)\nheapq.heappush(h, 0)\nprint(heapq.heappop(h))   # 0 — همیشه کمینه"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: heapq پایتون هیپ کمینه در list پیاده می‌کند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا ریشه هیپ همیشه کمینه است؟","opts":["تصادفی","خاصیت هیپ می‌گوید پدر ≤ فرزندان، پس ریشه از همه کوچک‌تر است","مرتب شده","هش شده"],"ans":1,"why":"با حفظ خاصیت هیپ در هر زیردرخت، کوچک‌ترین عنصر به ریشه می‌رسد."},{"q":"چرا هیپ برای صف اولویت مناسب‌تر از لیست مرتب است؟","opts":["مرتب‌تر است","چون درج و برداشت کمینه هر دو O(log n)‌اند؛ لیست مرتب برای درج باید O(n) شیفت بدهد","حافظه کمتر","ساده‌تر"],"ans":1,"why":"صف اولویت مدام درج و برداشتِ بهترین دارد. هیپ هر دو را log n انجام می‌دهد؛ لیست مرتب یا درجش O(n) است یا برداشتش. پس برای این الگوی دسترسی، هیپ متوازن‌تر است."},{"q":"آیا هیپ کمینه می‌تواند بگوید دومین عنصر کوچک‌تر از سومین است؟","opts":["بله","خیر — هیپ فقط رابطه پدر-فرزند را تضمین می‌کند، نه ترتیب بین برادرها یا زیردرخت‌ها","بستگی دارد","فقط در هیپ کامل"],"ans":1,"why":"خاصیت هیپ محلی است (پدر ≤ فرزند)؛ بین دو فرزندِ یک پدر یا بین زیردرخت‌ها هیچ تضمینی نیست. تنها چیزی که مطمئنی ریشه کمینه است — بقیه را باید pop کنی تا به ترتیب برسی."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('dsa-b9', 'dsa', 'گراف و روش‌های نمایش', 63, 18, '[{"k":"p","t":"گراف مجموعه گره و یال است. ماتریس مجاورت برای گراف متراکم و لیست مجاورت برای گراف پراکنده مناسب است — اکثر گراف‌های واقعی پراکنده‌اند."},{"k":"h","t":"دو نمایش و معیار انتخاب"},{"k":"p","t":"ماتریس مجاورت یک جدول V×V است که خانه [u][v] می‌گوید آیا یال هست — پس بررسی یال O(1) است ولی حافظه O(V²) می‌خواهد حتی اگر یال کم باشد. لیست مجاورت برای هر گره فقط همسایه‌هایش را نگه می‌دارد — حافظه O(V+E) و پیمایش همسایه‌ها سریع. چون اکثر گراف‌های واقعی پراکنده‌اند (یال‌ها خیلی کمتر از V²)، لیست مجاورت انتخاب پیش‌فرض است؛ ماتریس فقط وقتی گراف متراکم است یا خیلی «آیا یال هست؟» می‌پرسی."},{"k":"h","t":"گراف در پایتون؛ dict از لیست"},{"k":"p","t":"ساده‌ترین و رایج‌ترین نمایش در پایتون، dictای است که هر گره را به لیست همسایه‌هایش نگاشت می‌کند. این نمایش خوانا و انعطاف‌پذیر است و با .get(v, []) برای گره‌های بدون همسایه امن می‌شود. برای گراف وزن‌دار، همسایه‌ها را به‌جای گره، به‌صورت (همسایه، وزن) نگه می‌دار. این ساختار ساده، پایه الگوریتم‌های BFS و DFS و Dijkstra است که در درس‌های بعد می‌آیند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"گراف وزن‌دار به‌صورت لیست مجاورت","code":"# گراف وزن‌دار: هر همسایه یک (گره، وزن) است\ngraph = {\n    ''الف'': [(''ب'', 2), (''ج'', 5)],\n    ''ب'': [(''د'', 3)],\n    ''ج'': [(''د'', 1)],\n    ''د'': [],\n}\n\n# پیمایش همسایه‌ها با وزن:\nfor neighbor, weight in graph[''الف'']:\n    print(f''الف -> {neighbor} با هزینه {weight}'')\n\n# گره بدون همسایه، امن:\nprint(graph.get(''د'', []))  # []"},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["لیست مجاورت: dict از گره به لیست همسایه‌ها","ماتریس مجاورت O(1) برای بررسی یال ولی O(V²) حافظه","گراف جهت‌دار و بی‌جهت، وزن‌دار و بی‌وزن"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"graph.py","code":"graph = {\n    ''الف'': [''ب'', ''ج''],\n    ''ب'': [''الف'', ''د''],\n    ''ج'': [''الف''],\n    ''د'': [''ب''],\n}\nprint(graph[''ب''])   # همسایه‌های ب"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: لیست مجاورت: dict از گره به لیست همسایه‌ها بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"برای شبکه اجتماعی (گراف پراکنده) کدام نمایش بهتر است؟","opts":["ماتریس مجاورت","لیست مجاورت","هر دو برابرند","هیچ‌کدام"],"ans":1,"why":"در گراف پراکنده اکثر خانه‌های ماتریس خالی‌اند؛ لیست مجاورت فقط یال‌های موجود را نگه می‌دارد."},{"q":"برای شبکه اجتماعی با میلیون‌ها کاربر ولی دوستی‌های کمِ هر کاربر، کدام نمایش بهتر است؟","opts":["ماتریس مجاورت","لیست مجاورت — چون گراف پراکنده است و ماتریس میلیون‌ها خانه خالی O(V²) را هدر می‌دهد","هر دو","هیچ‌کدام"],"ans":1,"why":"هر کاربر چند صد دوست دارد ولی V² برای میلیون کاربر نجومی است. لیست مجاورت فقط یال‌های موجود را نگه می‌دارد، پس حافظه‌اش متناسب با دوستی‌های واقعی است نه مربع کاربران."},{"q":"برای نمایش گراف وزن‌دار در پایتون، همسایه‌ها را چطور نگه می‌داری؟","opts":["فقط نام همسایه","به‌صورت (همسایه، وزن) — تا هم مقصد و هم هزینه یال در دسترس باشد","در دو dict جدا","ممکن نیست"],"ans":1,"why":"گراف وزن‌دار برای الگوریتم‌هایی مثل Dijkstra به هزینه هر یال نیاز دارد؛ پس هر همسایه را به‌همراه وزنش در یک tuple نگه می‌داریم تا با یک پیمایش، هر دو را داشته باشیم."}]'::jsonb),
('dsa-b10', 'dsa', 'BFS و DFS روی گراف', 63, 19, '[{"k":"p","t":"BFS با صف لایه‌به‌لایه پیش می‌رود و کوتاه‌ترین مسیر در گراف بی‌وزن را می‌دهد؛ DFS با پشته عمیق می‌شود و برای تشخیص دور و مؤلفه‌ها خوب است."},{"k":"h","t":"BFS؛ لایه‌به‌لایه و کوتاه‌ترین مسیر"},{"k":"p","t":"BFS با یک صف کار می‌کند: شروع را در صف بگذار، و تا صف خالی نشده، گره را بردار، همسایه‌های ندیده‌اش را علامت بزن و به صف اضافه کن. چون همه هم‌لایه‌ها قبل از لایه بعد پردازش می‌شوند، اولین باری که به مقصد می‌رسی با کمترین تعداد یال رسیده‌ای — پس BFS در گراف بی‌وزن کوتاه‌ترین مسیر را می‌دهد. برای گراف وزن‌دار این تضمین نیست و باید Dijkstra بزنی."},{"k":"h","t":"DFS؛ عمق و تشخیص حلقه"},{"k":"p","t":"DFS تا جایی که می‌تواند عمیق می‌شود و وقتی به بن‌بست رسید برمی‌گردد (با stack یا بازگشت). این رفتار برای مسائل «همه را ببین» مناسب است: شمارش مؤلفه‌های همبند، تشخیص حلقه (اگر به گره‌ای در مسیر جاری برگردی، حلقه هست)، و مرتب‌سازی توپولوژیک. مجموعه visited در هر دو حیاتی است — بدون آن، در گراف دارای حلقه، پیمایش بی‌نهایت می‌شود."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"کوتاه‌ترین مسیر بی‌وزن با BFS","code":"from collections import deque\n\ndef shortest(g, start, end):\n    prev = {start: None}            # برای بازسازی مسیر\n    q = deque([start])\n    while q:\n        v = q.popleft()\n        if v == end:\n            # بازسازی مسیر از end به start\n            path, cur = [], end\n            while cur is not None:\n                path.append(cur); cur = prev[cur]\n            return path[::-1]\n        for w in g.get(v, []):\n            if w not in prev:\n                prev[w] = v; q.append(w)\n    return None                     # مسیر نیست"},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["BFS برای کوتاه‌ترین مسیر بی‌وزن و همسایگی","DFS برای تشخیص حلقه و شمارش مؤلفه","هر دو با مجموعه visited از بازدید تکراری جلوگیری می‌کنند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"bfs.py","code":"from collections import deque\ndef bfs(g, start):\n    seen = {start}\n    q = deque([start])\n    order = []\n    while q:\n        v = q.popleft()\n        order.append(v)\n        for w in g.get(v, []):\n            if w not in seen:\n                seen.add(w); q.append(w)\n    return order"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: BFS برای کوتاه‌ترین مسیر بی‌وزن و همسایگی بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"کدام پیمایش کوتاه‌ترین مسیر در گراف بی‌وزن را می‌دهد؟","opts":["DFS","BFS","هر دو","هیچ‌کدام"],"ans":1,"why":"BFS لایه‌به‌لایه دور می‌شود؛ پس اولین بار که به مقصد برسد با کمترین یال رسیده است."},{"q":"چرا BFS کوتاه‌ترین مسیر را در گراف بی‌وزن می‌دهد ولی در وزن‌دار نه؟","opts":["قرارداد","چون BFS بر اساس تعداد یال لایه‌بندی می‌کند؛ در گراف وزن‌دار مسیر با یال کمتر می‌تواند هزینه بیشتری داشته باشد","سرعت","حافظه"],"ans":1,"why":"در گراف بی‌وزن، کمترین یال = کمترین هزینه. ولی اگر یال‌ها وزن متفاوت دارند، یک مسیر ۳ یالیِ سبک می‌تواند بهتر از مسیر ۲ یالیِ سنگین باشد — و BFS این را نمی‌بیند. آنجا Dijkstra لازم است."},{"q":"نقش مجموعه visited چیست و اگر حذفش کنی چه می‌شود؟","opts":["برای سرعت","جلوگیری از بازدید تکراری؛ بدون آن در گراف حلقه‌دار، پیمایش بی‌نهایت می‌شود و هرگز تمام نمی‌شود","برای ترتیب","اختیاری است"],"ans":1,"why":"گراف می‌تواند حلقه داشته باشد؛ بدون علامت‌زدن گره‌های دیده‌شده، پیمایش دورِ حلقه می‌چرخد. visited تضمین می‌کند هر گره حداکثر یک‌بار پردازش شود و الگوریتم تمام شود."}]'::jsonb),
('dsa-b11', 'dsa', 'Trie و جست‌وجوی پیشوند', 63, 20, '[{"k":"p","t":"Trie درختی است که هر مسیر از ریشه تا گره، یک پیشوند است؛ برای تکمیل خودکار و جست‌وجوی پیشوندی O(L) که L طول کلمه است."},{"k":"h","t":"چرا پیشوند، ساختار می‌خواهد"},{"k":"p","t":"اگر بخواهی «همه کلماتی که با ''برن'' شروع می‌شوند» را پیدا کنی، گشتن همه کلمات O(n) است حتی با هش. Trie این را با ساختار حل می‌کند: حروف مشترک پیشوندها فقط یک‌بار ذخیره می‌شوند و مسیر از ریشه تا هر گره، یک پیشوند است. پس پیدا کردن همه کلمات با یک پیشوند یعنی پایین‌رفتن به گره آن پیشوند و پیمایش زیردرختش — مستقل از تعداد کل کلمات، وابسته فقط به طول پیشوند و تعداد جواب‌ها."},{"k":"h","t":"is_end؛ مرز کلمه و پیشوند"},{"k":"p","t":"در Trie، رسیدن به انتهای حروف یک کلمه لزوماً یعنی آن کلمه وجود دارد — شاید فقط پیشوند کلمه بلندتری باشد. پس هر گره یک پرچم is_end دارد که می‌گوید «اینجا یک کلمه کامل تمام می‌شود». هنگام جست‌وجوی کلمه، باید هم مسیر حروف وجود داشته باشد و هم is_end در انتها True باشد؛ وگرنه «بر» را در حضور «برنامه» به‌اشتباه کلمه مستقل می‌گیری."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"Trie با جست‌وجوی پیشوند","code":"class Trie:\n    def __init__(self):\n        self.children, self.end = {}, False\n\n    def add(self, w):\n        node = self\n        for c in w:\n            node = node.children.setdefault(c, Trie())\n        node.end = True\n\n    def all_with(self, prefix):\n        node = self\n        for c in prefix:                 # پایین برو تا گره پیشوند\n            if c not in node.children: return []\n            node = node.children[c]\n        out = []\n        def walk(n, path):               # حالا زیردرخت را جمع کن\n            if n.end: out.append(prefix + path)\n            for c, ch in n.children.items(): walk(ch, path + c)\n        walk(node, '''')\n        return out"},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["هر گره یک کاراکتر و فرزندان، حروف بعدی‌اند","پایان کلمه با یک پرچم is_end مشخص می‌شود","برای دیکشنری و پیشنهاد تایپ عالی است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"trie.py","code":"class Trie:\n    def __init__(self):\n        self.children = {}\n        self.end = False\n    def add(self, w):\n        node = self\n        for c in w:\n            node = node.children.setdefault(c, Trie())\n        node.end = True"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: هر گره یک کاراکتر و فرزندان، حروف بعدی‌اند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"پیچیدگی جست‌وجو در Trie به چه چیزی وابسته است؟","opts":["تعداد کل کلمات","طول کلمه جست‌وجوشده","اندازه الفبا","حافظه"],"ans":1,"why":"هر کاراکتر یک گام است؛ پس O(L) مستقل از اینکه چند هزار کلمه ذخیره شده."},{"q":"چرا Trie برای تکمیل خودکار بهتر از جدول هش است؟","opts":["سریع‌تر در همه‌چیز","چون هش فقط برابری کامل را در O(1) می‌گوید؛ «همه کلمات با این پیشوند» را نمی‌تواند — ولی Trie با ساختار درختی‌اش زیردرخت پیشوند را مستقیم می‌دهد","حافظه کمتر","ساده‌تر"],"ans":1,"why":"هش برای «هست یا نیست» عالی است ولی پیشوند را نمی‌فهمد — باید همه کلیدها را بگردی. Trie پیشوندهای مشترک را ساختار می‌دهد، پس جمع‌کردن همه کلماتِ یک پیشوند، یک پیمایش زیردرخت است."},{"q":"اگر is_end نداشته باشیم و فقط مسیر حروف باشد، چه خطایی رخ می‌دهد؟","opts":["حافظه","کلمات را با پیشوندهایشان قاطی می‌کنیم؛ مثلاً جست‌وجوی ''بر'' وقتی فقط ''برنامه'' هست، به‌اشتباه True می‌شود","کند می‌شود","ممکن نیست"],"ans":1,"why":"مسیرِ حروفِ ''بر'' در دل ''برنامه'' وجود دارد؛ بدون پرچم پایان، نمی‌توانی فرق بگذاری «اینجا یک کلمه تمام شده» یا «فقط وسط یک کلمه‌ام». is_end همین مرز را می‌سازد."}]'::jsonb),
('dsa-b12', 'dsa', 'انتخاب ساختار داده درست', 56, 21, '[{"k":"p","t":"انتخاب ساختار داده یعنی تطبیق عملیات پرتکرار برنامه با پیچیدگی هر ساختار. قبل از انتخاب بپرس: بیشتر چه کاری انجام می‌دهم؟"},{"k":"h","t":"سوال اول؛ عملیات غالب چیست"},{"k":"p","t":"انتخاب ساختار داده سلیقه نیست؛ یعنی ببینی برنامه‌ات بیشتر چه کاری انجام می‌دهد و ساختاری بگیری که همان کار را سریع‌تر کند. اگر دسترسی تصادفی با ایندکس غالب است، آرایه؛ اگر جست‌وجو با کلید، هش؛ اگر داده باید همیشه مرتب بماند، درخت متوازن. اشتباه رایج انتخاب بر اساس «کدام را بهتر بلدم» است — درحالی‌که معیار، پرتکرارترین عمل در حلقه داغ برنامه است."},{"k":"h","t":"هزینه‌های پنهان را هم ببین"},{"k":"p","t":"فقط پیچیدگی یک عمل را نبین؛ نوشتن و حافظه و کش را هم حساب کن. لیست پیوندی درج O(1) دارد ولی پیمایشش کش‌ناپذیر است و عملاً از آرایه کندتر درمی‌آید؛ هش O(1) میانگین دارد ولی مرتب نیست و حافظه بیشتری می‌خواهد. پس جدول پیچیدگی نقطه شروع است، نه پایان — بعد با اندازه واقعی داده و پروفایل، انتخاب را تأیید کن."},{"k":"h","t":"جدول مرجع"},{"k":"table","head":["نیاز غالب","ساختار پیشنهادی","چرا"],"rows":[["دسترسی با ایندکس","آرایه / list","O(1) و کش‌دوست"],["جست‌وجو/عضویت با کلید","جدول هش","میانگین O(1)"],["داده همیشه مرتب","درخت متوازن","درج/حذف/جست‌وجو O(log n)"],["کمینه/بیشینه زنده","هیپ","برداشت O(log n)، ریشه همیشه بهترین"],["پیشوند و تکمیل","Trie","وابسته به طول کلمه نه تعداد"]]},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["دسترسی تصادفی → آرایه / درج سر → لیست پیوندی","عضویت و نگاشت → هش / مرتب‌بودن → درخت","نوبت → صف / اولویت → هیپ / پیشوند → Trie"]},{"k":"h","t":"کاربرد و مقایسه"},{"k":"table","head":["نیاز","ساختار"],"rows":[["دسترسی با ایندکس","آرایه"],["جست‌وجوی کلید","جدول هش"],["داده مرتب زنده","BST متوازن"],["کوتاه‌ترین مسیر","گراف + BFS/Dijkstra"]]},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: دسترسی تصادفی → آرایه / درج سر → لیست پیوندی بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"اولین سوال قبل از انتخاب ساختار داده چیست؟","opts":["کدام جدیدتر است","کدام عملیات پرتکرارترین است","کدام کوتاه‌تر نوشته می‌شود","کدام محبوب‌تر است"],"ans":1,"why":"ساختار داده را بر اساس عملیات غالب انتخاب می‌کنی نه سلیقه؛ پرتکرارترین عمل باید سریع‌ترین باشد."},{"q":"اگر برنامه‌ات مدام «آیا این کاربر قبلاً دیده شده؟» می‌پرسد، کدام ساختار؟","opts":["لیست","جدول هش (set) — چون عضویت را میانگین O(1) می‌گوید؛ لیست باید O(n) بگردد","درخت","هیپ"],"ans":1,"why":"سوال غالب «عضویت» است و هش دقیقاً برای آن ساخته شده. لیست در هر پرسش همه را می‌گردد؛ با میلیون کاربر، تفاوت از میلی‌ثانیه به دقیقه می‌رسد."},{"q":"چرا با وجود درج O(1)، لیست پیوندی اغلب از آرایه کندتر است؟","opts":["باگ","چون گره‌ها پراکنده‌اند و کش CPU را خوب استفاده نمی‌کنند؛ آرایه داده فشرده و پیش‌خوانی‌شده دارد که در عمل خیلی سریع‌تر است","حافظه","ساده‌تر"],"ans":1,"why":"پیچیدگی نظری، هزینه کش و locality را نادیده می‌گیرد. پردازنده‌ها بلوک‌های پشت‌سرهم را خیلی سریع‌تر از اشاره‌گرهای پراکنده می‌خوانند؛ پس برای پیمایش، آرایه عملاً برنده است حتی اگر درجش O(n) باشد."}]'::jsonb),
('algo-r1', 'algo', 'جست‌وجوی دودویی؛ قدرتِ نصف‌کردن', 50, 1, '[{"k":"p","t":"پیدا کردن یک اسم در دفترچه تلفن هزار صفحه‌ای چقدر طول می‌کشد؟ اگر صفحه‌به‌صفحه بگردی، تا هزار قدم؛ ولی اگر هر بار دفترچه را نصف کنی، حدود ده قدم. این همان جهش از O(n) به O(log n) است — و جست‌وجوی دودویی ساده‌ترین راهی است که این جهش را با دست خودت تجربه می‌کنی."},{"k":"h","t":"چرا نصف‌کردن این‌قدر قدرتمند است"},{"k":"p","t":"هر بار که جست‌وجو را نصف می‌کنی، فضای باقی‌مانده را بر دو تقسیم کرده‌ای؛ پس تعداد قدم‌ها برابر است با چندبار «تقسیم بر دو» تا رسیدن به یک. برای یک میلیون عنصر این می‌شود حدود بیست مقایسه، نه یک میلیون. لگاریتم یعنی همین: تعداد دفعاتی که باید چیزی را نصف کنی. به همین دلیل هر الگوریتمی که در هر قدم مسئله را نصف (یا به‌طور کلی کوچک‌تر) کند، به‌طور چشمگیری از الگوریتم‌های خطی جلوتر است."},{"k":"h","t":"پیش‌شرط: داده مرتب"},{"k":"p","t":"جست‌وجوی دودویی فقط روی داده «مرتب» کار می‌کند، چون تصمیمِ «برو نیمه چپ یا راست» به مقایسه با عنصر وسط متکی است؛ اگر داده نامرتب باشد، بزرگ‌تر یا کوچک‌تر بودن وسط هیچ اطلاعاتی درباره محل هدف نمی‌دهد. پس هزینه جست‌وجوی دودویی، یک‌بار مرتب‌سازی O(n log n) است — که اگر بعد از آن چندین جست‌وجو انجام دهی، کاملاً می‌صرفد."},{"k":"h","t":"مرزها؛ جایی که باگ‌ها زندگی می‌کنند"},{"k":"p","t":"خود ایده جست‌وجوی دودویی چند خط است، ولی معروف است به اینکه پیاده‌سازیِ بدون‌باگش سخت است؛ چون همه‌چیز در مرزهاست: اینکه بازه بسته است یا نیمه‌باز، mid چطور حساب می‌شود تا سرریز نکند، و شرط خروج دقیقاً چیست. روش مطمئن، ثابت‌نگه‌داشتن یک «قرارداد بازه» از اول تا آخر است و تست‌کردن روی آرایه‌های کوچک و مرزی؛ مثل یک عنصر، دو عنصر، و هدفی که اول یا آخر است."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"binary_search.py","code":"def binary_search(arr, target):\n    lo, hi = 0, len(arr) - 1      # بازه بسته [lo, hi]\n    while lo <= hi:\n        mid = (lo + hi) // 2\n        if arr[mid] == target:\n            return mid\n        elif arr[mid] < target:\n            lo = mid + 1          # نیمه راست\n        else:\n            hi = mid - 1          # نیمه چپ\n    return -1                     # نیست\n\nnums = [2, 5, 8, 12, 16, 23, 38]\nprint(binary_search(nums, 23))    # 5\nprint(binary_search(nums, 7))     # -1"},{"k":"list","items":["قرارداد: بازه همیشه بسته است [lo, hi]؛ پس شرط حلقه lo <= hi و وقتی lo از hi رد شد یعنی بازه خالی شده.","اگر وسط کوچک‌تر از هدف بود، خود mid هم دیگر کاندید نیست؛ پس lo = mid + 1. این +1 و -1 همان مرزهایی‌اند که باگ از آن‌ها می‌آید.","برای جلوگیری از سرریز در زبان‌هایی مثل C، mid را به صورت lo + (hi - lo) // 2 حساب می‌کنند؛ در پایتون لازم نیست ولی دانستنش مفید است."]},{"k":"def","term":"O(log n)","t":"رشدی که در آن با چندبرابرشدن ورودی، هزینه فقط «یک واحد» زیاد می‌شود؛ چون در هر قدم مسئله تقسیم می‌شود. جست‌وجوی دودویی، درخت‌های دودویی متوازن و تقسیم‌وحل‌های یک‌شکافی همگی این رفتار را دارند و در مقیاس بزرگ تقریباً «رایگان» به‌نظر می‌رسند."},{"k":"table","head":["روش","پیش‌نیاز","پیچیدگی","کی استفاده کنیم"],"rows":[["خطی","ندارد","O(n)","داده کوچک یا نامرتب، یک‌بار"],["دودویی","مرتب بودن","O(log n)","چندین جست‌وجو روی داده ثابت"],["هش‌تیبل","کلید هش‌پذیر","O(1) میانگین","جست‌وجوی دقیقِ مکرر"]]},{"k":"warn","title":"دام رایج","t":"استفاده از جست‌وجوی دودویی روی داده نامرتب؛ کد اجرا می‌شود و گاهی حتی جواب درست می‌دهد، ولی تضمینی ندارد و در مواردی جواب غلط برمی‌گرداند. همیشه اول مطمئن شو داده مرتب است — یا از ابتدا ساختار مرتب نگه دار."},{"k":"tip","title":"نکته حرفه‌ای","t":"وقتی مسئله‌ات «کوچک‌ترین x که شرطی را برآورده می‌کند» است، حتی اگر آرایه‌ای در کار نیست، باز هم می‌توانی روی «فضای جواب» جست‌وجوی دودویی کنی؛ چون جواب‌ها معمولاً خاصیت یکنوا دارند: تا یک نقطه شرط برقرار نیست و بعد از آن هست."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["جست‌وجوی دودویی در هر قدم فضا را نصف می‌کند: O(log n)","پیش‌شرطش مرتب‌بودن داده است","یک قرارداد بازه را ثابت نگه دار و مرزها را دقیق بگذار","با داده‌های مرزیِ کوچک تست کن تا باگ‌های ±۱ لو بروند"]}]'::jsonb, '[{"q":"چرا جست‌وجوی دودویی O(log n) است؟","opts":["چون آرایه کوچک است","چون در هر قدم فضای جست‌وجو نصف می‌شود","چون کش دارد","چون مرتب است"],"ans":1,"why":"تعداد دفعات نصف‌کردن n تا رسیدن به ۱ برابر log n است؛ پس تعداد مقایسه‌ها هم همین قدر است."},{"q":"پیش‌شرط ضروری جست‌وجوی دودویی چیست؟","opts":["اندازه زوج","مرتب‌بودن داده","اعداد مثبت","بدون تکرار"],"ans":1,"why":"تصمیم چپ/راست به مقایسه با عنصر وسط متکی است و فقط روی داده مرتب معنا دارد."},{"q":"چرا lo = mid + 1 است نه lo = mid؟","opts":["سلیقه‌ای است","چون mid قبلاً بررسی شده و اگر جواب بود برمی‌گشتیم؛ ماندنش باعث حلقه بی‌پایان می‌شود","برای سرعت","برای حافظه"],"ans":1,"why":"اگر lo = mid بگذاری و فاصله دو عنصر باشد، mid همان lo می‌ماند و بازه هیچ‌وقت کوچک نمی‌شود."}]'::jsonb),
('algo-r2', 'algo', 'مرتب‌سازی؛ چرا مرج‌سورت قابل‌اتکاست', 55, 2, '[{"k":"p","t":"مرتب‌سازی اولین جایی است که «الگوریتم واقعاً اهمیت دارد» را می‌بینی: تفاوت یک مرتب‌سازی ساده با یک مرتب‌سازی خوب، روی داده بزرگ یعنی تفاوت بین چند ثانیه و چند ساعت. و در میان همه روش‌ها، مرج‌سورت به یک دلیل خاص می‌درخشد: رفتارش قابل‌پیش‌بینی است."},{"k":"h","t":"تقسیم و حل به زبان ساده"},{"k":"p","t":"ایده مرج‌سورت این است: مرتب‌کردن یک لیست بزرگ سخت است، ولی مرتب‌کردن دو لیست کوچکِ «از قبل مرتب» و ترکیبشان بسیار آسان است. پس لیست را نصف کن، هر نیمه را (بازگشتی) مرتب کن، و این دو نیمه مرتب را در یک گذر ادغام کن. ادغام فقط مقایسه سرِ دو لیست و برداشتن کوچک‌تر است؛ چون هر دو مرتب‌اند، این کار خطی و ساده است."},{"k":"h","t":"چرا همیشه O(n log n)"},{"k":"p","t":"عمق تقسیم‌ها log n است چون هر بار نصف می‌کنیم، و در هر سطح، کل کارِ ادغام روی همه عناصر n است؛ پس کل کار n × log n. نکته مهم این است که این تحلیل به شکلِ داده وابسته نیست — فرقی نمی‌کند داده از قبل مرتب باشد یا کاملاً برعکس، مرج‌سورت همان n log n را می‌دهد. همین «تضمین بدترین حالت» است که آن را برای داده‌های بزرگ و حساس به تأخیر قابل‌اتکا می‌کند؛ برخلاف QuickSort که معمولاً سریع‌تر است ولی در بدترین حالت به n² می‌افتد."},{"k":"h","t":"قیمتش: حافظه کمکی"},{"k":"p","t":"ادغام دو لیست به یک فضای کمکی به اندازه خود داده نیاز دارد؛ این بهای O(n) حافظه‌ای مرج‌سورت است. در مقابل، مرتب‌سازی‌های درجایی مثل HeapSort با حافظه O(1) کار می‌کنند. پس انتخاب بین این‌ها یک معامله کلاسیک است: مرج‌سورت سرعت قابل‌پیش‌بینی و «پایدار بودن» (حفظ ترتیب عناصر برابر) را می‌دهد و در عوض حافظه بیشتری می‌گیرد — معامله‌ای که در بیشتر سیستم‌های واقعی می‌صرفد."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"merge_sort.py","code":"def merge_sort(arr):\n    if len(arr) <= 1:            # پایه بازگشت\n        return arr\n    mid = len(arr) // 2\n    left  = merge_sort(arr[:mid])\n    right = merge_sort(arr[mid:])\n    return merge(left, right)\n\ndef merge(l, r):\n    out, i, j = [], 0, 0\n    while i < len(l) and j < len(r):\n        if l[i] <= r[j]:         # <= یعنی پایدار\n            out.append(l[i]); i += 1\n        else:\n            out.append(r[j]); j += 1\n    return out + l[i:] + r[j:]   # باقی‌مانده را بچسبان\n\nprint(merge_sort([38, 27, 43, 3, 9, 82, 10]))"},{"k":"list","items":["پایه بازگشت یعنی لیست تک‌عنصری از قبل مرتب است؛ بدون این شرط، بازگشت هیچ‌وقت متوقف نمی‌شود.","ادغام با دو اشاره‌گر i و j سرِ دو لیست را مقایسه می‌کند؛ چون هر دو مرتب‌اند، کوچک‌ترِ سرها همیشه کوچک‌ترِ باقی‌مانده‌هاست.","استفاده از <= (نه <) باعث «پایداری» می‌شود: عناصر برابر، ترتیب اولیه‌شان را حفظ می‌کنند؛ برای مرتب‌سازی چندمرحله‌ای (اول نام، بعد سن) حیاتی است."]},{"k":"def","term":"پایداری مرتب‌سازی","t":"مرتب‌سازی پایدار، ترتیب نسبی عناصری که کلیدشان برابر است را حفظ می‌کند. وقتی روی یک جدول چندبار با کلیدهای مختلف مرتب‌سازی می‌کنی، فقط با مرتب‌سازی پایدار نتیجه نهایی «مرتب بر اساس آخرین کلید، و در تساوی‌ها بر اساس کلید قبلی» می‌شود؛ مرج‌سورت پایدار و QuickSort معمولاً ناپایدار است."},{"k":"table","head":["الگوریتم","میانگین","بدترین حالت","حافظه","پایدار"],"rows":[["حبابی/درجی","O(n²)","O(n²)","O(1)","بله"],["مرج‌سورت","O(n log n)","O(n log n)","O(n)","بله"],["QuickSort","O(n log n)","O(n²)","O(log n)","خیر"],["HeapSort","O(n log n)","O(n log n)","O(1)","خیر"]]},{"k":"warn","title":"دام رایج","t":"انتخاب QuickSort برای داده‌ای که ممکن است از قبل مرتب یا تقریباً مرتب باشد و انتخاب pivot ضعیف (مثلاً همیشه اولین عنصر)؛ در این حالت QuickSort به O(n²) تنزل می‌کند. اگر تضمین بدترین حالت لازم داری، مرج‌سورت یا sort داخلی زبان (که ترکیبی و مقاوم است) انتخاب کن."},{"k":"tip","title":"نکته حرفه‌ای","t":"در عمل تقریباً همیشه باید از sort داخلی زبان استفاده کنی (مثل sorted در پایتون یا Arrays.sort در جاوا)؛ این‌ها الگوریتم‌های ترکیبیِ بهینه و تست‌شده‌اند. مرج‌سورت را با دست پیاده کن تا بفهمی، نه تا در تولید استفاده کنی."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["مرج‌سورت: نصف کن، مرتب کن، ادغام کن","همیشه O(n log n)؛ حتی در بدترین حالت","بهایش حافظه کمکی O(n) است","پایدار است؛ برای مرتب‌سازی چندکلیدی مهم است"]}]'::jsonb, '[{"q":"چرا مرج‌سورت همیشه O(n log n) است؟","opts":["چون سریع است","چون عمق تقسیم log n و کار هر سطح n است و این به شکل داده وابسته نیست","چون پایدار است","چون بازگشتی است"],"ans":1,"why":"تحلیل به ترتیب اولیه داده وابسته نیست؛ چه مرتب چه نامرتب، همان تعداد تقسیم و همان کار ادغام انجام می‌شود."},{"q":"مزیت کلیدی مرج‌سورت نسبت به QuickSort چیست؟","opts":["کمتر حافظه","تضمین O(n log n) در بدترین حالت","درجا بودن","سادگی کد"],"ans":1,"why":"QuickSort در بدترین حالت O(n²) می‌شود ولی مرج‌سورت این تضمین را همیشه نگه می‌دارد."},{"q":"پایداری مرتب‌سازی یعنی چه و چرا مهم است؟","opts":["سرعت ثابت؛ برای کش","حفظ ترتیب عناصر برابر؛ برای مرتب‌سازی چندمرحله‌ای با چند کلید","کمتر حافظه؛ برای موبایل","هیچ"],"ans":1,"why":"وقتی چندبار با کلیدهای مختلف مرتب می‌کنی، پایداری تضمین می‌کند ترتیبِ کلیدهای قبلی در تساوی‌ها حفظ شود."}]'::jsonb),
('c4-l1', 'algo', 'جست‌وجو؛ از خطی تا دودویی', 45, 3, '[{"k":"p","t":"جست‌وجوی خطی ساده است: از اول تا آخر نگاه کن. اما وقتی داده مرتب باشد، راه بسیار بهتری هست: هر بار وسط را ببین و نیمی را حذف کن. برای یک میلیارد عنصر، جست‌وجوی خطی تا یک میلیارد مقایسه لازم دارد؛ دودویی حداکثر ۳۰ تا!"},{"k":"code","lang":"py","title":"binary_search.py","code":"def binary_search(items, target):\n    lo, hi = 0, len(items) - 1\n    while lo <= hi:\n        mid = (lo + hi) // 2\n        if items[mid] == target:\n            return mid\n        if items[mid] < target:\n            lo = mid + 1        # نیمه راست\n        else:\n            hi = mid - 1        # نیمه چپ\n    return -1\n\nnums = [2, 5, 8, 12, 16, 23, 38, 56, 72, 91]\nprint(binary_search(nums, 23))   # 5"},{"k":"visual","visual":"binarySearch","title":"شبیه‌ساز: جست‌وجوی دودویی"},{"k":"warn","title":"شرط حیاتی","t":"جست‌وجوی دودویی فقط روی داده مرتب‌شده جواب می‌دهد. اگر داده نامرتب است و فقط یک بار جست‌وجو می‌کنی، مرتب‌کردن + دودویی (O(n log n)) از جست‌وجوی خطی (O(n)) بدتر است؛ اما برای جست‌وجوهای مکرر می‌ارزد."},{"k":"def","term":"Invariant","t":"شرطی که در تمام طول اجرای حلقه برقرار می‌ماند؛ مثلاً «اگر target وجود داشته باشد، بین lo و hi است». اثبات Invariant، روش ریاضی اثبات درستی الگوریتم‌های حلقه‌ای است."},{"k":"tip","title":"نکته منتور","t":"حتی اگر کتابخانه جست‌وجو داری، دودویی را یک بار با دست بنویس و با تست‌های مرزی (لیست خالی، عنصر اول، عنصر آخر، عنصر ناموجود) امتحان کن — خطاهای Off-by-one اینجا کمین کرده‌اند."},{"k":"h","t":"عمیق‌تر: جست‌وجوی دودویی فراتر از آرایه"},{"k":"p","t":"جست‌وجوی دودویی فقط یک الگوریتم نیست — یک «طرز فکر» است: هر بار که بتوانی پاسخ‌های نامعتبر را نصف کنی، داری جست‌وجوی دودویی می‌کنی، حتی بدون آرایه! می‌خواهی کوچک‌ترین پهنای باندی را پیدا کنی که ویدیو بدون لگ پخش می‌شود؟ به‌جای تست ۱۰۰ مقدار، با ۷ بار تست (log₂100 ≈ 7) پیدایش می‌کنی. پیدا کردن اولین نسخه‌ای که باگ دارد بین ۱۰۰۰ کامیت؟ git bisect دقیقاً همین کار را با جست‌وجوی دودویی روی تاریخچه انجام می‌دهد. هرجا یک ویژگی «مرزی» وجود دارد (قبلش نه، بعدش بله)، جست‌وجوی دودویی پنهان است."},{"k":"p","t":"دو واریانت مهمش را حتماً بشناس: «اولین رخداد» وقتی داده تکراری دارد و «کوچک‌ترین عنصر بزرگ‌تر یا مساوی» که در بازه‌های زمانی و رزرواسیون کاربرد دارد. کتابخانه bisect پایتون این‌ها را آماده دارد: bisect_left اولین جای ممکن برای درج مرتب را برمی‌گرداند و عملاً هر دو واریانت را پوشش می‌دهد. اما تله معروفش را بدان: آرایه حتماً باید مرتب باشد، و اگر شرط مرزی اشتباه نوشته شود، حلقه infinite می‌شود یا خانه‌ای را جا می‌اندازد — به همین دلیل تست‌های مرزی (خالی، تک‌عنصر، اول و آخر) در این الگوریتم واجب‌اند."},{"k":"code","lang":"py","title":"deepdive-bisect.py","code":"from bisect import bisect_left, insort\n\nversions = [''1.0'', ''1.2'', ''1.2'', ''1.5'', ''2.0'']\n\n# اولین رخداد «1.2»:\ni = bisect_left(versions, ''1.2'')\nprint(i)                         # 1 — نه 2!\n\n# رزرواسیون: اولین اسلات بعد از ساعت ۱۴:۳۰\nslots = [9*60, 10*60, 13*60, 15*60, 16*60]\nj = bisect_left(slots, 14*60 + 30)\nprint(f''اسلات بعدی: {slots[j] // 60}:{slots[j] % 60:02d}'')  # 15:00\n\n# درج با حفظ ترتیب — بدون مرتب‌سازی دوباره:\ninsort(slots, 12*60)\nprint(slots)   # [540, 600, 720, 780, 900, 960]\n\n# git bisect — جست‌وجوی دودویی روی تاریخچه:\n# git bisect start\n# git bisect bad            ← نسخه فعلی باگ دارد\n# git bisect good v1.0      ← این نسخه سالم بود\n# ... گیت وسط را checkout می‌کند، تو می‌گویی خوب/بد\n# در ~۱۰ قدم، کامیتِ مقصر بین ۱۰۰۰ کامیت پیدا می‌شود!"},{"k":"warn","title":"تله off-by-one","t":"بیشتر باگ‌های جست‌وجوی دودویی در مرزهاست: حلقه باید تا lo <= hi ادامه یابد، mid باید lo + (hi - lo) // 2 محاسبه شود (نه (lo+hi)//2 که در زبان‌های ثابت‌نوع سرریز می‌کند) و بعد از هر مقایسه، lo = mid + 1 یا hi = mid - 1. این سه خط را مثل ورد حفظ کن و همیشه حالت‌های مرزی را تست کن."}]'::jsonb, '[{"q":"حداکثر چند مقایسه برای یافتن عنصر در آرایه مرتب ۱٬۰۴۸٬۵۷۶ تایی لازم است؟","opts":["۱٬۰۴۸٬۵۷۶","حدود ۵۲۴ هزار","۲۰","۳۲"],"ans":1,"why":"log2(1048576) = 20؛ هر مقایسه فضا را نصف می‌کند، پس حداکثر ۲۰ مقایسه لازم است — نه ۲۰ هزار!"},{"q":"اگر items[mid] > target باشد چه باید کرد؟","opts":["lo = mid + 1","hi = mid - 1","mid += 1","برگرداندن -1"],"ans":1,"why":"چون آرایه مرتب است، همه عناصر سمت راست mid هم از target بزرگ‌ترند؛ پس جست‌وجو به نیمه چپ محدود می‌شود."}]'::jsonb),
('c4-l2', 'algo', 'مرتب‌سازی؛ حبابی تا مرج', 65, 4, '[{"k":"p","t":"حبابی را یاد می‌گیریم تا بفهمیم چرا نباید استفاده شود: O(n²) و کند حتی برای داده‌های کوچک. مرج‌سورت اما الگوی «تقسیم و حل» را نشان می‌دهد: آرایه را نصف کن، هر نیمه را مرتب کن و با یک ادغام هوشمندانه O(n) نتیجه را بساز — مجموعاً O(n log n)."},{"k":"code","lang":"py","title":"merge_sort.py","code":"def merge_sort(items):\n    if len(items) <= 1:            # حالت پایه\n        return items\n    mid = len(items) // 2\n    left = merge_sort(items[:mid])   # تقسیم\n    right = merge_sort(items[mid:])\n    return merge(left, right)        # حل\n\ndef merge(a, b):\n    out, i, j = [], 0, 0\n    while i < len(a) and j < len(b):\n        if a[i] <= b[j]:\n            out.append(a[i]); i += 1\n        else:\n            out.append(b[j]); j += 1\n    return out + a[i:] + b[j:]"},{"k":"visual","visual":"recursionTree","title":"شبیه‌ساز: درخت فراخوانی"},{"k":"table","head":["الگوریتم","بهترین","میانگین","حافظه"],"rows":[["حبابی","O(n)","O(n²)","O(1)"],["درجی","O(n)","O(n²)","O(1)"],["مرج","O(n log n)","O(n log n)","O(n)"],["سریع (Quick)","O(n log n)","O(n log n)","O(log n)"]]},{"k":"tip","title":"نکته منتور","t":"در عمل پایتون از Timsort استفاده می‌کند — ترکیبی از مرج و درجی که از مرتب‌بودن نسبی داده‌های واقعی بهره می‌برد. دانستن الگوریتم پایه برای درک ابزارهایی مثل این است، نه برای بازنویسی‌شان."},{"k":"h","t":"عمیق‌تر: از درخت فراخوانی تا Memoization واقعی"},{"k":"p","t":"درخت فراخوانی فیبوناچی یک درس بزرگ دارد: تعداد گره‌هایش نمایی است، ولی تعداد «مسائل متمایز» فقط n تا. یعنی درخت دارد یک سوال را هزار بار از اول جواب می‌دهد. Memoization یعنی جواب هر سوال را اولین بار در یک جدول ذخیره کنی و دفعه‌های بعد فقط نگاه کنی — درخت نمایی به یک زنجیره خطی تبدیل می‌شود. این فقط «ترفند سرعت» نیست؛ شیوه تفکر است: هر جا دیدی یک تابع با ورودی مشابه بارها صدا می‌شود، آنجا کشِ نتایج جواب است. و قاعده طلایی طراحی: اول نسخه بازگشتی ساده و درست را بنویس، بعد با یک جدول، تکرارها را حذف کن — نه از اول به دنبال راه‌حل هوشمندانه بگرد."},{"k":"code","lang":"py","title":"سه نسخه، سه سرنوشت","code":"def fib_naive(n):                    # O(2^n) — برای n=40 دقیقه‌ها\n    return n if n < 2 else fib_naive(n - 1) + fib_naive(n - 2)\n\nfrom functools import lru_cache\n\n@lru_cache(maxsize=None)             # Memoization در یک خط\ndef fib_memo(n):                     # O(n)\n    return n if n < 2 else fib_memo(n - 1) + fib_memo(n - 2)\n\ndef fib_iter(n):                      # O(n) و O(1) حافظه\n    a, b = 0, 1\n    for _ in range(n):\n        a, b = b, a + b\n    return a\n\nimport time\nfor f, name in [(fib_memo, ''memo''), (fib_iter, ''iter'')]:\n    t0 = time.perf_counter()\n    f(3000)\n    print(name, round((time.perf_counter() - t0) * 1000, 2), ''ms'')"},{"k":"warn","title":"مرز بازگشت","t":"بازگشت در پایتون سقف عمق دارد (به‌طور پیش‌فرض حدود ۱۰۰۰ قاب) و هر قاب هزینه حافظه دارد. برای nهای بزرگ، نسخه تکراری نه تنها سریع‌تر که امن‌تر است. قاعده: بازگشت وقتی درخت مسئله واقعاً شاخه‌دار است (مثل پیمایش فایل‌ها یا تجزیه عبارت)؛ وگرنه حلقه ساده قابل‌پیش‌بینی‌تر است."}]'::jsonb, '[{"q":"چرا ادغام دو لیست مرتب O(n) است؟","opts":["چون لیست‌ها کوچک‌اند","چون هر عنصر دقیقاً یک بار مقایسه و کپی می‌شود","چون از هش استفاده می‌کند","چون بازگشتی است"],"ans":1,"why":"دو اشاره‌گر جلو می‌روند و هر عنصر بدون بازگشت به عقب، یک بار وارد خروجی می‌شود؛ پس کل کار متناسب با n است."},{"q":"کجا مرتب‌سازی درجی از مرج بهتر است؟","opts":["داده خیلی بزرگ","داده تقریباً مرتب و کوچک","داده کاملاً برعکس","هیچ‌وقت"],"ans":1,"why":"درجی روی داده تقریباً مرتب نزدیک O(n) است و سربار بازگشت ندارد؛ به همین دلیل Timsort برای قطعه‌های کوچک از آن استفاده می‌کند."}]'::jsonb),
('c4-l3', 'algo', 'بازگشت و تقسیم و حل', 55, 5, '[{"k":"p","t":"بازگشت یعنی تابعی که خودش را صدا می‌زند؛ قدرتش از دو بخش می‌آید: حالت پایه که توقف را تضمین می‌کند و گام بازگشتی که مسئله را به نمونه کوچک‌تر همان مسئله تقلیل می‌دهد. درخت فراخوانی را روی کاغذ بکش تا بازگشت از جادو به ابزار تبدیل شود."},{"k":"code","lang":"py","title":"recursion.py","code":"def factorial(n):\n    if n <= 1:              # حالت پایه\n        return 1\n    return n * factorial(n - 1)\n\ndef sum_digits(n):\n    if n < 10:\n        return n\n    return n % 10 + sum_digits(n // 10)\n\nprint(factorial(6))     # 720\nprint(sum_digits(4821)) # 15"},{"k":"warn","title":"خطر سرریز","t":"هر فراخوانی بازگشتی یک فریم روی Call Stack می‌گذارد؛ بازگشت عمیق (مثلاً factorial(10000)) در پایتون خطای RecursionError می‌دهد. برای مسائل عمیق یا از بازگشت دم‌بهینه‌شده در زبان‌های مناسب استفاده کن یا به حلقه تبدیلش کن."},{"k":"def","term":"Divide & Conquer","t":"الگویی سه‌مرحله‌ای: تقسیم مسئله به زیرمسئله‌های مستقل، حل بازگشتی هرکدام و ترکیب نتایج. مرج‌سورت، جست‌وجوی دودویی و ضرب سریع ماتریس‌ها همه از این خانواده‌اند."},{"k":"tip","title":"نکته منتور","t":"برای طراحی تابع بازگشتی اول حالت پایه را بنویس، بعد فرض کن تابع برای ورودی کوچک‌تر درست کار می‌کند (فرض استقرا) و فقط «یک قدم» را بنویس. این ذهنیت، ۹۰٪ سختی بازگشت را حل می‌کند."},{"k":"h","t":"عمیق‌تر: هنر تعریف زیرمسئله — قلب برنامه‌ریزی پویا"},{"k":"p","t":"بیشتر کسانی که در DP گیر می‌کنند، دنبال «فرمول» می‌گردند؛ ولی فرمول نتیجه است، نه شروع. شروع، تعریف دقیق زیرمسئله است: «بهترین ارزش کوله با i آیتم اول و ظرفیت w». وقتی این جمله را داری، رابطه بازگشتی خودش ظاهر می‌شود: یا آیتم i را برنمی‌داری (جواب i-1 با همان w) یا برمی‌داری (جواب i-1 با w منهای وزن آیتم، به‌علاوه ارزشش) — و بزرگ‌ترِ این دو، جواب است. همه مسائل DP از همین سه گام می‌آیند: ۱) تعریف زیرمسئله به‌شکل یک جمله کامل ۲) نوشتن رابطه بر اساس انتخاب‌ها ۳) مشخص‌کردن ترتیب پرکردن جدول طوری که هر خانه هنگام محاسبه، وابستگی‌هایش آماده باشند."},{"k":"p","t":"دو الگوی رایج را بشناس: «خطی» مثل ویرایش فاصله (Levenshtein) که جدولش دوبعدیِ متن×متن است و «کیسه‌ای» مثل کوله‌پشتی. و مهم‌تر از همه، معیار تشخیص: DP فقط وقتی جواب است که مسئله دو خاصیت داشته باشد — زیرساختار بهینه (جواب کل از جواب زیرمسئله‌ها ساخته شود) و زیرمسئله‌های هم‌پوشان (همان زیرمسئله بارها تکرار شود). اگر هم‌پوشانی نیست، «تقسیم و حل» کافی است؛ و اگر زیرساختار بهینه نیست (مثل یافتن بلندترین مسیر ساده در گراف)، DP اصلاً درست کار نمی‌کند — و دانستن این مرزها از حفظ‌کردن فرمول مهم‌تر است."},{"k":"table","head":["سوال طراحی","مثال در کوله‌پشتی"],"rows":[["زیرمسئله چیست؟","بهترین ارزش با i آیتم اول و ظرفیت w"],["در هر قدم چه انتخابی دارم؟","برداشتن یا برنداشتن آیتم i"],["وابستگی هر خانه به کجاست؟","(i-1, w) و (i-1, w - وزن آیتم)"],["ترتیب پرکردن؟","سطر به سطر، ظرفیت صعودی"],["جواب نهایی کجاست؟","آخرین خانه: (n, W)"]]}]'::jsonb, '[{"q":"بدون حالت پایه چه اتفاقی می‌افتد؟","opts":["تابع صفر برمی‌گرداند","بازگشت بی‌نهایت و سرریز پشته","کامپایلر خطا می‌دهد","حلقه جایگزین می‌شود"],"ans":1,"why":"بدون شرط توقف، تابع تا ابد خودش را صدا می‌زند تا حافظه Call Stack پر شود — RecursionError در پایتون."},{"q":"کدام مسئله ذاتاً بازگشتی نیست؟","opts":["پیمایش درخت","محاسبه فاکتوریل","جست‌وجوی دودویی","جمع دو عدد ثابت"],"ans":3,"why":"جمع دو عدد یک عملیات مستقیم است؛ نیازی به کاهش به زیرمسئله ندارد."}]'::jsonb),
('algo-x1', 'algo', 'جست‌وجوی دودویی — قدرتمندترین الگوریتم ۱۰ خطی', 45, 6, '[{"k":"p","t":"جست‌وجوی دودویی فقط یک ترفند نیست؛ یک طرز فکر است: وقتی فضا «مرتب» یا «یکنوا» باشد، هر بررسی می‌تواند نصف احتمالات را حذف کند. پیدا کردن یک نام در دفترچه تلفن ۴ میلیارد نفری؟ حداکثر ۳۳ مقایسه. به همین دلیل log n زیباترین منحنی مهندسی است."},{"k":"visual","visual":"binarySearch","title":"شبیه‌ساز: جست‌وجوی دودویی قدم به قدم"},{"k":"code","lang":"py","title":"binary_search.py","code":"def binary_search(arr: list[int], target: int) -> int:\n    lo, hi = 0, len(arr) - 1\n    while lo <= hi:\n        mid = (lo + hi) // 2        # مواظب سرریز در زبان‌های دیگر!\n        if arr[mid] == target:\n            return mid\n        if arr[mid] < target:\n            lo = mid + 1            # نصف چپ حذف شد\n        else:\n            hi = mid - 1            # نصف راست حذف شد\n    return -1\n\nnums = [3, 7, 12, 18, 24, 31, 38, 45]\nprint(binary_search(nums, 31))   # 5\nprint(binary_search(nums, 32))   # -1"},{"k":"warn","title":"سه باگ کلاسیک","t":"۱) شرط حلقه: lo <= hi نه lo < hi. ۲) به‌روزرسانی: lo = mid + 1 نه mid (ورنه حلقه بی‌نهایت). ۳) محاسبه mid: در جاوا از lo + (hi - lo) / 2 استفاده کن تا مجموع سرریز نکند. این سه، ۹۰٪ اشتباهات پیاده‌سازی‌اند."},{"k":"h","t":"فراتر از آرایه: جست‌وجو روی جواب"},{"k":"p","t":"قدرت واقعی: هرگاه پاسخ «یکنوا» باشد — یعنی یک نقطه مرزی وجود داشته باشد که قبلش همه False و بعدش همه True — می‌توانی روی خودِ جواب جست‌وجوی دودویی کنی، حتی بدون آرایه! مثال: «کوچک‌ترین عددی که مربعش از یک میلیارد بیشتر است»."},{"k":"code","lang":"py","title":"جست‌وجو روی جواب","code":"def smallest_square_above(limit: int) -> int:\n    # کوچک‌ترین x که x*x > limit\n    lo, hi = 0, limit\n    while lo < hi:\n        mid = (lo + hi) // 2\n        if mid * mid > limit:\n            hi = mid          # جواب هست، شاید کوچک‌تر هم باشد\n        else:\n            lo = mid + 1      # قطعا جواب نیست\n    return lo\n\nprint(smallest_square_above(10**9))  # 31623"},{"k":"tip","title":"نکته منتور","t":"در کتابخانه‌ها چرخ را دوباره نساز: bisect پایتون، Arrays.binarySearch جاوا و std::lower_bound در C++ همه آماده‌اند — ولی پیاده‌سازی دستی را یک‌بار بنویس تا منطق مرزها ملکه ذهنت شود."}]'::jsonb, '[{"q":"حداکثر چند مقایسه برای ۱ میلیون عنصر لازم است؟","opts":["۱ میلیون","حدود ۲۰ (log2 یک میلیون)","۵۰۰ هزار","بستگی به داده دارد"],"ans":1,"why":"log2(1,000,000) ≈ 19.9 — هر مقایسه فضا را نصف می‌کند، پس ۲۰ بار نصف‌کردن از یک میلیون به یک می‌رسد."},{"q":"جست‌وجوی دودویی روی جواب چه زمانی کاربرد دارد؟","opts":["فقط برای آرایه مرتب","هرجا خاصیت یکنوایی باشد: قبل از مرز False، بعد از مرز True","فقط برای رشته‌ها","هیچ‌وقت"],"ans":1,"why":"این تعمیم، بزرگ‌ترین ابزار حل مسئله است: تابع هدف را ارزیابی کن و نیمه غلط را دور بریز — حتی اگر آرایه‌ای وجود نداشته باشد."}]'::jsonb)
